import React, { FC, createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";

import { DAY, NOW } from "../mockData";
import { TimeWindow, previousWindow } from "../selectors";
import { StripeIdentity, StripeWorkflowError } from "./stripeTypes";
import { StripePaymentRow, mapCharge } from "./chargeModel";
import { buildCustomerSearchRequest, CUSTOMERS_PER_QUERY } from "./chargeQuery";
import { searchCharges } from "./stripeWorkflowClient";
import { useStripeIdentity } from "./useStripeIdentity";
import { OrgCustomers, fetchOrgCustomers } from "./orgCustomers";

/** Stripe's maximum page size for search. */
export const SWEEP_LIMIT = 100;
/** Pages read per customer chunk before the figures are flagged as partial. */
export const MAX_PAGES_PER_CHUNK = 10;
const DEBOUNCE_MS = 400;

/**
 * 90 days rather than the ledger's 365: the sweep also covers the
 * previous period. The picker widens it.
 */
export const DEFAULT_STRIPE_RANGE: TimeWindow = { from: NOW - 90 * DAY, to: NOW };

interface WindowKey {
  from: number;
  to: number;
  userId: string;
  cudbServiceId: string;
  customers: string;
}

const keyOf = (key: WindowKey) => `${key.from}|${key.to}|${key.userId}|${key.cudbServiceId}|${key.customers}`;

export interface StripeWindowState {
  identity: StripeIdentity | null;
  /** What the range pickers show, shared by every Stripe screen. */
  range: TimeWindow;
  /** The same length immediately before `range`, for the comparisons. */
  previous: TimeWindow;
  setRange: (range: TimeWindow) => void;
  /** The organisation's Stripe customers; null until read. */
  customers: OrgCustomers | null;
  /** The organisation is known and has no Stripe customer at all. */
  noCustomers: boolean;
  /** Every charge of the organisation's customers created between `previous.from` and `range.to`. */
  rows: StripePaymentRow[];
  currentRows: StripePaymentRow[];
  previousRows: StripePaymentRow[];
  loading: boolean;
  progress: { chunks: number; chunksTotal: number; charges: number };
  /** A customer chunk hit `MAX_PAGES_PER_CHUNK` with more charges left; the totals are partial. */
  truncated: boolean;
  error: StripeWorkflowError | null;
  loadedAt: number | null;
  /** Any charge on the page is in live mode. */
  live: boolean;
  refresh: () => void;
  /** Swaps one row in place after a refund or a detail reload. */
  replaceRow: (row: StripePaymentRow) => void;
}

interface ContextValue extends StripeWindowState {
  register: () => () => void;
}

const StripeWindowContext = createContext<ContextValue | null>(null);

/**
 * The organisation's Stripe charges, shared by every screen that reads
 * them.
 *
 * Stripe is one account for the whole platform and charges carry no
 * organisation id, so the organisation's charges are those of its
 * users' Stripe customers (`orgCustomers.ts`). Stripe search allows at
 * most ten filters per query and no mixing of OR with AND, and the
 * workflow appends an AND date clause whenever dates are sent; so the
 * sweep runs one `customer:'…' OR …` query per chunk of ten customers,
 * without dates, and keeps the window's dates client-side. Results come
 * newest first, so a chunk stops paging once a whole page predates the
 * window.
 *
 * The range and the rows live here rather than in the screens, which
 * unmount when the rail switches: moving between screens keeps the date
 * and never refetches, and one range change costs one sweep.
 */
export const StripeWindowProvider: FC = ({ children }) => {
  const identity = useStripeIdentity();
  const [range, setRangeState] = useState<TimeWindow>(DEFAULT_STRIPE_RANGE);
  const [customers, setCustomers] = useState<{ serviceId: string; data: OrgCustomers } | null>(null);
  const [customersError, setCustomersError] = useState<StripeWorkflowError | null>(null);
  const [cache, setCache] = useState<{ key: string; rows: StripePaymentRow[] } | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState({ chunks: 0, chunksTotal: 0, charges: 0 });
  const [truncated, setTruncated] = useState(false);
  const [error, setError] = useState<StripeWorkflowError | null>(null);
  const [loadedAt, setLoadedAt] = useState<number | null>(null);
  const [consumers, setConsumers] = useState(0);

  const seq = useRef(0);
  const mounted = useRef(true);
  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inflightKey = useRef<string | null>(null);
  const customersFor = useRef<string | null>(null);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      if (debounce.current) clearTimeout(debounce.current);
    };
  }, []);

  const previous = useMemo(() => previousWindow(range), [range]);

  /* The organisation's customers, once per organisation. */
  useEffect(() => {
    if (!identity || consumers === 0) return;
    if (customersFor.current === identity.cudbServiceId) return;
    customersFor.current = identity.cudbServiceId;
    const serviceId = identity.cudbServiceId;
    fetchOrgCustomers({ serviceId, connectionId: "" })
      .then((data) => {
        if (!mounted.current) return;
        setCustomers({ serviceId, data });
        setCustomersError(null);
      })
      .catch((e: any) => {
        if (!mounted.current) return;
        customersFor.current = null;
        setCustomersError({ kind: "network", message: e?.message || "The organisation's users could not be read" });
      });
  }, [identity, consumers]);

  const orgCustomers = customers && identity && customers.serviceId === identity.cudbServiceId ? customers.data : null;
  const customersHash = orgCustomers ? orgCustomers.customerIds.slice().sort().join(",") : "";
  const noCustomers = !!orgCustomers && orgCustomers.customerIds.length === 0;

  const wantedKey = useMemo<WindowKey | null>(
    () =>
      identity && orgCustomers
        ? { from: previous.from, to: range.to, userId: identity.userId, cudbServiceId: identity.cudbServiceId, customers: customersHash }
        : null,
    [identity, orgCustomers, customersHash, previous.from, range.to]
  );
  const wanted = wantedKey ? keyOf(wantedKey) : null;

  const sweep = useCallback(
    async (key: WindowKey, ids: string[]) => {
      const id = keyOf(key);
      const mine = ++seq.current;
      inflightKey.current = id;
      setLoading(true);
      setError(null);
      setTruncated(false);

      const chunks: string[][] = [];
      for (let i = 0; i < ids.length; i += CUSTOMERS_PER_QUERY) chunks.push(ids.slice(i, i + CUSTOMERS_PER_QUERY));
      setProgress({ chunks: 0, chunksTotal: chunks.length, charges: 0 });

      const acc: StripePaymentRow[] = [];
      let hitCap = false;
      const identityNow = { userId: key.userId, cudbServiceId: key.cudbServiceId };

      for (let c = 0; c < chunks.length; c += 1) {
        let page: string | undefined;
        let pages = 0;
        for (;;) {
          const result = await searchCharges(identityNow, buildCustomerSearchRequest(chunks[c], SWEEP_LIMIT, page));
          /* A newer sweep has started, or the provider is gone: drop this reply. */
          if (!mounted.current || mine !== seq.current) return;
          if (result.ok === false) {
            inflightKey.current = null;
            setLoading(false);
            setError(result.error);
            setCache({ key: id, rows: [] });
            return;
          }
          const mapped = (result.data.data || []).map(mapCharge);
          mapped.forEach((row) => {
            if (row.createdAt >= key.from && row.createdAt <= key.to) acc.push(row);
          });
          pages += 1;
          setProgress({ chunks: c, chunksTotal: chunks.length, charges: acc.length });
          /* Newest first: once a whole page predates the window, the rest of the chunk does too. */
          const allOlder = mapped.length > 0 && mapped.every((row) => row.createdAt < key.from);
          if (allOlder || !result.data.has_more || !result.data.next_page) break;
          if (pages >= MAX_PAGES_PER_CHUNK) {
            hitCap = true;
            break;
          }
          page = result.data.next_page;
        }
        setProgress({ chunks: c + 1, chunksTotal: chunks.length, charges: acc.length });
      }

      /* One charge can match several of the organisation's customers only by accident; keep each once. */
      const unique = new Map<string, StripePaymentRow>();
      acc.forEach((row) => unique.set(row.id, row));

      inflightKey.current = null;
      setCache({ key: id, rows: Array.from(unique.values()) });
      setTruncated(hitCap);
      setLoading(false);
      setLoadedAt(Date.now());
    },
    []
  );

  /* A consumer on screen, the organisation's customers known, and a window we do not have yet: sweep it after the debounce. */
  useEffect(() => {
    if (consumers === 0 || !wantedKey || !wanted || !orgCustomers) return;
    if ((cache && cache.key === wanted) || inflightKey.current === wanted) return;
    if (orgCustomers.customerIds.length === 0) {
      setCache({ key: wanted, rows: [] });
      setLoadedAt(Date.now());
      return;
    }
    if (debounce.current) clearTimeout(debounce.current);
    const ids = orgCustomers.customerIds;
    debounce.current = setTimeout(() => sweep(wantedKey, ids), DEBOUNCE_MS);
    return () => {
      if (debounce.current) clearTimeout(debounce.current);
    };
  }, [consumers, wanted]); // eslint-disable-line react-hooks/exhaustive-deps

  const refresh = useCallback(() => {
    if (debounce.current) clearTimeout(debounce.current);
    if (identity) customersFor.current = null;
    setCustomers(null);
    setCache(null);
  }, [identity]);

  const setRange = useCallback((next: TimeWindow) => setRangeState(next), []);

  const register = useCallback(() => {
    setConsumers((count) => count + 1);
    return () => setConsumers((count) => Math.max(0, count - 1));
  }, []);

  const rows = cache && cache.key === wanted ? cache.rows : [];
  const replaceRow = useCallback((row: StripePaymentRow) => {
    setCache((current) =>
      current ? { ...current, rows: current.rows.map((existing) => (existing.id === row.id ? row : existing)) } : current
    );
  }, []);

  const currentRows = useMemo(
    () => rows.filter((row) => row.createdAt >= range.from && row.createdAt <= range.to),
    [rows, range]
  );
  const previousRows = useMemo(
    () => rows.filter((row) => row.createdAt >= previous.from && row.createdAt <= previous.to),
    [rows, previous]
  );
  const live = useMemo(() => rows.some((row) => row.livemode), [rows]);

  const value: ContextValue = {
    identity,
    range,
    previous,
    setRange,
    customers: orgCustomers,
    noCustomers,
    rows,
    currentRows,
    previousRows,
    loading: loading || (!!identity && consumers > 0 && !orgCustomers && !customersError),
    progress,
    truncated,
    error: error || customersError,
    loadedAt,
    live,
    refresh,
    replaceRow,
    register,
  };

  return <StripeWindowContext.Provider value={value}>{children}</StripeWindowContext.Provider>;
};

/**
 * The shared window for a screen that reads the organisation's charges.
 * Mounting the hook (with `enabled`) is what makes the provider load.
 */
export const useStripeWindow = (enabled = true): StripeWindowState => {
  const context = useContext(StripeWindowContext);
  if (!context) {
    throw new Error("useStripeWindow must be used inside a StripeWindowProvider");
  }
  const { register, ...state } = context;
  useEffect(() => {
    if (!enabled) return;
    return register();
  }, [enabled, register]);
  return state;
};
