/**
 * Parents and their kids, for the Players page.
 *
 * Only parents are real users. Each parent record carries
 * `persistent.static.live.family = { familyId, relation, children: [{ type:
 * "nonBeamer", id, beamId }] }`, and every kid is a non-beamer record of its
 * own (profile, extended bio) that points back with `family.primaryParentUserId`
 * / `secondaryParentUserId`. Both parents of a family list the same kids.
 *
 * `buildFamilyRows` pairs every parent with each of their kids; `groupByKid`
 * then folds those pairs into one row per kid listing both parents (primary
 * first), which is what the Players pages show. A kid is rated and listed as a
 * player, but the parents are the ones added to a page or group, with the kid's
 * beamId attached to each parent's member entry (`associatedBeamIds`).
 *
 * The builders are pure so they can be tested; `fetchFamilyRows` is the thin
 * wrapper that reads over the same aggregate the other Players queries use.
 */
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { formatForRedis } from "utils/appUtil";

const ECO = process.env.REACT_APP_ECO_SYSTEM;

export interface FamilyParent {
  id: string;
  beamId?: string;
  name: string;
  email?: string;
  phone?: string;
  roleId?: string;
  /** The Stripe customer the parent pays through, when the record has one. */
  stripeCustomerId?: string | null;
  /** "primary" | "secondary" as the family record says. */
  relation?: string;
  /** The raw parent record. */
  user: any;
}

export interface FamilyKid {
  id: string;
  beamId?: string;
  /** The kid's own role (Recreational / Travelling ...), read from their record. */
  roleId?: string;
  /** Registered but not verified yet: the record is a `user:recreational` object. */
  pending?: boolean;
  /** The kid's record in the shape the Players rows use (live, extendedBio, status). */
  user: any;
}

export interface FamilyRow {
  /** Unique per parent and kid. */
  key: string;
  parent: FamilyParent;
  kid: FamilyKid;
}

const fullName = (live: any, fallback: string): string => {
  const first = `${live?.profile?.firstName ?? ""}`.trim();
  const last = `${live?.profile?.lastName ?? ""}`.trim();
  return `${first} ${last}`.trim() || fallback;
};

/** The aggregate that lists the org's parents: users whose family record has children. */
export const parentsRequest = (serviceId: string) => ({
  select: {
    index: {
      searchIndex: `${ECO}:userNameIndex`,
      searchQuery: `@serviceId:{'${formatForRedis(serviceId)}'}`,
      searchOptions: "TIMEOUT 5000",
    },
    load: {
      id: "$.objectId",
      live: "$.persistent.static.live",
      roleId: "$..admin.profile.roleId",
      children: "$.persistent.static.live.family.children",
      relation: "$.persistent.static.live.family.relation",
    },
  },
  apply: { expression: "", name: "" },
  result: {},
  filter: { expression: "exists(@children)" },
  anyStatus: false,
});

/** The aggregate that reads a batch of kids by id. */
export const kidsRequest = (serviceId: string, ids: string[]) => ({
  select: {
    index: {
      searchIndex: `${ECO}:userNameIndex`,
      searchQuery: `@serviceId:{'${formatForRedis(serviceId)}'}`,
      searchOptions: "TIMEOUT 5000",
    },
    list: { objectIds: ids },
    load: {
      id: "$.objectId",
      status: "$.nonpersistent.static.live.status",
      live: "$.persistent.static.live",
      roleId: "$..admin.profile.roleId",
      extendedBio: "$..extendedBio",
    },
  },
  apply: { expression: "", name: "" },
  result: {},
  filter: { expression: "exists(@roleId)" },
  anyStatus: false,
});

/**
 * The aggregate that reads pending kids. A kid whose parent has not verified yet
 * is a `user:recreational` custom object of the org (written by the CPC
 * registration form), not a user, so the user index does not list it.
 */
export const pendingKidsRequest = (serviceId: string, ids: string[]) => ({
  select: {
    index: {
      searchIndex: `${ECO}:custom:id`,
      searchQuery: `@partitions:{org\\:${formatForRedis(serviceId)}}`,
      searchOptions: "VERBATIM TIMEOUT 10000",
    },
    list: { objectIds: ids },
    load: { objectId: "$.objectId", info: "$.info" },
  },
});

/**
 * A pending kid in the shape the other player rows use (`live`, `roleId`,
 * `extendedBio`), so the date-of-birth, gender and extended-bio filters read it
 * unchanged. Null when the object is not a pending user.
 */
export const pendingToUser = (raw: any): any | null => {
  const info = raw?.info;
  if (!info || info.type !== "user:recreational" || raw.objectId === undefined) return null;
  const bio = info.basicBio || {};
  return {
    id: `${raw.objectId}`,
    pending: true,
    status: {},
    roleId: bio.roleId ? `${bio.roleId}` : undefined,
    live: {
      beamIds: bio.beamId ? [bio.beamId] : [],
      alternativeIds: { email: bio.email, phone: bio.phone },
      profile: {
        firstName: bio.firstName,
        middleName: bio.middleName,
        lastName: bio.lastName,
        doB: bio.doB,
        gender: bio.gender,
        location: bio.location,
      },
    },
    extendedBio: info.extendedBio,
  };
};

/** A parent row of the aggregate as a parent, or null when it has no kids. */
export const toParent = (raw: any): (FamilyParent & { children: any[] }) | null => {
  if (!raw || raw.id === undefined || raw.id === null) return null;
  const children = (Array.isArray(raw.children) ? raw.children : []).filter(
    (c: any) => c && c.id !== undefined && c.id !== null && `${c.id}` !== ""
  );
  if (!children.length) return null;
  const live = raw.live || {};
  return {
    id: `${raw.id}`,
    beamId: live?.beamIds?.[0],
    name: fullName(live, `#${raw.id}`),
    email: live?.alternativeIds?.email,
    phone: live?.alternativeIds?.phone,
    roleId: raw.roleId === undefined || raw.roleId === null ? undefined : `${raw.roleId}`,
    stripeCustomerId: live?.alternativeIds?.stripeCustomerId || null,
    relation: typeof raw.relation === "string" ? raw.relation : undefined,
    user: raw,
    children,
  };
};

/**
 * One row per parent and kid, parents in the order given and each parent's kids
 * in the order the family lists them. A kid whose record could not be read still
 * gets a row (named by its beamId) so a family is never silently short.
 */
export const buildFamilyRows = (parentRows: any[], kidRows: any[]): FamilyRow[] => {
  const kidsById = new Map<string, any>();
  (kidRows || []).forEach((k: any) => {
    if (k && k.id !== undefined && k.id !== null) kidsById.set(`${k.id}`, k);
  });
  const rows: FamilyRow[] = [];
  const seen = new Set<string>();
  (parentRows || []).forEach((raw) => {
    const parent = toParent(raw);
    if (!parent) return;
    parent.children.forEach((child: any) => {
      const kidId = `${child.id}`;
      const key = `${parent.id}:${kidId}`;
      if (seen.has(key)) return;
      seen.add(key);
      const record = kidsById.get(kidId);
      const live = record?.live;
      const beamId = live?.beamIds?.[0] || child.beamId;
      rows.push({
        key,
        parent,
        kid: {
          id: kidId,
          beamId,
          roleId: record?.roleId === undefined || record?.roleId === null ? undefined : `${record.roleId}`,
          pending: !!record?.pending,
          // The same shape the other Players rows carry, so the existing
          // filters (date of birth, gender, extended bio) read it unchanged.
          user: record || { id: kidId, live: { beamIds: beamId ? [beamId] : [], profile: { firstName: beamId || `#${kidId}`, lastName: "" } } },
        },
      });
    });
  });
  return rows;
};

/** The kid's display name. */
export const kidName = (kid: FamilyKid): string => fullName(kid.user?.live, kid.beamId || `#${kid.id}`);

/** One kid with every parent that lists them (primary first). */
export interface KidRow {
  /** Unique per kid. */
  key: string;
  kid: FamilyKid;
  parents: FamilyParent[];
}

const relationOrder = (relation?: string): number =>
  relation === "primary" ? 0 : relation === "secondary" ? 1 : 2;

/** One row per kid: the (parent, kid) pairs folded together, parents primary first. */
export const groupByKid = (rows: FamilyRow[]): KidRow[] => {
  const byKid = new Map<string, KidRow>();
  (rows || []).forEach((row) => {
    let entry = byKid.get(row.kid.id);
    if (!entry) {
      entry = { key: row.kid.id, kid: row.kid, parents: [] };
      byKid.set(row.kid.id, entry);
    }
    if (!entry.parents.some((p) => p.id === row.parent.id)) entry.parents.push(row.parent);
  });
  const out = Array.from(byKid.values());
  /* Array.sort is stable, so parents of the same relation keep their order. */
  out.forEach((entry) => entry.parents.sort((a, b) => relationOrder(a.relation) - relationOrder(b.relation)));
  return out;
};

/** The parents of a list of rows, once each, in first-seen order. */
export const uniqueParents = (rows: KidRow[]): FamilyParent[] => {
  const seen = new Set<string>();
  const parents: FamilyParent[] = [];
  rows.forEach((row) =>
    row.parents.forEach((parent) => {
      if (seen.has(parent.id)) return;
      seen.add(parent.id);
      parents.push(parent);
    })
  );
  return parents;
};

/**
 * The page members for rows: each parent once (every parent of a selected kid),
 * with the beamIds of their selected kids (and their own) attached, as the
 * page's `associatedBeamIds` expects.
 */
export interface FamilyMember {
  id: string;
  beamId?: string;
  associatedBeamIds: string[];
}

export const familyMembers = (rows: KidRow[]): FamilyMember[] => {
  const byParent = new Map<string, FamilyMember>();
  rows.forEach((row) =>
    row.parents.forEach((parent) => {
      let member = byParent.get(parent.id);
      if (!member) {
        member = {
          id: parent.id,
          beamId: parent.beamId,
          associatedBeamIds: parent.beamId ? [parent.beamId] : [],
        };
        byParent.set(parent.id, member);
      }
      if (row.kid.beamId && !member.associatedBeamIds.includes(row.kid.beamId)) {
        member.associatedBeamIds.push(row.kid.beamId);
      }
    })
  );
  return Array.from(byParent.values());
};

/** Runs one aggregate request and resolves with its rows (an empty list when it fails). */
export type RunAggregate = (requestData: any) => Promise<any[]>;

const viaDispatch = (dispatch: any): RunAggregate => (requestData) =>
  new Promise((resolve) => {
    dispatch(
      GET_AGGREGATE({
        requestData,
        callback: (response: any) => resolve(Array.isArray(response) ? response : []),
      })
    );
  });

/** Reads the org's parents and their kids and returns one row per parent and kid. */
export const fetchFamilyRows = (dispatch: any, serviceId: string): Promise<FamilyRow[]> =>
  fetchFamilyRowsWith(viaDispatch(dispatch), serviceId);

/** The same read over any transport (the CFO dashboard sends its aggregates with fetch). */
export const fetchFamilyRowsWith = async (run: RunAggregate, serviceId: string): Promise<FamilyRow[]> => {
  if (!serviceId) return [];
  const aggregate = (_: unknown, request: any) => run(request);
  const parentRows = await aggregate(null, parentsRequest(serviceId));
  /* Kids are listed as `nonBeamer` (a user) or `pending` (registered, not verified yet). */
  const kidIds = new Set<string>();
  const pendingIds = new Set<string>();
  parentRows.forEach((raw: any) =>
    (Array.isArray(raw?.children) ? raw.children : []).forEach((c: any) => {
      const id = `${c?.id}`;
      if (!id || id === "undefined") return;
      (c?.type === "pending" ? pendingIds : kidIds).add(id);
    })
  );
  const [userKids, pendingRows] = await Promise.all([
    kidIds.size ? aggregate(null, kidsRequest(serviceId, Array.from(kidIds))) : Promise.resolve([]),
    pendingIds.size ? aggregate(null, pendingKidsRequest(serviceId, Array.from(pendingIds))) : Promise.resolve([]),
  ]);
  const pendingKids = pendingRows.map(pendingToUser).filter((k: any) => k !== null);
  return buildFamilyRows(parentRows, [...userKids, ...pendingKids]);
};

/**
 * Whether a coach sees a kid row: one of the kid's parents is a member of one of
 * the coach's pages AND the kid's beamId is attached to a member of those pages.
 * Both are needed so a kid shows only when a parent who is on the page lists
 * them, and a kid's id (a different counter than user ids) is never matched to a
 * member.
 */
export const kidInCoachScope = (
  row: KidRow,
  memberIds: string[] | undefined,
  memberBeamIds: string[] | undefined
): boolean =>
  row.parents.some((p) => !!memberIds?.includes(p.id)) &&
  !!row.kid.beamId &&
  !!memberBeamIds?.includes(row.kid.beamId);

/** How many distinct kids rows stand for (a kid listed under both parents counts once). */
export const distinctKidCount = (rows: any[]): number =>
  new Set(rows.map((r) => `${r?.action?.userId}`)).size;
