import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Modal, Select, Button, Input, Spin, Tag } from "antd";
import { useDispatch, useSelector } from "react-redux";

import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { formatForRedis } from "utils/appUtil";
import { PERMISSION_TYPES } from "utils/PageTypes";
import { pushNotification } from "utils/notifications";
import { CreatePageReplies } from "../../../CFO/Dashboard/payments/friendPage";
import { GroupUser } from "./AddToGroupModal";

/**
 * "Assign coaches" popup for the Players page. The selected players plus the
 * chosen coaches become the members of one new page, created with the same
 * `createPage` message the CFO dashboard uses for its friend pages.
 */

interface CoachOption {
  id: string;
  name: string;
  beamId?: string;
}

const AssignCoachesModal: FC<{
  open: boolean;
  /** Selected players. */
  users: GroupUser[];
  /** id -> label of the selected users, to show who joins the page. */
  usersById?: Record<string, string>;
  /** How many players (kids) the selection stands for, when `users` are their parents. */
  playerCount?: number;
  serviceId: string;
  connectionId: string;
  socket?: ISocket;
  onClose: () => void;
  onCreated?: () => void;
}> = ({ open, users, usersById, playerCount, serviceId, connectionId, socket, onClose, onCreated }) => {
  const players = playerCount ?? users.length;
  const dispatch = useDispatch();
  const { adminUserRoles } = useSelector((state: RootState) => state.auth);
  const [coaches, setCoaches] = useState<CoachOption[]>([]);
  const [loading, setLoading] = useState(false);
  const [selected, setSelected] = useState<string[]>([]);
  const [title, setTitle] = useState("");
  const [creating, setCreating] = useState(false);
  const repliesRef = useRef<CreatePageReplies | null>(null);

  // Same coach role the Coaches page lists.
  const coachRoles = useMemo(
    () =>
      (adminUserRoles || []).filter(
        (x: any) =>
          x.name.toLowerCase() === "coach" &&
          x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1 &&
          x.permissions.indexOf(PERMISSION_TYPES.Live) !== -1 &&
          x.permissions.indexOf(PERMISSION_TYPES.Dashboard) !== -1 &&
          x.permissions.indexOf(PERMISSION_TYPES.OnMove) !== -1
      ),
    [adminUserRoles]
  );

  useEffect(() => {
    if (!open) return;
    setSelected([]);
    setTitle("");
    if (!serviceId || !coachRoles.length) return;
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: {
          select: {
            index: {
              searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
              searchQuery: `@serviceId:{'${formatForRedis(serviceId)}'}`,
              searchOptions: "TIMEOUT 5000",
            },
            load: {
              id: "$.objectId",
              live: "$.persistent.static.live",
              roleId: "$..admin.profile.roleId",
            },
          },
          apply: { expression: "", name: "" },
          result: {},
          filter: {
            expression: `exists(@roleId) && (${coachRoles
              .map((r: any) => `@roleId === '${r._id}'`)
              .join("||")})`,
          },
          anyStatus: false,
        },
        callback: (response: any) => {
          setLoading(false);
          const rows = Array.isArray(response) ? response : [];
          setCoaches(
            rows.map((x: any) => ({
              id: `${x.id}`,
              name:
                `${x?.live?.profile?.firstName ?? ""} ${x?.live?.profile?.lastName ?? ""}`.trim() ||
                `#${x.id}`,
              beamId: x?.live?.beamIds?.[0],
            }))
          );
        },
      })
    );
  }, [open, serviceId, coachRoles, dispatch]);

  // Drop the createPage reply subscription when the popup goes away.
  useEffect(() => {
    return () => {
      repliesRef.current?.close();
      repliesRef.current = null;
    };
  }, []);

  const handleCreate = async () => {
    if (!socket || !connectionId || !users.length || !selected.length) return;
    setCreating(true);
    try {
      if (!repliesRef.current) repliesRef.current = new CreatePageReplies(socket, connectionId);
      const now = Date.now();
      const members = [
        ...users.map((u) => ({ id: u.id, beamId: u.beamId, associatedBeamIds: u.associatedBeamIds })),
        ...coaches
          .filter((c) => selected.includes(c.id))
          .map((c) => ({ id: c.id, beamId: c.beamId, associatedBeamIds: undefined as string[] | undefined })),
      ];
      const changes: any[] = [
        { op: "add", path: "/persistent/static/metadata/createdAt", value: now },
        { op: "add", path: "/persistent/dynamic/metadata/updatedAt", value: now },
        { op: "add", path: "/nonpersistent/dynamic/metadata/lastSent/members/updatedAt", value: now },
        { op: "add", path: "/persistent/static/metadata/type", value: "group" },
        {
          op: "add",
          path: "/persistent/static/metadata/title",
          value: title.trim() || "Players & coaches",
        },
        ...members.map((m) => ({
          op: "add",
          path: `/persistent/static/metadata/members/users/${m.id}`,
          value: {
            beamId: m.beamId || `User#${m.id}`,
            role: "write",
            // A parent carries the selected kids as associated beamIds.
            ...(m.associatedBeamIds && m.associatedBeamIds.length
              ? {
                  associatedBeamIds: m.associatedBeamIds.map((b) => ({ beamId: b, role: "write" })),
                }
              : {}),
          },
        })),
        { op: "add", path: "/partitions", value: [`org:${serviceId}`] },
      ];
      console.log("[AssignCoaches] createPage", { members: members.length, changes });
      const pageId = await repliesRef.current.create(changes);
      console.log("[AssignCoaches] page created", pageId);
      pushNotification(
        `Page created with ${players} ${players === 1 ? "player" : "players"} and ${
          selected.length
        } ${selected.length === 1 ? "coach" : "coaches"}`,
        "success",
        "TOP_CENTER",
        3000
      );
      onCreated?.();
      onClose();
    } catch (e: any) {
      pushNotification(e?.message || "Could not create the page", "error", "TOP_CENTER", 3500);
    } finally {
      setCreating(false);
    }
  };

  return (
    <Modal
      title="Assign coaches"
      visible={open}
      onCancel={onClose}
      width="520px"
      className="beam-modal"
      footer={null}
      destroyOnClose
    >
      <p style={{ color: "#8c8c8c", marginBottom: 12 }}>
        The {players === 1 ? "player" : "players"} you selected (with their parent) and the coaches
        you choose will all be on one new page.
      </p>

      <div style={{ fontSize: 12, color: "#8c8c8c", marginBottom: 6 }}>
        Players ({players})
      </div>
      <div style={{ maxHeight: 120, overflow: "auto", display: "flex", flexWrap: "wrap", gap: 6 }}>
        {users.map((u) => (
          <Tag key={u.id}>{usersById?.[u.id] || `#${u.id}`}</Tag>
        ))}
      </div>

      <div style={{ fontSize: 12, color: "#8c8c8c", margin: "16px 0 6px" }}>Coaches</div>
      {loading ? (
        <Spin size="small" />
      ) : (
        <Select
          mode="multiple"
          allowClear
          showSearch
          placeholder="Select coaches"
          value={selected}
          onChange={(v) => setSelected(v)}
          options={coaches.map((c) => ({ label: c.name, value: c.id }))}
          filterOption={(input, option) =>
            (option?.label ?? "").toString().toLowerCase().includes(input.toLowerCase())
          }
          style={{ width: "100%" }}
          notFoundContent="No coaches found"
        />
      )}

      <div style={{ fontSize: 12, color: "#8c8c8c", margin: "16px 0 6px" }}>Page name (optional)</div>
      <Input
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        placeholder="Players & coaches"
      />

      <div style={{ display: "flex", gap: 12, marginTop: 24 }}>
        <Button
          type="primary"
          className="beam-btn green-btn cover"
          style={{ flex: 1 }}
          loading={creating}
          disabled={!selected.length || !users.length}
          onClick={handleCreate}
        >
          Create page
        </Button>
        <Button
          className="beam-btn orange-btn bordered"
          style={{ flex: 1 }}
          onClick={onClose}
          disabled={creating}
        >
          Cancel
        </Button>
      </div>
    </Modal>
  );
};

export default AssignCoachesModal;
