import React, { FC, useCallback, useEffect, useMemo, useState } from "react";
import { Button, Row, Col, Table, Select, Tooltip, Modal } from "antd";
import { EditOutlined, EyeOutlined, ReloadOutlined } from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import {
  encryptSetupToken,
  searchInQuery,
} from "../../../../../services/apis/collections/oAuthApis";
import { pushNotification } from "utils/notifications";
import "../Dashboard.scss";

// Values from the Beam Vite apps guide. The object id and app URL can differ per
// environment, so both can be overridden from the environment.
const BEAM_APPS_OBJECT_ID = Number(
  process.env.REACT_APP_BEAM_APPS_OBJECT_ID || 202051
);
const BEAMVITE_APP_URL = (
  process.env.REACT_APP_BEAMVITE_URL || "https://beamvite.beam.live"
).replace(/\/$/, "");
// Fixed values: the shared admin of Beam Vite apps, and the CUDB all of them use.
const BEAMVITE_ADMIN_ID = "25";
const BEAMVITE_CUDB_SERVICE_ID = "cudb-live";

/** `key=value&key=value`, skipping keys with no value. */
const buildSetupString = (entries: [string, any][]) =>
  entries
    .filter(([, value]) => value !== undefined && value !== null && `${value}` !== "")
    .map(([key, value]) => `${key}=${value}`)
    .join("&");

/**
 * Beam Vite apps of the organization: create one (pick the role its users get,
 * then the onboarding page takes over) and list the org's apps with View / Edit.
 */
const BeamAppsModal: FC<{ userRole?: any }> = () => {
  const { projects, encrypted_token, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const orgServiceId: string | undefined = projects?.userServiceId;
  const connectionId = encrypted_token?.connectionId;

  const [roleId, setRoleId] = useState<string | undefined>(undefined);
  const [creating, setCreating] = useState(false);
  const [apps, setApps] = useState<any[]>([]);
  const [appsLoading, setAppsLoading] = useState(false);
  const [openingId, setOpeningId] = useState<string | undefined>(undefined);
  // The page shown in the popup (onboarding form or the public app).
  const [frame, setFrame] = useState<{ title: string; url: string } | undefined>(
    undefined
  );

  const roleOptions = useMemo(
    () =>
      (adminUserRoles || []).map((role: any) => ({
        label: role?.name,
        value: role?._id,
      })),
    [adminUserRoles]
  );
  const roleNameOf = (id?: string) =>
    (adminUserRoles || []).find((r: any) => r?._id === id)?.name || "-";

  // ----- List: every org's apps live in one BDS object, so read it and keep
  // only this organization's Beam Vite apps (the rest is dropped right away).
  const loadApps = useCallback(() => {
    if (!orgServiceId) return;
    setAppsLoading(true);
    searchInQuery({
      data: {
        objectId: BEAM_APPS_OBJECT_ID,
        paths: ["$"],
        returnPaths: ["/info"],
        resultType: "value",
      },
    })
      .then((res: any) => {
        const header = res?.data?.header?.[0]?.[0];
        const entries =
          header && typeof header === "object" && !Array.isArray(header)
            ? Object.entries(header)
            : [];
        const mine = entries
          .filter(([, info]: [string, any]) => {
            const owns =
              info?.cudbServiceId === orgServiceId ||
              info?.selectedCudbServiceId === orgServiceId;
            return owns && `${info?.appType ?? ""}`.toLowerCase() === "beamvite";
          })
          .map(([key, info]: [string, any]) => ({
            id: key,
            companyName: info?.websiteName ?? key,
            userId: info?.userId,
            adminId: info?.adminId,
            connectionId: info?.connectionId,
            cudbServiceId: info?.cudbServiceId,
            selectedCudbServiceId: info?.selectedCudbServiceId || "",
            roleId: info?.roleId || "",
          }));
        console.log("[BeamApps] apps of this org", mine);
        setApps(mine);
        setAppsLoading(false);
      })
      .catch(() => {
        setApps([]);
        setAppsLoading(false);
      });
  }, [orgServiceId]);

  useEffect(() => {
    loadApps();
  }, [loadApps]);

  // The onboarding page saves the app in another tab and sends nothing back, so
  // reload the list whenever the user returns to this tab.
  useEffect(() => {
    const onVisible = () => {
      if (document.visibilityState === "visible") loadApps();
    };
    document.addEventListener("visibilitychange", onVisible);
    return () => document.removeEventListener("visibilitychange", onVisible);
  }, [loadApps]);

  // ----- Create / Edit: setup string -> token -> onboarding page in a popup.
  const openOnboarding = async (
    title: string,
    setup: string,
    busy: () => void,
    idle: () => void,
    extraParams?: Record<string, string>
  ) => {
    busy();
    try {
      console.log("[BeamApps] setup string", setup);
      const res: any = await encryptSetupToken({ payload: setup });
      const token = res?.token;
      if (!token) {
        throw new Error(
          (Array.isArray(res?.message) ? res.message.join(", ") : res?.message) ||
            "Could not create the token"
        );
      }
      const query = new URLSearchParams({ token, ...(extraParams || {}) });
      const url = `${BEAMVITE_APP_URL}/onboarding?${query.toString()}`;
      console.log("[BeamApps] onboarding url", url);
      setFrame({ title, url });
    } catch (error: any) {
      pushNotification(
        error?.message || "Could not open the onboarding page",
        "error",
        "TOP_CENTER",
        3500
      );
    } finally {
      idle();
    }
  };

  // The onboarding page saves the app itself, so reload the list on close.
  const closeFrame = () => {
    setFrame(undefined);
    loadApps();
  };

  const createApp = () => {
    if (!roleId || !orgServiceId) return;
    // selectedCudbServiceId and roleId must both be set, otherwise the app's
    // users register in cudb-live instead of the organization.
    const setup = buildSetupString([
      ["adminId", BEAMVITE_ADMIN_ID],
      ["connectionId", connectionId],
      ["cudbServiceId", BEAMVITE_CUDB_SERVICE_ID],
      ["appType", "beamvite"],
      ["selectedCudbServiceId", orgServiceId],
      ["roleId", roleId],
    ]);
    // The form needs the app type and the logged-in org as plain URL params too.
    openOnboarding("Create app", setup, () => setCreating(true), () => setCreating(false), {
      appType: "beamvite",
      adminCudbServiceId: orgServiceId,
    });
  };

  const editApp = (app: any) => {
    // Sending the stored values (plus websiteName = the app key) makes the page
    // load the existing app; what is saved replaces what is stored.
    const setup = buildSetupString([
      ["adminId", app.adminId || BEAMVITE_ADMIN_ID],
      ["connectionId", app.connectionId || connectionId],
      ["cudbServiceId", app.cudbServiceId || BEAMVITE_CUDB_SERVICE_ID],
      ["appType", "beamvite"],
      ["websiteName", app.id],
      ["selectedCudbServiceId", app.selectedCudbServiceId],
      ["roleId", app.roleId],
      ["userId", app.userId],
    ]);
    openOnboarding(
      `Edit ${app.companyName}`,
      setup,
      () => setOpeningId(app.id),
      () => setOpeningId(undefined)
    );
  };

  const viewApp = (app: any) =>
    setFrame({ title: app.companyName, url: `${BEAMVITE_APP_URL}/${app.id}` });

  const columns = [
    {
      title: "Company name",
      dataIndex: "companyName",
      key: "companyName",
      defaultSortOrder: "ascend" as const,
      sorter: (a: any, b: any) =>
        `${a?.companyName ?? ""}`.localeCompare(`${b?.companyName ?? ""}`),
    },
    {
      title: "Role",
      key: "role",
      render: (_: any, app: any) => roleNameOf(app.roleId),
    },
    {
      title: "Action",
      key: "action",
      render: (_: any, app: any) => (
        <Row style={{ width: 110 }}>
          <Col span={12}>
            <Tooltip overlay="View app">
              <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn cover"
                onClick={() => viewApp(app)}
              >
                <EyeOutlined />
              </Button>
            </Tooltip>
          </Col>
          <Col span={12}>
            <Tooltip overlay="Edit app">
              <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn yellow-btn cover"
                loading={openingId === app.id}
                onClick={() => editApp(app)}
              >
                <EditOutlined />
              </Button>
            </Tooltip>
          </Col>
        </Row>
      ),
    },
  ];

  return (
    <React.Fragment>
      <Row>
        <Col span={24}>
          <div>
            <h2 style={{ marginBottom: 4 }}>Apps</h2>
            <p style={{ marginBottom: 0, color: "#8c8c8c" }}>
              Home &gt; Apps
            </p>
          </div>
        </Col>
      </Row>

      <Row gutter={[12, 12]} className="mt-3" align="middle">
        <Col xs={24} sm={14} md={10} lg={8}>
          <Select
            showSearch
            allowClear
            placeholder="Select a role for the app's users"
            options={roleOptions}
            value={roleId}
            onChange={(value) => setRoleId(value)}
            filterOption={(input, option) =>
              (option?.label ?? "")
                .toString()
                .toLowerCase()
                .includes(input.toLowerCase())
            }
            notFoundContent="No roles found for this organization"
            style={{ width: "100%" }}
          />
        </Col>
        <Col>
          <Button
            className="beam-btn green-btn cover"
            disabled={!roleId}
            loading={creating}
            onClick={createApp}
          >
            Create app
          </Button>
        </Col>
        <Col>
          <Tooltip overlay="Reload the list">
            <Button
              style={{ boxShadow: "none" }}
              className="beam-btn icon-btn cover"
              loading={appsLoading}
              onClick={loadApps}
            >
              <ReloadOutlined />
            </Button>
          </Tooltip>
        </Col>
      </Row>
      {roleOptions.length === 0 && (
        <p style={{ color: "#8c8c8c", marginTop: 8 }}>
          No roles found for this organization. Open it once in the admin console
          so its default roles are created.
        </p>
      )}

      <Row
        gutter={20}
        className="scrollable-table mt-3"
        style={{ display: "grid", marginRight: -20 }}
      >
        <Col xs={24} sm={24} md={24} style={{ maxHeight: 1000, overflow: "scroll" }}>
          <Table
            rowKey="id"
            loading={appsLoading}
            dataSource={apps}
            columns={columns}
            locale={{ emptyText: "No apps yet" }}
            scroll={{ x: true }}
          />
        </Col>
      </Row>

      <Modal
        title={frame?.title}
        visible={frame !== undefined}
        onCancel={closeFrame}
        width="90vw"
        className="beam-modal"
        footer={[]}
        destroyOnClose
      >
        {frame && (
          <iframe
            title="beam-vite"
            src={frame.url}
            style={{ width: "100%", height: "80vh", border: "none" }}
          />
        )}
      </Modal>
    </React.Fragment>
  );
};

export default BeamAppsModal;
