import React, { FC, useEffect, useRef, useState } from "react";
import { Layout } from "antd";
import { useDispatch } from "react-redux";
import { useLocation } from "react-router-dom";
import { SocketTopics } from "constants/enums";
import { decryptPublishTopic, decryptSubscriptionTopic } from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import { pushNotification } from "utils/notifications";

import Header from "./Header";
import SideBar from "./SideBar";
import CfoAccessGate from "./CfoAccessGate";
import { CFO_MENU_ITEMS, menuLabel } from "./menu";
import { Domain, EntityKind, TransactionFilter } from "./types";
import DashboardScreen from "./screens/DashboardScreen";
import EntityScreen from "./screens/EntityScreen";
import TransactionsScreen, { TransactionPreset } from "./screens/TransactionsScreen";
import ReportsScreen from "./screens/ReportsScreen";
import { StripeWindowProvider } from "./stripe/useStripeWindow";
import { DirectoryProvider } from "./directory/useDirectory";
import { CfoSocketProvider } from "./payments/useCfoSocket";
import { PaymentRequestsProvider } from "./payments/usePaymentRequests";

import "../../School3/Dashboard/Dashboard.scss";
import "./CFODashboard.scss";

/**
 * The CFO dashboard page: header across the top, icon rail down the
 * left, one screen at a time in the content pane.
 *
 * Four screens: Dashboard (the big picture), Transactions (every ledger
 * line and the payment schedule behind one filter), Reports (AR / AP
 * aging and reminders) and the Directory (players, teams, events,
 * coaches, staff and vendors behind one select). Dashboard and Reports
 * drill into Transactions by handing it a filter preset.
 *
 * The Directory reads the organisation through `DirectoryProvider` and
 * the organisation's Stripe charges through `StripeWindowProvider`;
 * Transactions reads the payment requests the wizard recorded through
 * `PaymentRequestsProvider`. All key off the link's token (see the
 * decrypt effect below). Dashboard and Reports still run on mock data.
 *
 * Laid out with flex rather than the fixed header + rail the other
 * dashboards use, so the same look needs no viewport-sized magic
 * numbers and the content pane is the only thing that scrolls.
 */
const CFODashboardWrapper: FC<{ socket?: ISocket }> = ({ socket }) => {
  const dispatch = useDispatch();
  const { search } = useLocation();
  const [screen, setScreen] = useState<CFO_MENU_ITEMS>(CFO_MENU_ITEMS.Dashboard);
  const [domain, setDomain] = useState<Domain>("sport");
  const [entityKind, setEntityKind] = useState<EntityKind>("players");
  const [preset, setPreset] = useState<TransactionPreset | null>(null);
  const content = useRef<HTMLDivElement>(null);
  /** The token already sent for decryption, so re-renders do not publish it again. */
  const decrypted = useRef<string | null>(null);

  /* A new screen starts at the top, not wherever the last one was scrolled to. */
  useEffect(() => {
    if (content.current) content.current.scrollTop = 0;
  }, [screen, domain]);

  /*
   * Identity comes from the encrypted `?token=` on the link, as on every
   * other dashboard: decrypt it over the socket (School3's pattern) and
   * store the payload as `encrypted_token`, which the directory, the
   * Stripe window and the send wizard read. Without a token nothing is
   * dispatched and the Directory shows the sign-in state.
   */
  useEffect(() => {
    if (!socket || !socket.client) return;
    const token = new URLSearchParams(search).get("token");
    if (!token || decrypted.current === token) return;
    decrypted.current = token;

    const connectionId = String(Math.floor(10000 + Math.random() * 90000));
    const fail = () => pushNotification("The link's token could not be read", "error", "TOP_CENTER", 3000);

    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      decryptSubscriptionTopic(connectionId),
      (response: any) => {
        const raw = response?.response?.data?.decryptedPayload;
        try {
          const payload = typeof raw === "string" ? JSON.parse(raw) : raw;
          if (payload && typeof payload === "object") {
            dispatch({ type: "ADD_ENCRYPTED_TOKEN", payload });
          } else {
            fail();
          }
        } catch (e) {
          fail();
        }
      }
    );
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      decryptPublishTopic(connectionId),
      wrapRequestPayload({ payload: token })
    );
  }, [search, socket && socket.client]); // eslint-disable-line react-hooks/exhaustive-deps

  const switchDomain = (next: Domain) => {
    setDomain(next);
    setPreset(null);
    setScreen(CFO_MENU_ITEMS.Dashboard);
  };

  /** Lands on Transactions with the given filters applied. */
  const openTransactions = (filter: Partial<TransactionFilter>) => {
    setPreset({ filter, nonce: Date.now() });
    setScreen(CFO_MENU_ITEMS.Transactions);
  };

  const renderScreen = (current: CFO_MENU_ITEMS) => {
    switch (current) {
      case CFO_MENU_ITEMS.Dashboard:
        return <DashboardScreen domain={domain} onOpenTransactions={openTransactions} />;
      case CFO_MENU_ITEMS.Transactions:
        return <TransactionsScreen domain={domain} preset={preset} />;
      case CFO_MENU_ITEMS.Reports:
        return <ReportsScreen domain={domain} onOpenTransactions={openTransactions} />;
      case CFO_MENU_ITEMS.Directory:
        return (
          <EntityScreen key={entityKind} kind={entityKind} onKindChange={setEntityKind} domain={domain} />
        );
      default:
        return (
          <div className="cfo-placeholder">
            <h2>{menuLabel(current, domain)}</h2>
          </div>
        );
    }
  };

  return (
    <StripeWindowProvider>
      <DirectoryProvider>
        <PaymentRequestsProvider>
        <CfoSocketProvider socket={socket}>
          <CfoAccessGate>
          {(allowedModules) => {
            // A screen the role's list leaves out never renders; open its first one instead.
            const current =
              allowedModules && !allowedModules.includes(screen)
                ? (allowedModules[0] as CFO_MENU_ITEMS) || screen
                : screen;
            return (
          <div className="cfo-shell">
            <Header domain={domain} onDomainChange={switchDomain} />

            <div className="cfo-shell__body">
              <div className="cfo-shell__rail">
                <SideBar screen={current} setScreen={setScreen} domain={domain} allowedModules={allowedModules} />
              </div>

              <div className="cfo-shell__content" ref={content}>
                <div className="beam-modal analytics-summary-modal">
                  <Layout className="main-layout exec-layout">{renderScreen(current)}</Layout>
                </div>
              </div>
            </div>
          </div>
            );
          }}
          </CfoAccessGate>
        </CfoSocketProvider>
        </PaymentRequestsProvider>
      </DirectoryProvider>
    </StripeWindowProvider>
  );
};

export default CFODashboardWrapper;
