/**
 * Payment requests — the page side of the link between a request record
 * and the friend page it was delivered on.
 *
 * api-admin-core links a page to its group by `updatePage` adding
 * `/persistent/static/organization/queryId` (`group.service.ts`,
 * `updateGroupPage`). This does the same for payment requests, over the
 * page API with the `topic` header the backend sends. The page keeps a
 * map of the requests delivered on it, keyed by record id, so a friend
 * page reused for a second request gains an entry without a read first.
 *
 * Identity only: amount, ids and when. Delivery and payment state live
 * on the record, so there is one source for them.
 */
import { OrgContext } from "../directory/directoryApi";
import { PaymentRequestRecord } from "./paymentRequestRecord";

const ecosystem = process.env.REACT_APP_ECO_SYSTEM || "";
const pageBase = process.env.REACT_APP_LIVE_API || "";

const UPDATE_PAGE_TIMEOUT_MS = 10_000;

/** Where a page stores the payment requests delivered on it. */
export const PAGE_PAYMENTS_PATH = "/persistent/static/payments";

export interface PageChange {
  op: "add" | "replace";
  path: string;
  value: unknown;
}

/** What a page records about one request. */
export interface PageRequestRef {
  paymentRequestId: string;
  requestId: string;
  batchId: string;
  amount: number;
  currency: string;
  subject: string;
  createdAt: number;
}

export type PageUpdateResult = { ok: true } | { ok: false; error: string };

export const pageUpdateTopic = (connectionId: string): string =>
  `${ecosystem}/connection/${connectionId}/service/live/updatePage`;

/** The page reference for a record. */
export const pageRequestRef = (
  recordId: string,
  record: Pick<PaymentRequestRecord, "requestId" | "batchId" | "amount" | "subject" | "createdAt">
): PageRequestRef => ({
  paymentRequestId: recordId,
  requestId: record.requestId,
  batchId: record.batchId,
  amount: record.amount.total,
  currency: record.amount.currency,
  subject: record.subject,
  createdAt: record.createdAt,
});

/** JSON-patch changes that put the record's reference on the page. */
export const paymentRequestPageChanges = (ref: PageRequestRef, now: number): PageChange[] => [
  { op: "add", path: `${PAGE_PAYMENTS_PATH}/requests/${ref.paymentRequestId}`, value: ref },
  { op: "add", path: `${PAGE_PAYMENTS_PATH}/lastPaymentRequestId`, value: ref.paymentRequestId },
  { op: "add", path: "/persistent/dynamic/metadata/updatedAt", value: now },
];

/**
 * `updatePage` as api-admin-core's `sendRequest` makes it: JSON POST,
 * `topic` header, the reply's `status` says whether it took. Never
 * throws; a failure comes back as `{ok: false, error}` so a send can go
 * on without the link.
 */
export const updatePage = async (context: OrgContext, pageId: string, changes: PageChange[]): Promise<PageUpdateResult> => {
  if (!pageBase) return { ok: false, error: "REACT_APP_LIVE_API is not set" };
  const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), UPDATE_PAGE_TIMEOUT_MS) : null;
  try {
    const response = await fetch(`${pageBase}/updatePage`, {
      method: "POST",
      headers: { accept: "*/*", "Content-Type": "application/json", topic: pageUpdateTopic(context.connectionId) },
      body: JSON.stringify({ objectId: pageId, changes }),
      signal: controller ? controller.signal : undefined,
    });
    const text = await response.text();
    let body: any = {};
    try {
      body = text ? JSON.parse(text) : {};
    } catch (e) {
      body = { status: false, message: text.slice(0, 200) };
    }
    if (!response.ok || (body && body.status === false)) {
      return { ok: false, error: (body && body.message) || `updatePage replied ${response.status}` };
    }
    return { ok: true };
  } catch (e: any) {
    return { ok: false, error: e?.name === "AbortError" ? "updatePage timed out" : e?.message || "updatePage failed" };
  } finally {
    if (timer) clearTimeout(timer);
  }
};
