import React, { FC, useEffect, useState } from "react";
import { Modal, Select, Spin, Rate, Empty } from "antd";
import { useDispatch } from "react-redux";

import { CoachRating, Option, fetchRatedUserIds } from "./ratingSources";

/**
 * "Show Ratings" popup: what each coach rated a player on a page, and the
 * overall (the average across coaches).
 */
const ShowRatingsModal: FC<{
  open: boolean;
  user?: { userId: any; name?: string };
  serviceId: string;
  pages: Option[];
  /** The page picked in the Players filter, used as the starting page. */
  initialPageId?: string;
  /** Surveys that count as rating surveys (empty = every survey on the page). */
  ratingSurveyIds: string[];
  onClose: () => void;
}> = ({ open, user, serviceId, pages, initialPageId, ratingSurveyIds, onClose }) => {
  const dispatch = useDispatch();
  const [pageId, setPageId] = useState<string | undefined>(undefined);
  const [loading, setLoading] = useState(false);
  const [list, setList] = useState<CoachRating[]>([]);

  useEffect(() => {
    if (open) setPageId(initialPageId);
    else setList([]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  useEffect(() => {
    if (!open || !pageId || !user) {
      setList([]);
      return;
    }
    let active = true;
    setLoading(true);
    fetchRatedUserIds(dispatch, serviceId, pageId, ratingSurveyIds).then(({ byPlayer }) => {
      if (!active) return;
      setList(byPlayer[`${user.userId}`] || []);
      setLoading(false);
    });
    return () => {
      active = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, pageId, user?.userId]);

  const range = list.length ? Math.max(...list.map((c) => c.range)) : 5;
  const overall = list.length
    ? Math.round((list.reduce((sum, c) => sum + c.value, 0) / list.length) * 10) / 10
    : 0;

  const stars = (value: number, count: number) => (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}>
      <Rate disabled allowHalf count={count} value={value} style={{ fontSize: 14 }} />
      <span>
        {value}/{count}
      </span>
    </span>
  );

  return (
    <Modal
      title={`Ratings - ${user?.name || ""}`}
      visible={open}
      onCancel={onClose}
      width="min(560px, 96vw)"
      className="beam-modal"
      footer={null}
      destroyOnClose
    >
      <Select
        showSearch
        allowClear
        placeholder="Select page"
        value={pageId}
        onChange={(v) => setPageId(v)}
        options={pages.map((p) => ({ label: p.label, value: p.value }))}
        optionFilterProp="label"
        style={{ width: "100%", marginBottom: 16 }}
      />
      {!pageId ? (
        <Empty description="Select a page to see its ratings" image={Empty.PRESENTED_IMAGE_SIMPLE} />
      ) : loading ? (
        <div style={{ textAlign: "center", padding: "24px 0" }}>
          <Spin />
        </div>
      ) : (
        <>
          {list.length ? (
            list.map((c, i) => (
              <div
                key={`${c.raterId ?? c.raterName}-${c.surveyId}-${i}`}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: "8px 12px",
                  borderBottom: "1px solid rgba(0,0,0,0.06)",
                }}
              >
                <span>{c.raterName}</span>
                {stars(c.value, c.range)}
              </div>
            ))
          ) : (
            <Empty description="No ratings on this page yet" image={Empty.PRESENTED_IMAGE_SIMPLE} />
          )}
          {list.length > 0 && (
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              padding: "10px 12px",
              borderRadius: 8,
              background: "rgba(0,0,0,0.04)",
              marginTop: 16,
            }}
          >
            <strong>Total</strong>
            {stars(overall, range)}
          </div>
          )}
        </>
      )}
    </Modal>
  );
};

export default ShowRatingsModal;
