import { useEffect, useState } from "react";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";

import { dashboardAccess } from "../../../School3/permissions";
import { fetchUserRoleId } from "./directoryApi";
import { useDirectory } from "./useDirectory";

export interface CfoAccess {
  /** The signed-in user's role is known, so `enabled` and `modules` are final. */
  ready: boolean;
  /** The role may open the CFO dashboard. */
  enabled: boolean;
  /** The sidebar options the role shows; undefined = all of them. */
  modules?: string[];
}

/**
 * What the signed-in user's role allows on the CFO dashboard, from the role's
 * `dashboards.cfo` setting (admin console > Roles > Dashboards). Admins are
 * never kept out. A role with no setting is unrestricted. If the role cannot
 * be read, the dashboard stays open (the same read feeds its own screens).
 */
export const useCfoAccess = (): CfoAccess => {
  const { encrypted_token } = useSelector((state: RootState) => state.auth) as any;
  const { context, roles, loading } = useDirectory();
  const userId: string | undefined = encrypted_token?.userId ? String(encrypted_token.userId) : undefined;
  // undefined = not read yet; null = read, no role found (or the read failed).
  const [roleId, setRoleId] = useState<string | null | undefined>(undefined);

  useEffect(() => {
    if (!context || !userId) return;
    let cancelled = false;
    fetchUserRoleId(context, userId).then((result) => {
      if (cancelled) return;
      setRoleId(result.ok ? result.data : null);
    });
    return () => {
      cancelled = true;
    };
  }, [context, userId]);

  if (!context || !userId || roleId === undefined || loading) return { ready: false, enabled: true };
  const role = roles.find((r) => String(r._id) === roleId);
  if (!role) return { ready: true, enabled: true };
  const access = dashboardAccess(role, "cfo");
  const admin = (role.permissions || []).includes("admin");
  return {
    ready: true,
    enabled: access.enabled || admin,
    modules: admin ? undefined : (access.modules as string[] | undefined),
  };
};
