import { useEffect, useMemo, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { formatForRedis } from "utils/appUtil";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import {
  getGroupKeys,
  searchInUserForService,
} from "../../../../../services/apis/collections/oAuthApis";

export interface Option {
  value: string;
  label: string;
}

const ECO = process.env.REACT_APP_ECO_SYSTEM;

/** Survey responses live on the page under this node, keyed `<userId>:<surveyId>`. */
const SURVEY_NODE = "$.persistent.static.profile.unstructuredAttributes.survey";

/** The org's active `user:survey` forms. */
export const useSurveyOptions = (enabled: boolean = true) => {
  const { projects } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [surveys, setSurveys] = useState<Option[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!enabled || !projects?.userServiceId) return;
    const orgId = formatForRedis(projects.userServiceId);
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: {
          select: {
            index: {
              searchIndex: `${ECO}:query:bulk`,
              searchQuery: `@type:{user\\:survey}@partitions:{'org\\:${orgId}'}@objectStatus:{active}`,
            },
            load: { objectId: "$.objectId", name: "$.info.name" },
          },
          result: { pagination: { offset: 0, limit: 1000 } },
        },
        callback: (response: any[]) => {
          setSurveys(
            (response || [])
              .filter((s) => s?.objectId !== undefined && s?.objectId !== null)
              .map((s) => ({
                value: `${s.objectId}`,
                label: s?.name || "Untitled survey",
              }))
          );
          setLoading(false);
        },
      })
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, projects?.userServiceId]);

  return { surveys, loading };
};

/** The regular and group pages (group = made by "Assign coaches") the signed-in user is a member of (same source as the admin Share dialog). */
export const usePageOptions = (enabled: boolean = true) => {
  const { encrypted_token, projects } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const [pages, setPages] = useState<Option[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!enabled || !projects?.userServiceId || !encrypted_token?.userId) return;
    const orgId = formatForRedis(projects.userServiceId);
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: {
          select: {
            index: {
              searchIndex: `${ECO}:page:updatedAt`,
              searchQuery: `@pageType:{regular|group}@partitions:{org\\:${orgId}}@pageMembers:{${encrypted_token.userId}}`,
              searchOptions: "TIMEOUT 2000",
            },
            load: {
              objectId: "$.objectId",
              title: "$.persistent.static.metadata.title",
              createdAt: "$.persistent.static.metadata.createdAt",
            },
          },
          sortBy: {
            properties: [{ field: "@createdAt", order: "DESC" }],
            max: 100000,
          },
          result: { pagination: { offset: 0, limit: 1000 } },
        },
        callback: (response: any[]) => {
          setPages(
            (response || [])
              .filter((p) => p?.objectId !== undefined && p?.objectId !== null)
              .map((p) => ({
                value: `${p.objectId}`,
                label: p?.title || `Page ${p.objectId}`,
              }))
          );
          setLoading(false);
        },
      })
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, projects?.userServiceId, encrypted_token?.userId]);

  return { pages, loading };
};

/** A player's score on a page: the average of their `rating` answers. */
export interface PlayerRating {
  value: number;
  /** Top of the scale (e.g. 5 for a 1-5 rating question). */
  range: number;
}

/** One coach's rating of a player: the average of their `rating` answers in one stored entry. */
export interface CoachRating {
  /** Who rated: the `addedBy` the Rating popup stores in the entry's metadata. */
  raterId?: string;
  raterName: string;
  surveyId: string;
  value: number;
  range: number;
}

/** Elements of a stored survey config (blocks, or the legacy flat `questions` list). */
const configElements = (config: any): any[] => {
  if (Array.isArray(config?.blocks) && config.blocks.length) {
    return config.blocks.flatMap((block: any) => block?.elements || []);
  }
  return Array.isArray(config?.questions) ? config.questions : [];
};

/**
 * Users who were rated on a page, with their score. Reads the page's survey
 * node: every key is `<userId>:<surveyId>`, holding that responder's answers and
 * a snapshot of the survey config. When `ratingSurveyIds` is given, only entries
 * of those surveys count; otherwise every survey entry on the page does. The
 * score is the average of the entry's `rating`-type answers.
 */
export const fetchRatedUserIds = (
  dispatch: any,
  orgServiceId: string,
  pageId: string,
  ratingSurveyIds?: string[]
): Promise<{
  userIds: string[];
  surveyIds: string[];
  ratings: Record<string, PlayerRating>;
  /** Every rating behind a player's overall score, one per coach (and survey). */
  byPlayer: Record<string, CoachRating[]>;
}> =>
  new Promise((resolve) => {
    dispatch(
      GET_AGGREGATE({
        requestData: {
          select: {
            index: {
              searchIndex: `${ECO}:page:updatedAt`,
              searchQuery: `@partitions:{org\\:${formatForRedis(orgServiceId)}}`,
              searchOptions: "TIMEOUT 5000",
            },
            list: { objectIds: [`${pageId}`] },
            load: { objectId: "$.objectId", survey: SURVEY_NODE },
          },
          result: { pagination: { offset: 0, limit: 10 } },
        },
        callback: (response: any[]) => {
          const survey = response?.[0]?.survey;
          const keys =
            survey && typeof survey === "object" ? Object.keys(survey) : [];
          const entries = keys
            .map((key) => {
              const at = key.indexOf(":");
              if (at <= 0) return undefined;
              // "<player>_<coach>" (per-coach rating) or a bare "<player>" (older entries).
              const responder = key.slice(0, at);
              const split = responder.indexOf("_");
              return {
                key,
                userId: split > 0 ? responder.slice(0, split) : responder,
                raterId: split > 0 ? responder.slice(split + 1) : undefined,
                surveyId: key.slice(at + 1),
              };
            })
            .filter(Boolean) as {
            key: string;
            userId: string;
            raterId?: string;
            surveyId: string;
          }[];
          const counted =
            ratingSurveyIds && ratingSurveyIds.length
              ? entries.filter((e) => ratingSurveyIds.includes(e.surveyId))
              : entries;

          // One score per stored entry (the average of its `rating` answers),
          // credited to whoever the entry says added it.
          const byPlayer: Record<string, CoachRating[]> = {};
          counted.forEach((e) => {
            const entry = survey[e.key];
            const answers = entry?.answers?.[e.key] || {};
            const values: number[] = [];
            let range = 0;
            configElements(entry?.config)
              .filter((el: any) => el?.type === "rating")
              .forEach((el: any) => {
                const value = Number(answers[el.id]);
                if (!Number.isFinite(value)) return;
                values.push(value);
                range = Math.max(range, Number(el.range) || 5);
              });
            if (!values.length) return;
            const avg = values.reduce((sum, v) => sum + v, 0) / values.length;
            const meta = entry?.metadata || {};
            const raterId =
              e.raterId ?? (meta.addedBy !== undefined ? `${meta.addedBy}` : undefined);
            (byPlayer[e.userId] = byPlayer[e.userId] || []).push({
              raterId,
              raterName: meta.name || (raterId ? `Coach #${raterId}` : "Unknown coach"),
              surveyId: e.surveyId,
              value: Math.round(avg * 10) / 10,
              range,
            });
          });
          // Overall = the average across coaches' scores.
          const ratings: Record<string, PlayerRating> = {};
          Object.keys(byPlayer).forEach((userId) => {
            const list = byPlayer[userId];
            const avg = list.reduce((sum, c) => sum + c.value, 0) / list.length;
            ratings[userId] = {
              value: Math.round(avg * 10) / 10,
              range: Math.max(...list.map((c) => c.range)),
            };
          });

          resolve({
            userIds: Array.from(new Set(counted.map((e) => e.userId))),
            surveyIds: Array.from(new Set(counted.map((e) => e.surveyId))),
            ratings,
            byPlayer,
          });
        },
      })
    );
  });

/**
 * The org's teams: admin projects whose type is "org". The project list the app
 * receives at startup drops each project's type, so it is read from the admin
 * user's `admin.project` (items + types) directly.
 */
/** A team option, with what is needed to find its members. */
export interface TeamOption extends Option {
  groupId?: string;
  liveUserIds: string[];
  /** The team's coaches (`managerLiveUserIds`). */
  managerLiveUserIds: string[];
}

export const useOrgTeamOptions = (enabled: boolean = true) => {
  const { projects } = useSelector((state: RootState) => state.auth);
  const [teams, setTeams] = useState<TeamOption[]>([]);
  const [loading, setLoading] = useState(false);
  // True once the lookup has answered, found or not.
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    if (!enabled || !projects?.userServiceId || !projects?.adminUserId) return;
    let active = true;
    setLoading(true);
    searchInUserForService({
      serviceId: projects.userServiceId,
      data: {
        paths: ["$"],
        returnPaths: ["$..admin.project"],
        resultType: "value",
        objectId: `${projects.adminUserId}`,
      },
    })
      .then((res: any) => {
        if (!active) return;
        const node = res?.data?.[0]?.[0] || {};
        // Id of the project type named "org" (an array of { _id, name }).
        const types: any[] = Array.isArray(node?.types) ? node.types : [];
        const orgType = types.find(
          (t) => `${t?.name ?? ""}`.trim().toLowerCase() === "org"
        );
        const orgTypeId = orgType?._id ?? "org";
        setTeams(
          Object.values(node?.items || {})
            .filter(
              (item: any) =>
                item && typeof item === "object" && `${item.typeId}` === `${orgTypeId}`
            )
            .map((item: any) => ({
              value: `${item._id}`,
              label: item?.name || `Team ${item._id}`,
              groupId: item?.groupId ? `${item.groupId}` : undefined,
              liveUserIds: (item?.liveUserIds || []).map((id: any) => `${id}`),
              managerLiveUserIds: (item?.managerLiveUserIds || []).map(
                (id: any) => `${id}`
              ),
            }))
        );
        setLoading(false);
        setLoaded(true);
      })
      .catch(() => {
        if (active) {
          setLoading(false);
          setLoaded(true);
        }
      });
    return () => {
      active = false;
    };
  }, [enabled, projects?.userServiceId, projects?.adminUserId]);

  return { teams, loading, loaded };
};

/**
 * User ids on a team: the members of its group (what "Add to group" writes)
 * together with the team's own `liveUserIds`.
 */
export const fetchTeamMemberIds = async (team: TeamOption): Promise<string[]> => {
  const ids = new Set<string>(team.liveUserIds || []);
  if (team.groupId) {
    try {
      const res: any = await getGroupKeys({ data: { queryId: Number(team.groupId) } });
      (res?.data?.keys || [])
        .filter((key: string) => key.includes(":user:"))
        .forEach((key: string) => ids.add(key.split(":")[2]));
    } catch (e) {
      // Fall back to the team's own liveUserIds.
    }
  }
  return Array.from(ids);
};

/**
 * Everyone on the pages the user is a member of, other than one-to-one
 * "friend" pages (those are CFO / payment chats, not a team). Includes coaches
 * and staff; the Players list drops them because it only lists player roles.
 */
/**
 * Who shares the coach's pages: the member user ids, and the beamIds attached to
 * a member through `associatedBeamIds` (a parent's kids are on the page that way,
 * they are not members of their own).
 */
export interface PageMembers {
  ids: string[];
  associatedBeamIds: string[];
}

export const fetchPageMemberIds = (dispatch: any, userId: string): Promise<PageMembers> =>
  new Promise((resolve) => {
    dispatch(
      GET_AGGREGATE({
        requestData: {
          select: {
            index: {
              searchIndex: `${ECO}:pageUpdatedAtIndex`,
              searchQuery: `@pageMembers:{${userId}}`,
              searchOptions: "VERBATIM TIMEOUT 10000",
            },
            load: {
              pageId: "$.objectId",
              type: "$.persistent.static.metadata.type",
              members: "$.persistent.static.metadata.members.users",
            },
          },
          sortBy: { properties: [{ field: "@updatedAt", order: "DESC" }], max: 200 },
        },
        callback: (rows: any) => {
          const ids = new Set<string>();
          const beamIds = new Set<string>();
          (Array.isArray(rows) ? rows : []).forEach((row: any) => {
            if (row?.type === "friend") return;
            Object.keys(row?.members || {}).forEach((id) => {
              ids.add(id);
              const member = row.members[id];
              (Array.isArray(member?.associatedBeamIds) ? member.associatedBeamIds : []).forEach(
                (a: any) => {
                  if (a?.beamId && a.beamId !== member?.beamId) beamIds.add(`${a.beamId}`);
                }
              );
            });
          });
          ids.delete(`${userId}`);
          resolve({ ids: Array.from(ids), associatedBeamIds: Array.from(beamIds) });
        },
      })
    );
  });

/**
 * What a coach works with: the teams they manage and the ids of everyone on
 * those teams. Shared by the Dashboard and the Players page so both agree.
 * `scoped` is false for everyone else (no scoping, `teams` is empty).
 */
export interface CoachScope {
  scoped: boolean;
  /** The coach's own teams (all org teams are NOT listed here). */
  teams: TeamOption[];
  /** Members of those teams; undefined until they have been read. */
  memberIds: string[] | undefined;
  /** BeamIds attached to members of the coach's pages (a parent's kids); undefined until read. */
  memberBeamIds: string[] | undefined;
}

export const useCoachScope = (ownTeamsUserId: any): CoachScope => {
  const scoped = ownTeamsUserId !== undefined && ownTeamsUserId !== null;
  const dispatch = useDispatch();
  const { teams: allTeams, loaded } = useOrgTeamOptions(scoped);
  const teams = useMemo(
    () =>
      scoped
        ? allTeams.filter((t) => t.managerLiveUserIds.includes(`${ownTeamsUserId}`))
        : [],
    [allTeams, scoped, ownTeamsUserId]
  );
  const [memberIds, setMemberIds] = useState<string[] | undefined>(undefined);
  const [memberBeamIds, setMemberBeamIds] = useState<string[] | undefined>(undefined);

  useEffect(() => {
    if (!scoped) {
      setMemberIds(undefined);
      setMemberBeamIds(undefined);
      return;
    }
    if (!loaded) return;
    let active = true;
    // The coach's own teams plus every non-friend page they are a member of.
    Promise.all([
      Promise.all(teams.map((team) => fetchTeamMemberIds(team))),
      fetchPageMemberIds(dispatch, `${ownTeamsUserId}`),
    ]).then(([teamLists, pages]) => {
      if (!active) return;
      const ids = Array.from(new Set(([] as string[]).concat(...teamLists, pages.ids)));
      console.log("[Coach] scope", {
        teams: teams.map((t) => t.label),
        memberIds: ids,
        memberBeamIds: pages.associatedBeamIds,
      });
      setMemberIds(ids);
      setMemberBeamIds(pages.associatedBeamIds);
    });
    return () => {
      active = false;
    };
  }, [scoped, loaded, teams, dispatch, ownTeamsUserId]);

  return { scoped, teams, memberIds, memberBeamIds };
};
