import React, { FC, ReactNode } from "react";

import NoDashboardAccess from "../../School3/NoDashboardAccess";
import { useCfoAccess } from "./directory/useCfoAccess";

/**
 * Keeps a role whose CFO dashboard is switched off out of it, and hands the
 * rest the sidebar options their role shows (undefined = all of them). Sits
 * inside the DirectoryProvider, which supplies the roles it reads.
 */
const CfoAccessGate: FC<{ children: (allowedModules?: string[]) => ReactNode }> = ({ children }) => {
  const access = useCfoAccess();
  if (access.ready && !access.enabled) return <NoDashboardAccess dashboard="CFO dashboard" />;
  return <>{children(access.modules)}</>;
};

export default CfoAccessGate;
