import React, { FC } from "react";
import { Empty } from "antd";

/**
 * What every Stripe-backed screen shows before the link's token has been
 * decrypted, or when the link carries none (see `useStripeIdentity`).
 * No request is made in this state.
 */
const StripeSignInEmpty: FC = () => (
  <div className="cfo-stripe__empty">
    <Empty
      image={Empty.PRESENTED_IMAGE_SIMPLE}
      description={
        <>
          <strong>Sign in to view Stripe payments.</strong>
          <br />
          <span className="cfo-muted">
            No user id is available for the payment workflow. Open the dashboard through a link that carries your
            token.
          </span>
        </>
      }
    />
  </div>
);

export default StripeSignInEmpty;
