import React, { FC, useMemo, useState } from "react";
import { Alert, Button, Col, Input, Row, Select, Table, Tag, Tooltip } from "antd";
import { ReloadOutlined, SearchOutlined } from "@ant-design/icons";
import moment from "moment";
import { pushNotification } from "utils/notifications";

import {
  BillableEntity,
  BillingStatus,
  Domain,
  EntityKind,
  PaymentRequestTarget,
  ProjectRollup,
} from "../types";
import { DOMAIN_LABELS, getProject } from "../mockData";
import { peopleFor } from "../mockEntities";
import { BILLING_STATUS_LABELS, billingStatusOf } from "../selectors";
import { directoryGroups, directoryLabel } from "../menu";
import { payeeColumns, playerColumns, projectColumns } from "../entityColumns";
import SendPaymentRequestModal from "../SendPaymentRequestModal";
import PaymentConfigEditor from "../PaymentConfigEditor";
import { useStripeWindow } from "../stripe/useStripeWindow";
import { dominantCurrency } from "../stripe/chargeModel";
import StripeSignInEmpty from "../stripe/StripeSignInEmpty";
import { useCfoSession } from "../payments/useCfoSession";
import { useDirectory } from "../directory/useDirectory";
import { groupByKid } from "../../../School3/Dashboard/Student/familyRows";
import {
  Membership,
  PeopleKind,
  figuresByCustomer,
  membershipsByUser,
  toBillableEntity,
  toFamilyEntity,
  toEventRollup,
  toProjectRollup,
  toTeamRollup,
} from "../directory/directoryModel";
import { useCfoSocket } from "../payments/useCfoSocket";
import { usePaymentConfigs } from "../payments/paymentConfigs";
import { liveMembers, liveProjectSummary, projectForPlayer, seedConfig } from "../payments/liveTargets";
import { LiveDraftInput } from "../SendPaymentRequest/draft";

interface Props {
  kind: EntityKind;
  onKindChange: (kind: EntityKind) => void;
  domain: Domain;
}

interface EditTarget {
  configId: string | null;
  subject: string;
}

const STATUS_OPTIONS = (Object.keys(BILLING_STATUS_LABELS) as BillingStatus[]).map(
  (value) => ({ value, label: BILLING_STATUS_LABELS[value] })
);

const LIVE_KINDS: EntityKind[] = ["players", "coaches", "staff", "teams", "events"];

/**
 * The Directory: one table page for every entity group - players, teams,
 * events, coaches, staff and vendors - picked with the select in the
 * page head rather than six sidebar buttons. The columns differ per
 * kind; the chrome, filters, status chip and the two actions do not.
 *
 * Players, coaches and staff are the org's users by role; teams are its
 * groups; events are its event pages (see `directory/`). Each user's
 * Stripe customer id ties the dashboard's charges to the person, and a
 * team sums its members. Plans, due dates and outstanding balances are
 * not recorded anywhere yet and stay empty. Vendors have no source and
 * remain placeholder data.
 */
const EntityScreen: FC<Props> = ({ kind, onKindChange, domain }) => {
  const [search, setSearch] = useState("");
  const [projectFilter, setProjectFilter] = useState<string | undefined>();
  const [statusFilter, setStatusFilter] = useState<BillingStatus | undefined>();
  const [requestTarget, setRequestTarget] = useState<PaymentRequestTarget | null>(null);
  const [requestLive, setRequestLive] = useState<(LiveDraftInput & { subject: string }) | null>(null);
  const [editTarget, setEditTarget] = useState<EditTarget | null>(null);

  const directory = useDirectory();
  const session = useCfoSession();
  const win = useStripeWindow();
  const socket = useCfoSocket();
  const paymentConfigs = usePaymentConfigs(directory.context);

  const labels = DOMAIN_LABELS[domain];
  const isProjectKind = kind === "teams" || kind === "events";
  const isLive = LIVE_KINDS.indexOf(kind) !== -1;
  const title = directoryLabel(kind, domain);
  const groups = useMemo(() => directoryGroups(domain), [domain]);

  /* ---- live rows ---- */

  const currency = useMemo(() => dominantCurrency(win.rows), [win.rows]);
  const figures = useMemo(() => figuresByCustomer(win.rows), [win.rows]);
  const memberOf = useMemo(
    () => membershipsByUser(directory.groups, directory.projects),
    [directory.groups, directory.projects]
  );
  const usersById = useMemo(() => new Map(directory.users.map((u) => [u.id, u])), [directory.users]);

  const livePeople = useMemo(() => {
    const byKind: Record<PeopleKind, BillableEntity[]> = { players: [], coaches: [], staff: [] };
    directory.users.forEach((user) => {
      byKind[user.kind].push(toBillableEntity(user, domain, memberOf.get(user.id) || [], figures, currency));
    });
    (Object.keys(byKind) as PeopleKind[]).forEach((k) => byKind[k].sort((a, b) => a.name.localeCompare(b.name)));
    /* Kids: one row per kid, both parents on it. The parents are the users,
       so the teams are theirs (both parents' teams, each once). */
    groupByKid(directory.families).forEach((row) => {
      const teams = new Map<string, Membership>();
      row.parents.forEach((p) => (memberOf.get(p.id) || []).forEach((m) => teams.set(m.id, m)));
      byKind.players.push(toFamilyEntity(row, domain, Array.from(teams.values()), figures, currency, directory.roles));
    });
    return byKind;
  }, [directory.users, directory.families, directory.roles, domain, memberOf, figures, currency]);

  /* Teams: the organisation's groups and its projects, in one table. */
  const teams = useMemo(
    () =>
      directory.groups
        .map((group) => toTeamRollup(group, domain, usersById, figures, currency))
        .concat(directory.projects.map((project) => toProjectRollup(project, domain, usersById, figures, currency)))
        .sort((a, b) => a.name.localeCompare(b.name)),
    [directory.groups, directory.projects, domain, usersById, figures, currency]
  );

  const events = useMemo(
    () =>
      directory.events
        .map((page) => toEventRollup(page, domain, currency))
        .sort((a, b) => (b.startsAt || 0) - (a.startsAt || 0)),
    [directory.events, domain, currency]
  );

  const vendors = useMemo(() => peopleFor("vendors", domain), [domain]);

  const countFor = (k: EntityKind): number => {
    switch (k) {
      case "teams":
        return teams.length;
      case "events":
        return events.length;
      case "vendors":
        return vendors.length;
      default:
        return livePeople[k].length;
    }
  };

  const projectOptions = useMemo(
    () =>
      directory.groups
        .map((group) => ({ value: group._id, label: group.name || group._id }))
        .concat(directory.projects.map((p) => ({ value: p._id, label: p.name || p.customId || p._id })))
        .sort((a, b) => a.label.localeCompare(b.label)),
    [directory.groups, directory.projects]
  );

  const term = search.trim().toLowerCase();

  const projectRows = useMemo<ProjectRollup[]>(() => {
    if (!isProjectKind) return [];
    return (kind === "teams" ? teams : events).filter((p) => {
      if (statusFilter && p.status !== statusFilter) return false;
      if (term && `${p.name} ${p.kind}`.toLowerCase().indexOf(term) === -1) return false;
      return true;
    });
  }, [isProjectKind, kind, teams, events, statusFilter, term]);

  const peopleRows = useMemo<BillableEntity[]>(() => {
    if (isProjectKind) return [];
    const source = kind === "vendors" ? vendors : livePeople[kind as PeopleKind];
    return source.filter((e) => {
      if (projectFilter && e.projectIds.indexOf(projectFilter) === -1) return false;
      if (statusFilter && billingStatusOf(e.billing) !== statusFilter) return false;
      if (term) {
        const haystack = `${e.name} ${e.role} ${e.email} ${e.phone} ${e.household || ""} ${(e.projectNames || []).join(" ")}`.toLowerCase();
        if (haystack.indexOf(term) === -1) return false;
      }
      return true;
    });
  }, [isProjectKind, kind, vendors, livePeople, projectFilter, statusFilter, term]);

  /* ---- actions ---- */

  const allPeople = useMemo(
    () => livePeople.players.concat(livePeople.coaches, livePeople.staff),
    [livePeople]
  );

  /** Opens the wizard on a live target with its roster and seed configuration. */
  const openLiveRequest = (target: PaymentRequestTarget, subject: string, paymentConfigId: string | null | undefined) => {
    const members = liveMembers(target, directory, allPeople);
    setRequestLive({ members, config: seedConfig(subject, paymentConfigId, paymentConfigs.byId), subject });
    setRequestTarget(target);
  };

  const sendForPerson = (entity: BillableEntity) => {
    if (entity.kind === "vendor") {
      pushNotification("Vendors are placeholder data: there is no user to send a request to.", "warning", "TOP_CENTER", 2500);
      return;
    }
    if (entity.kind === "player" && entity.payer) {
      /* A kid is billed through their parent, who is the user the request goes to. */
      const payer = entity.payer;
      const payee: BillableEntity = {
        ...entity,
        id: payer.id,
        name: payer.name,
        role: "Parent",
        email: payer.email || "",
        phone: payer.phone || "",
        stripeCustomerId: payer.stripeCustomerId,
        household: payer.email || "",
        payer: undefined,
      };
      openLiveRequest({ project: null, payee }, `${entity.name} (${payer.name})`, null);
      return;
    }
    if (entity.kind === "player") {
      const project = projectForPlayer(entity, teams, domain);
      openLiveRequest({ project, focusMemberIds: [entity.id] }, entity.name, project.paymentConfigId);
      return;
    }
    openLiveRequest({ project: null, payee: entity }, entity.name, null);
  };

  const editForPerson = (entity: BillableEntity) => {
    if (entity.kind === "player") {
      const project = entity.projectIds[0] ? getProject(entity.projectIds[0]) : null;
      setEditTarget({
        configId: project ? project.paymentConfigId : null,
        subject: project ? `${entity.name} (${project.name})` : entity.name,
      });
      return;
    }
    setEditTarget({ configId: entity.paymentConfigId, subject: entity.name });
  };

  const sendForProject = (project: ProjectRollup) => {
    if (project.group === "event") {
      pushNotification("Event pages carry no participants yet, so there is no one to send a request to.", "warning", "TOP_CENTER", 2500);
      return;
    }
    openLiveRequest({ project: liveProjectSummary(project) }, project.name, project.paymentConfigId);
  };

  const editForProject = (project: ProjectRollup) =>
    setEditTarget({ configId: project.paymentConfigId, subject: project.name });

  const columns = useMemo(() => {
    if (kind === "players") {
      return playerColumns({ domain, onSend: sendForPerson, onEdit: editForPerson });
    }
    if (kind === "coaches" || kind === "staff" || kind === "vendors") {
      return payeeColumns(kind, { domain, onSend: sendForPerson, onEdit: editForPerson });
    }
    return projectColumns(kind === "teams" ? "team" : "event", {
      domain,
      onSend: sendForProject,
      onEdit: editForProject,
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind, domain]);

  const count = isProjectKind ? projectRows.length : peopleRows.length;

  /* ---- state of the feed ---- */

  const sourceTag = isLive ? (
    <Tooltip
      title={
        kind === "events"
          ? "Event pages of the organisation. Participants and payments are not recorded on them yet."
          : kind === "teams"
          ? `Groups and projects of the organisation. Billed and collected sum each member's Stripe charges over the dashboard's range (${moment(win.range.from).format("D MMM YYYY")} - ${moment(win.range.to).format("D MMM YYYY")}). Plans and due dates are not recorded yet.`
          : `Users of the organisation by role. Billed and collected are the person's Stripe charges over the dashboard's range (${moment(win.range.from).format("D MMM YYYY")} - ${moment(win.range.to).format("D MMM YYYY")}), matched by their Stripe customer id. Plans, due dates and outstanding balances are not recorded yet.`
      }
    >
      <Tag className="cfo-side-note" color="green">
        Live
      </Tag>
    </Tooltip>
  ) : (
    <Tooltip title="Vendors are placeholder data: no vendor or payable source exists in the platform yet.">
      <Tag className="cfo-side-note">Mock data</Tag>
    </Tooltip>
  );

  /* Sign-in only when the link has no token; while it is being read the table shows its spinner. */
  const feedNotice = !isLive ? null : session === "no-token" ? (
    <StripeSignInEmpty />
  ) : session === "pending" ? null : directory.errors.length > 0 ? (
    <Alert
      type="warning"
      showIcon
      className="cfo-stripe__notice"
      message="Some directory sources could not be loaded."
      description={directory.errors.join(" · ")}
      action={
        <Button size="small" onClick={directory.refresh}>
          Retry
        </Button>
      }
    />
  ) : !directory.ready ? (
    <Alert
      type="info"
      showIcon
      className="cfo-stripe__notice"
      message="Waiting for the organisation…"
      description="The directory lists users, groups, projects and events once the link's token has been read."
    />
  ) : null;

  return (
    <React.Fragment>
      <Row>
        <Col span={24} className="cfo-page-head">
          <div className="cfo-directory-head">
            <div>
              <h2 style={{ marginBottom: 4 }}>
                Directory {sourceTag}
              </h2>
              <p style={{ marginBottom: 0, color: "#8c8c8c" }}>
                Directory &gt; {title} · {count} {count === 1 ? "record" : "records"}
                {isLive && directory.loadedAt ? ` · loaded ${moment(directory.loadedAt).format("HH:mm:ss")}` : ""}
              </p>
            </div>
            <Select
              className="cfo-directory-select"
              value={kind}
              onChange={(value) => {
                setSearch("");
                setProjectFilter(undefined);
                setStatusFilter(undefined);
                onKindChange(value);
              }}
              dropdownMatchSelectWidth={false}
              optionLabelProp="label"
            >
              {groups.map((group) => (
                <Select.OptGroup key={group.label} label={group.label}>
                  {group.options.map((option) => (
                    <Select.Option key={option.value} value={option.value} label={option.label}>
                      <span className="cfo-directory-option">
                        <span>{option.label}</span>
                        <span className="cfo-directory-option__count">{countFor(option.value)}</span>
                      </span>
                    </Select.Option>
                  ))}
                </Select.OptGroup>
              ))}
            </Select>
          </div>

          <div className="cfo-page-toolbar">
            <Input
              allowClear
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{ width: 240, flexShrink: 0 }}
              placeholder="Search by name"
              prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
            />
            {!isProjectKind && kind !== "vendors" && (
              <Select
                allowClear
                showSearch
                placeholder={`Filter by ${labels.navSingular.team.toLowerCase()}`}
                options={projectOptions}
                value={projectFilter}
                onChange={(value) => setProjectFilter(value)}
                filterOption={(input, option) =>
                  (option?.label ?? "").toString().toLowerCase().includes(input.toLowerCase())
                }
                style={{ width: 220, flexShrink: 0 }}
              />
            )}
            <Select
              allowClear
              placeholder="Status"
              options={STATUS_OPTIONS}
              value={statusFilter}
              onChange={(value) => setStatusFilter(value)}
              style={{ width: 150, flexShrink: 0 }}
            />
            {isLive && (
              <Button type="text" icon={<ReloadOutlined />} loading={directory.loading} onClick={directory.refresh}>
                Refresh
              </Button>
            )}
          </div>
        </Col>
      </Row>

      {feedNotice}

      {(!isLive || session !== "no-token") && (
        <Row gutter={20} className="scrollable-table mt-3" style={{ display: "grid" }}>
          <Col span={24} style={{ overflow: "auto" }}>
            {isProjectKind ? (
              <Table<ProjectRollup>
                rowKey="id"
                loading={isLive && (session === "pending" || directory.loading)}
                dataSource={projectRows}
                columns={columns as any}
                scroll={{ x: true }}
                pagination={{ pageSize: 15, showSizeChanger: false }}
              />
            ) : (
              <Table<BillableEntity>
                rowKey="id"
                loading={isLive && (session === "pending" || directory.loading)}
                dataSource={peopleRows}
                columns={columns as any}
                scroll={{ x: true }}
                pagination={{ pageSize: 15, showSizeChanger: false }}
              />
            )}
          </Col>
        </Row>
      )}

      <SendPaymentRequestModal
        open={!!requestTarget}
        target={requestTarget}
        domain={domain}
        live={requestLive || undefined}
        socket={socket}
        context={directory.context}
        onClose={() => {
          setRequestTarget(null);
          setRequestLive(null);
        }}
      />

      <PaymentConfigEditor
        open={!!editTarget}
        configId={editTarget ? editTarget.configId : null}
        subject={editTarget ? editTarget.subject : ""}
        onClose={() => setEditTarget(null)}
      />
    </React.Fragment>
  );
};

export default EntityScreen;
