/**
 * Payment requests — the send itself. For every recipient: find or
 * create their friend page with the CFO, write the request record,
 * put the record's reference on the page, then post the pay message
 * and mark the record sent.
 *
 * The record comes before the message: a request the ledger cannot see
 * is the state this exists to remove, so a recipient whose record
 * cannot be written is not messaged. A retry of a recipient reuses
 * their record and message ids (`previous` outcomes carry them), so a
 * request is never listed twice and a resend after a lost ack is at
 * worst a duplicate message, never a lost one.
 *
 * Recipients run a few at a time; one failure never stops the others,
 * and every recipient ends with an outcome the modal can show and retry.
 */
import { SocketTopics } from "constants/enums";
import { generateUUID } from "utils/appUtil";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";

import { Domain, PaymentRequestDraft, ProjectMember, ProjectSummary } from "../types";
import { OrgContext } from "../directory/directoryApi";
import { CreatePageReplies, ensureFriendPage } from "./friendPage";
import { groupMembersPublishTopic, pageMessageEnvelope } from "./pageMessages";
import { buildPayMessage, computePayRequest } from "./paymentRequestMessage";
import {
  DeliveryStatus,
  PaymentRequestRecord,
  RecordPatch,
  buildPaymentRequestRecord,
  createPaymentRequestRecord,
  linkPaymentRequestKeys,
  updatePaymentRequestRecord,
} from "./paymentRequestRecord";
import { pageRequestRef, paymentRequestPageChanges, updatePage } from "./pageApi";

/**
 * pending → page-found | page-created → recorded → sent, or
 * unconfirmed (the broker never acknowledged; the message may have
 * arrived) or failed (with the reason).
 */
export type SendStatus = "pending" | "page-found" | "page-created" | "recorded" | "sent" | "unconfirmed" | "failed";

export interface SendOutcome {
  memberId: string;
  name: string;
  status: SendStatus;
  pageId?: string;
  requestId?: string;
  /** The BDS record of the request; set once it is written, kept across retries. */
  paymentRequestId?: string;
  connectionMessageId?: string;
  /** The run the record belongs to; a retry keeps the original. */
  batchId?: string;
  attempts?: number;
  error?: string;
}

export interface SendDeps {
  socket: ISocket;
  context: OrgContext;
  me: { id: string; beamId?: string | null };
  draft: PaymentRequestDraft;
  members: ProjectMember[];
  subject: string;
  /** The team or project the request is billed through; null for a direct request. */
  project: ProjectSummary | null;
  domain: Domain;
  /** Outcomes of an earlier run of the same draft: a retry reuses their records and ids. */
  previous?: SendOutcome[];
  onProgress?: (outcome: SendOutcome) => void;
}

/**
 * One recipient at a time: every create shares the connection's
 * `createPage/reply` topic, and while replies echo the request id, a
 * sequential run also keeps the no-id fallback in `CreatePageReplies`
 * unambiguous. Raise once the echo is confirmed in production logs.
 */
const CONCURRENCY = 1;
const PUBLISH_TIMEOUT_MS = 15_000;

const PUBLISH_TIMEOUT = "PUBLISH_TIMEOUT";

const timeoutError = (): Error => {
  const error: any = new Error("message publish timed out");
  error.code = PUBLISH_TIMEOUT;
  return error;
};

const isTimeout = (e: any): boolean => !!e && e.code === PUBLISH_TIMEOUT;

/** Publishes a message and resolves on the broker's ack; rejects when the ack fails or never comes. */
const publishMessage = (socket: ISocket, topic: string, envelope: unknown): Promise<void> =>
  new Promise<void>((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(timeoutError());
    }, PUBLISH_TIMEOUT_MS);
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      topic,
      wrapRequestPayload(envelope, generateUUID()),
      (ack: { status: boolean }) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        if (ack && ack.status !== false) resolve();
        else reject(new Error("message could not be published"));
      }
    );
  });

const sendToOne = async (
  deps: SendDeps,
  replies: CreatePageReplies,
  batchId: string,
  member: ProjectMember
): Promise<SendOutcome> => {
  const report = (outcome: SendOutcome) => {
    if (deps.onProgress) deps.onProgress(outcome);
    return outcome;
  };
  /* A retry picks up where the recipient's last run left off. */
  const prior = (deps.previous || []).find((o) => o.memberId === member.id && !!o.paymentRequestId);
  let recordId: string | null = prior ? prior.paymentRequestId || null : null;
  const attempts = (prior && prior.attempts ? prior.attempts : 0) + 1;
  const base: SendOutcome = {
    memberId: member.id,
    name: member.name,
    status: "pending",
    paymentRequestId: recordId || undefined,
    requestId: prior ? prior.requestId : undefined,
    connectionMessageId: prior ? prior.connectionMessageId : undefined,
    batchId: (prior && prior.batchId) || batchId,
    attempts,
  };
  report(base);
  if (String(member.id) === String(deps.me.id)) {
    return report({ ...base, status: "failed", error: "Cannot send a payment request to yourself" });
  }

  /** Writes delivery state onto the record; a failed write is logged, the outcome is still reported. */
  const patch = async (change: RecordPatch) => {
    if (!recordId) return;
    try {
      await updatePaymentRequestRecord(deps.context, recordId, change);
    } catch (e: any) {
      console.warn(`payment request ${recordId}: record not updated: ${e?.message || e}`); // eslint-disable-line no-console
    }
  };

  try {
    const page = await ensureFriendPage({
      replies,
      context: deps.context,
      me: deps.me,
      friend: { id: member.id, beamId: member.beamId || null },
    });
    report({ ...base, status: page.created ? "page-created" : "page-found", pageId: page.pageId });

    const now = Date.now();
    const request = computePayRequest(deps.draft, member.id, now);
    const requestId = base.requestId || generateUUID();
    const connectionMessageId = base.connectionMessageId || generateUUID();
    const record: PaymentRequestRecord = buildPaymentRequestRecord({
      context: deps.context,
      domain: deps.domain,
      batchId: base.batchId || batchId,
      requestId,
      connectionMessageId,
      me: deps.me,
      member,
      project: deps.project,
      subject: deps.subject,
      request,
      page: { id: page.pageId, created: page.created },
      now,
    });

    if (recordId) {
      await updatePaymentRequestRecord(deps.context, recordId, { delivery: "sending", attempts, error: null });
    } else {
      recordId = await createPaymentRequestRecord(deps.context, record);
    }
    const recorded: SendOutcome = {
      ...base,
      status: "recorded",
      pageId: page.pageId,
      paymentRequestId: recordId,
      requestId,
      connectionMessageId,
    };
    report(recorded);

    /* The page's side of the link; the send goes on without it, the record says it is missing. */
    const link = await updatePage(deps.context, page.pageId, paymentRequestPageChanges(pageRequestRef(recordId, record), now));
    if (link.ok === false) await patch({ page: { id: page.pageId, created: page.created, linkError: link.error } });

    const message = buildPayMessage({
      request,
      requestId,
      paymentRequestId: recordId,
      recipient: { id: member.id, name: member.name },
      sender: { id: deps.me.id },
      subject: deps.subject,
      now,
    });
    const envelope = pageMessageEnvelope({
      connectionId: deps.context.connectionId,
      userId: deps.me.id,
      pageId: page.pageId,
      message,
      connectionMessageId,
      now,
    });
    try {
      await publishMessage(deps.socket, groupMembersPublishTopic(deps.context.connectionId, page.pageId), envelope);
    } catch (e: any) {
      const delivery: DeliveryStatus = isTimeout(e) ? "unconfirmed" : "failed";
      const error = e?.message || "send failed";
      await patch({ delivery, error });
      return report({ ...recorded, status: delivery, error });
    }

    await patch({ delivery: "sent", sentAt: Date.now(), error: null });
    await linkPaymentRequestKeys(deps.context, recordId, record);
    return report({ ...recorded, status: "sent" });
  } catch (e: any) {
    const error = e?.message || "send failed";
    await patch({ delivery: "failed", error });
    return report({ ...base, status: "failed", paymentRequestId: recordId || undefined, error });
  }
};

/**
 * Sends the draft to every member in `deps.members` (the modal passes
 * the selected recipients, or the failed ones on a retry). Resolves with
 * one outcome per member, in the input order.
 */
export const sendPaymentRequests = async (deps: SendDeps): Promise<SendOutcome[]> => {
  const replies = new CreatePageReplies(deps.socket, deps.context.connectionId);
  const batchId = generateUUID();
  const outcomes: SendOutcome[] = new Array(deps.members.length);
  try {
    replies.open();
    for (let i = 0; i < deps.members.length; i += CONCURRENCY) {
      const batch = deps.members.slice(i, i + CONCURRENCY);
      const results = await Promise.all(batch.map((member) => sendToOne(deps, replies, batchId, member)));
      results.forEach((outcome, j) => {
        outcomes[i + j] = outcome;
      });
    }
  } finally {
    replies.close();
  }
  return outcomes;
};
