import React, { FC } from "react";
import { Result } from "antd";

/**
 * Shown when the signed-in user's role has this dashboard switched off in the
 * admin console (Roles > Dashboards). It hides the screens; it is not a data
 * rule, so a role that is meant to be kept out of data needs a backend rule too.
 */
const NoDashboardAccess: FC<{ dashboard: string }> = ({ dashboard }) => (
  <Result
    status="403"
    title="No access"
    subTitle={`Your role does not have access to the ${dashboard}. Ask an administrator to turn it on for your role.`}
  />
);

export default NoDashboardAccess;
