import React, { FC, useEffect, useRef, useState } from "react";
import { Button, Modal, Select } from "antd";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { searchInUserForService } from "../../../../../services/apis/collections/oAuthApis";
import { usePageOptions, useSurveyOptions } from "./ratingSources";

/**
 * Rating popup for a player: pick a survey and a page, then load the survey
 * form for that player. Surveys are the org's active `user:survey` BDS objects;
 * pages are the regular pages the signed-in user is a member of (the same
 * source the admin Share dialog uses).
 */
const RatingModal: FC<{
  open: boolean;
  user?: { userId: any; name?: string };
  onClose: () => void;
}> = ({ open, user, onClose }) => {
  const { encrypted_token, projects } = useSelector(
    (state: RootState) => state.auth
  );

  // Both lists reload each time the popup opens.
  const { surveys, loading: surveysLoading } = useSurveyOptions(open);
  const { pages, loading: pagesLoading } = usePageOptions(open);

  const [surveyId, setSurveyId] = useState<string | undefined>(undefined);
  const [pageId, setPageId] = useState<string | undefined>(undefined);
  // The form is only shown after "Load form", with the values used at that time.
  const [formUrl, setFormUrl] = useState<string | undefined>(undefined);
  const [loadingForm, setLoadingForm] = useState(false);
  // Name of the signed-in user (who adds the rating), read once from their profile.
  const addedByNameRef = useRef<string | undefined>(undefined);
  // The same name, for showing in the popup.
  const [addedByName, setAddedByName] = useState<string | undefined>(undefined);

  const fetchAddedByName = async (): Promise<string> => {
    if (addedByNameRef.current !== undefined) return addedByNameRef.current;
    const userId = encrypted_token?.userId;
    const serviceId =
      encrypted_token?.cudbServiceId ||
      encrypted_token?.serviceId ||
      projects?.userServiceId;
    if (userId === undefined || !serviceId) return "";
    try {
      const res: any = await searchInUserForService({
        serviceId,
        data: {
          objectId: `${userId}`,
          paths: ["$"],
          returnPaths: ["$.persistent.static.live"],
          resultType: "value",
        },
      });
      const live = res?.data?.[0]?.[0];
      const profile = live?.profile;
      const name =
        `${profile?.firstName ?? ""} ${profile?.lastName ?? ""}`.trim() ||
        live?.beamIds?.[0] ||
        "";
      addedByNameRef.current = name;
      return name;
    } catch (e) {
      return "";
    }
  };

  // Start from a clean form whenever the popup opens (or for another player).
  useEffect(() => {
    if (!open) return;
    setSurveyId(undefined);
    setPageId(undefined);
    setFormUrl(undefined);
    fetchAddedByName().then((name) => setAddedByName(name));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, user?.userId]);

  // serviceId, adminUserId and connectionId come from the decrypted token
  // (older tokens have no adminUserId, so the org's admin user fills in).
  // metadata says who added the rating: the token's user id and their name.
  const loadForm = async () => {
    if (!surveyId || !pageId || user?.userId === undefined) return;
    setLoadingForm(true);
    const name = await fetchAddedByName();
    const metadataValue = { addedBy: encrypted_token?.userId, name };
    const metadata = encodeURIComponent(JSON.stringify(metadataValue));
    const serviceId = encrypted_token?.cudbServiceId || encrypted_token?.serviceId;
    const adminUserId = encrypted_token?.adminUserId ?? projects?.adminUserId;
    const params = [
      ["serviceId", serviceId],
      ["adminUserId", adminUserId],
      ["connectionId", encrypted_token?.connectionId],
      ["pageId", pageId],
      ["surveyId", surveyId],
      // "<player>_<coach>": the form stores each response under this id, so every
      // coach keeps their own rating of the player instead of replacing another's.
      ["userId", encrypted_token?.userId !== undefined ? `${user.userId}_${encrypted_token.userId}` : user.userId],
    ]
      .map(([key, value]) => `${key}=${encodeURIComponent(`${value ?? ""}`)}`)
      .join("&");
    const url = `https://cpc.staging.beam.live/s/${surveyId}?${params}&metadata=${metadata}`;
    console.log("[Rating] metadata", metadataValue);
    console.log("[Rating] form url", url);
    setFormUrl(url);
    setLoadingForm(false);
  };

  const filterOption = (input: string, option: any) =>
    (option?.label ?? "").toString().toLowerCase().includes(input.toLowerCase());

  const formShown = formUrl !== undefined;

  return (
    <Modal
      title={user?.name ? `Rating - ${user.name}` : "Rating"}
      visible={open}
      onCancel={onClose}
      // Wide enough for the form, never wider than the screen; the form then gets
      // most of the height too (see the iframe).
      width={formShown ? "min(1200px, 96vw)" : "min(600px, 96vw)"}
      style={{ top: 20, maxWidth: "96vw" }}
      className="beam-modal"
      footer={[]}
      destroyOnClose
    >
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "4px 24px",
          marginBottom: 12,
          fontSize: 13,
          color: "#595959",
        }}
      >
        <span>
          Player: <strong>{user?.name || `#${user?.userId}`}</strong>
        </span>
        <span>
          Rated by:{" "}
          <strong>
            {addedByName === undefined
              ? "Loading..."
              : addedByName || `#${encrypted_token?.userId}`}
          </strong>
        </span>
      </div>

      <div
        style={{
          display: "grid",
          gap: 12,
          // Stacked before the form; one compact row once it is showing.
          gridTemplateColumns: formShown ? "1fr 1fr auto" : "1fr",
          alignItems: "center",
        }}
      >
        <Select
          showSearch
          allowClear
          placeholder="Select survey"
          loading={surveysLoading}
          options={surveys}
          value={surveyId}
          onChange={(value) => {
            setSurveyId(value);
            setFormUrl(undefined);
          }}
          filterOption={filterOption}
          style={{ width: "100%" }}
          notFoundContent={surveysLoading ? "Loading..." : "No surveys found"}
        />
        <Select
          showSearch
          allowClear
          placeholder="Select page"
          loading={pagesLoading}
          options={pages}
          value={pageId}
          onChange={(value) => {
            setPageId(value);
            setFormUrl(undefined);
          }}
          filterOption={filterOption}
          style={{ width: "100%" }}
          notFoundContent={pagesLoading ? "Loading..." : "No pages found"}
        />
        <Button
          className="beam-btn green-btn cover"
          disabled={!surveyId || !pageId}
          loading={loadingForm}
          onClick={loadForm}
        >
          Load form
        </Button>
      </div>

      {formUrl && (
        <iframe
          title="rating-form"
          src={formUrl}
          style={{
            width: "100%",
            // Fill the screen below the popup's header and controls.
            height: "calc(100vh - 260px)",
            minHeight: 420,
            border: "none",
            marginTop: 16,
          }}
        />
      )}
    </Modal>
  );
};

export default RatingModal;
