/**
 * Payment requests — topics and envelopes, in the shapes the live app
 * uses (mirrors `live-react/mobile`: a friend page is a `createPage`
 * with JSON-patch changes; a page message is the group/members
 * envelope). Pure functions; nothing here touches the socket.
 */
import { generateUUID } from "utils/appUtil";
import { getPageGroupMembersSubscriptionTopic } from "hooks/MQTTConstants";

const ecosystem = process.env.REACT_APP_ECO_SYSTEM || "";

export const createPageTopics = (connectionId: string) => ({
  publish: `${ecosystem}/connection/${connectionId}/service/live/createPage`,
  reply: `${ecosystem}/connection/${connectionId}/service/live/createPage/reply`,
});

/** Where a page message is published; the page's members receive it on `groupMembersSubscriptionTopic`. */
export const groupMembersPublishTopic = (connectionId: string, pageId: string): string =>
  `${ecosystem}/connection/${connectionId}/page/${pageId}/group/members`;

export const groupMembersSubscriptionTopic = (pageId: string): string => getPageGroupMembersSubscriptionTopic(pageId);

export interface PageChange {
  op: "add";
  path: string;
  value: unknown;
}

/** The changes the mobile app writes when it creates a friend page between two users. */
export const friendPageChanges = (input: {
  meId: string;
  meBeamId?: string | null;
  friendId: string;
  friendBeamId?: string | null;
  serviceId: string;
  now?: number;
}): PageChange[] => {
  const timestamp = input.now || Date.now();
  return [
    { op: "add", path: "/persistent/static/metadata/createdAt", value: timestamp },
    { op: "add", path: "/persistent/dynamic/metadata/updatedAt", value: timestamp },
    { op: "add", path: "/nonpersistent/dynamic/metadata/lastSent/members/updatedAt", value: timestamp },
    { op: "add", path: "/persistent/static/metadata/type", value: "friend" },
    {
      op: "add",
      path: `/persistent/static/metadata/members/users/${input.meId}`,
      value: { beamId: input.meBeamId || `User#${input.meId}`, role: "write" },
    },
    {
      op: "add",
      path: `/persistent/static/metadata/members/users/${input.friendId}`,
      value: { beamId: input.friendBeamId || `User#${input.friendId}`, role: "write" },
    },
    { op: "add", path: "/partitions", value: [`org:${input.serviceId}`] },
  ];
};

export interface PageMessage {
  type: string;
  attributes: Record<string, unknown> & { body: string };
}

/**
 * The message envelope (`getMessageRequestPayload` in
 * `helpers/request/RequestPayload.tsx`, plus the `notificationTypes` the
 * mobile app sends so the recipient is pushed).
 */
export const pageMessageEnvelope = (input: {
  connectionId: string;
  userId: string;
  pageId: string;
  message: PageMessage;
  connectionMessageId?: string;
  notificationTypes?: string[];
  now?: number;
}) => {
  const date = input.now || Date.now();
  return {
    header: { accessToken: "", connectionId: input.connectionId, userId: input.userId, udid: generateUUID() },
    messages: [
      {
        message: input.message,
        connectionInfo: {
          connectionMessageId: input.connectionMessageId || generateUUID(),
          connectionId: input.connectionId,
          pageId: input.pageId,
          userId: input.userId,
          createdAt: date,
          originalCreatedAt: date,
          refMessage: undefined,
          originalPageMessageId: undefined,
          notificationTypes: input.notificationTypes || ["push"],
        },
      },
    ],
    connectionId: input.connectionId,
    connectionPubTopic: "",
  };
};
