import { useCallback, useEffect, useState } from "react";

import { ProjectForm } from "./beamTypes";
import { getProgramsConfig, ProgramsConfig, resolveProgramsConfig } from "./config";
import { buildFilterDefs, buildSections, FilterDef, liveUserName, toProgramEvents } from "./mapEvents";
import {
  fetchLiveUsers,
  fetchProjectForms,
  fetchProjects,
  fetchProjectTypes,
  fetchProjectTypesForId,
  fetchQueryObject,
  fetchRoles,
} from "./queries";
import { resolveSignups, SignupTarget } from "./signup";
import { ProgramEvent, SectionDef } from "../data";

export interface ProgramsData {
  loading: boolean;
  error?: string;
  /** Sidebar sections, built from the event form's event-type widget. */
  sections: SectionDef[];
  /** Sign-up form per form-section slug, resolved from the org's roles. */
  signups: Record<string, SignupTarget>;
  events: ProgramEvent[];
  /** Filter controls built from the event forms' widgets. */
  filterDefs: FilterDef[];
  forms: ProjectForm[];
  config: ProgramsConfig;
  reload: () => void;
}

/**
 * Loads everything the Programs page shows, in one pass:
 *
 *   1. the organization's `project:extendedBio` forms (BDS)  — what an event is
 *   2. the organization's projects (CUDB)                     — the events
 *   3. the organization's roles (CUDB)                        — the sign-up forms
 *   4. the organization's live users (BDS)                    — manager names
 *
 * Projects already carry their answers, so there is no per-event call, and the
 * filters are read off the forms from step 1. Steps 3 and 4 are not fatal: a
 * failure there costs the sign-up form or the coach line, not the page.
 */
/**
 * Find the id of the project type whose name matches `name`, wherever it sits in
 * the project.types value (an array, or a map keyed by id). Reads the id from
 * whichever key the entry uses.
 */
const findTypeByName = (types: unknown, name: string): any => {
  const target = name.trim().toLowerCase();
  let result: any;
  const walk = (node: any) => {
    if (result !== undefined || node === null || typeof node !== "object") return;
    if (Array.isArray(node)) {
      node.forEach(walk);
      return;
    }
    // Shape A: an object that is itself a type - { _id, name, extendedBioId }.
    if (
      typeof node.name === "string" &&
      node.name.trim().toLowerCase() === target
    ) {
      result = node;
      return;
    }
    // Shape B: a map keyed by type name - { "beamvite": { _id, ... } }.
    for (const [key, val] of Object.entries(node)) {
      if (result !== undefined) break;
      if (
        key.trim().toLowerCase() === target &&
        val &&
        typeof val === "object"
      ) {
        result = { _id: key, ...(val as object) };
        return;
      }
    }
    Object.values(node).forEach(walk);
  };
  walk(types);
  return result;
};

const typeIdOf = (type: any): any =>
  type?._id ?? type?.id ?? type?.objectId ?? type?.typeId;

export const useProgramsData = (): ProgramsData => {
  // The base config (query/env/defaults) renders immediately; the token-derived
  // org, if any, replaces it once the token is decrypted inside the effect.
  const [config, setConfig] = useState<ProgramsConfig>(getProgramsConfig);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>();
  const [sections, setSections] = useState<SectionDef[]>(() => buildSections([]));
  const [events, setEvents] = useState<ProgramEvent[]>([]);
  const [filterDefs, setFilterDefs] = useState<FilterDef[]>([]);
  const [forms, setForms] = useState<ProjectForm[]>([]);
  const [signups, setSignups] = useState<Record<string, SignupTarget>>({});
  const [nonce, setNonce] = useState(0);

  const reload = useCallback(() => setNonce((n) => n + 1), []);

  useEffect(() => {
    const controller = new AbortController();
    let active = true;

    const run = async () => {
      setLoading(true);
      setError(undefined);
      try {
        // Decrypt the `?token=` first (if any) so every fetch below uses the
        // organization it names; a missing or bad token keeps the base config.
        const cfg = await resolveProgramsConfig();
        if (!active) return;
        setConfig(cfg);

        const [loadedForms, projects, roles, projectTypes] = await Promise.all([
          fetchProjectForms(cfg, controller.signal),
          fetchProjects(cfg, controller.signal),
          // Only the sign-up sections need these; a failure costs the form, not the page.
          fetchRoles(cfg, controller.signal).catch(() => []),
          // Project types drive the event-page filter; a failure just skips it.
          fetchProjectTypes(cfg, controller.signal).catch(() => null),
        ]);

        // The event pages (clinics, special events, camps) show only projects of
        // the "beamvite" type. Find its id in project.types (any shape), then
        // keep only those projects; if the type isn't found, keep all.
        const beamviteType = findTypeByName(projectTypes, "beamvite");
        const beamviteTypeId = typeIdOf(beamviteType);
        const beamviteExtendedBioId = beamviteType?.extendedBioId;
        console.log(
          "[Programs] beamvite type",
          beamviteType,
          "id",
          beamviteTypeId,
          "extendedBioId",
          beamviteExtendedBioId
        );
        // Take each project:extendedBio objectId from the aggregateBds response
        // (loadedForms) and pass it to both services (logged for inspection).
        loadedForms.forEach((form) => {
          if (!form?.id) return;
          fetchQueryObject(cfg, form.id, controller.signal).catch(
            () => undefined
          );
          fetchProjectTypesForId(cfg, form.id, controller.signal).catch(
            () => undefined
          );
        });
        // Keep only events whose project extendedBioId matches the beamvite
        // type's extendedBioId; if it isn't found, keep all.
        const eventProjects =
          beamviteExtendedBioId !== undefined && beamviteExtendedBioId !== null
            ? projects.filter(
                (p) => `${p.extendedBioId}` === `${beamviteExtendedBioId}`
              )
            : projects;
        console.log(
          "[Programs] event projects (beamvite extendedBioId)",
          beamviteExtendedBioId,
          eventProjects.length,
          "of",
          projects.length
        );

        // Only needed when a project actually names managers.
        const needsUsers = eventProjects.some((p) => (p.managerLiveUserIds ?? []).length > 0);
        const users = needsUsers
          ? await fetchLiveUsers(cfg, controller.signal).catch(() => [])
          : [];
        const userNames: Record<string, string> = {};
        users.forEach((row) => {
          if (row.objectId !== undefined) userNames[`${row.objectId}`] = liveUserName(row);
        });

        if (!active) return;

        const mapped = toProgramEvents(eventProjects, loadedForms, {
          config: cfg,
          userNames,
          sectionElementId: cfg.sectionElementId,
        });

        // Filters come from the "beamvite" type's extendedBio form (its
        // data.blocks[].elements[] marked isFilter), same as /sports builds
        // them from the "org" type's form. If the beamvite form isn't found,
        // fall back to every event form so the controls are never empty.
        const beamviteForm = beamviteExtendedBioId
          ? loadedForms.find((f) => `${f.id}` === `${beamviteExtendedBioId}`)
          : undefined;
        const defs = beamviteForm
          ? buildFilterDefs(beamviteForm)
          : loadedForms.flatMap((form) => buildFilterDefs(form));
        console.log(
          "[Programs] filter defs (beamvite form)",
          beamviteExtendedBioId,
          defs
        );

        const loadedSections = buildSections(loadedForms, cfg.sectionElementId);

        setForms(loadedForms);
        setSections(loadedSections);
        setSignups(
          resolveSignups(
            loadedSections.filter((s) => s.kind === "form").map((s) => s.id),
            roles,
            cfg
          )
        );
        setEvents(mapped);
        setFilterDefs(defs);
      } catch (err) {
        if (!active || controller.signal.aborted) return;
        setError(err instanceof Error ? err.message : "Could not load programs");
        setSections(buildSections([]));
        setSignups({});
        setEvents([]);
        setFilterDefs([]);
      } finally {
        if (active) setLoading(false);
      }
    };

    run();
    return () => {
      active = false;
      controller.abort();
    };
    // Config is resolved inside the effect, so it must not be a dependency.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nonce]);

  return { loading, error, sections, signups, events, filterDefs, forms, config, reload };
};
