import { useLocation } from "react-router-dom";
import { useDirectory } from "../directory/useDirectory";
import { useStripeIdentity } from "../stripe/useStripeIdentity";

/**
 * Where the dashboard is with the link's identity:
 * - `no-token`: the URL carries no `?token=`, so nothing can load.
 * - `pending`: a token is on the URL but has not been decrypted yet
 *   (`CFODashboardWrapper` does that over the socket).
 * - `ready`: the user and the organisation are known; the screens load.
 *
 * Screens show their sign-in state only for `no-token`; during `pending`
 * they render empty, with a loading indicator, never sample data.
 */
export type CfoSession = "no-token" | "pending" | "ready";

export const useCfoSession = (): CfoSession => {
  const { search } = useLocation();
  const identity = useStripeIdentity();
  const { context } = useDirectory();
  if (identity && context) return "ready";
  return new URLSearchParams(search).get("token") ? "pending" : "no-token";
};
