/**
 * Stripe payments tab — view model.
 *
 * Stripe reports amounts in minor units and statuses as three words; the
 * table wants decimals in the dashboard's currency formatting and a
 * status that also says whether money went back out.
 */
import { StripeCharge } from "./stripeTypes";

/** Currencies Stripe quotes without a fractional unit. */
const ZERO_DECIMAL = new Set([
  "bif", "clp", "djf", "gnf", "jpy", "kmf", "krw", "mga", "pyg", "rwf", "ugx", "vnd", "vuv", "xaf", "xof", "xpf",
]);

export const fromMinor = (minor: number, currency: string): number =>
  ZERO_DECIMAL.has((currency || "").toLowerCase()) ? minor : minor / 100;

export const toMinor = (major: number, currency: string): number =>
  Math.round(ZERO_DECIMAL.has((currency || "").toLowerCase()) ? major : major * 100);

export type StripePaymentStatus =
  | "succeeded"
  | "uncaptured"
  | "partially_refunded"
  | "refunded"
  | "failed"
  | "pending"
  | "disputed";

export const STRIPE_STATUS_META: Record<StripePaymentStatus, { label: string; color: string; bg: string }> = {
  succeeded: { label: "Succeeded", color: "#1F9D55", bg: "#E4F6EC" },
  uncaptured: { label: "Uncaptured", color: "#508AFA", bg: "#E6F0FF" },
  partially_refunded: { label: "Partially refunded", color: "#FBAE16", bg: "#FEF5E1" },
  refunded: { label: "Refunded", color: "#FF5F25", bg: "#FFEDE6" },
  failed: { label: "Failed", color: "#E5484D", bg: "#FDECEC" },
  pending: { label: "Pending", color: "#5a6478", bg: "#EFF2F7" },
  disputed: { label: "Disputed", color: "#E5484D", bg: "#FDECEC" },
};

/** One charge, as the table and drawer read it. */
export interface StripePaymentRow {
  key: string;
  id: string;
  /** Epoch ms. */
  createdAt: number;
  /** Major units. */
  amount: number;
  amountCaptured: number;
  amountRefunded: number;
  /** captured − refunded. */
  net: number;
  /** Uppercase ISO code for the formatters. */
  currency: string;
  status: StripePaymentStatus;
  rawStatus: StripeCharge["status"];
  livemode: boolean;
  description: string;
  customerId: string | null;
  customerName: string;
  customerEmail: string;
  paymentMethodType: string;
  card: { brand: string; last4: string; exp: string } | null;
  paymentIntent: string | null;
  invoice: string | null;
  failure: { code: string; message: string } | null;
  outcome: StripeCharge["outcome"];
  metadata: Record<string, string>;
  /** Minor units still available to refund. */
  refundableMinor: number;
  canRefund: boolean;
  /** The raw object, for the drawer. */
  charge: StripeCharge;
}

export const deriveStatus = (charge: StripeCharge): StripePaymentStatus => {
  if (charge.disputed) return "disputed";
  if (charge.status === "failed") return "failed";
  if (charge.status === "pending") return "pending";
  if (charge.amount_refunded > 0 && (charge.refunded || charge.amount_refunded >= charge.amount_captured)) {
    return "refunded";
  }
  if (charge.amount_refunded > 0) return "partially_refunded";
  if (!charge.captured) return "uncaptured";
  return "succeeded";
};

const pad2 = (value: number) => String(value).padStart(2, "0");

export const mapCharge = (charge: StripeCharge): StripePaymentRow => {
  const currency = (charge.currency || "usd").toUpperCase();
  const card = charge.payment_method_details?.card;
  const status = deriveStatus(charge);
  const refundableMinor = Math.max(0, (charge.amount_captured || 0) - (charge.amount_refunded || 0));
  return {
    key: charge.id,
    id: charge.id,
    createdAt: (charge.created || 0) * 1000,
    amount: fromMinor(charge.amount || 0, currency),
    amountCaptured: fromMinor(charge.amount_captured || 0, currency),
    amountRefunded: fromMinor(charge.amount_refunded || 0, currency),
    net: fromMinor((charge.amount_captured || 0) - (charge.amount_refunded || 0), currency),
    currency,
    status,
    rawStatus: charge.status,
    livemode: !!charge.livemode,
    description: charge.description || "",
    customerId: charge.customer || null,
    customerName: charge.billing_details?.name || "",
    customerEmail: charge.billing_details?.email || "",
    paymentMethodType: charge.payment_method_details?.type || "",
    card: card
      ? { brand: card.brand, last4: card.last4, exp: `${pad2(card.exp_month)}/${card.exp_year}` }
      : null,
    paymentIntent: charge.payment_intent || null,
    invoice: charge.invoice || null,
    failure:
      charge.failure_code || charge.failure_message
        ? { code: charge.failure_code || "", message: charge.failure_message || "" }
        : null,
    outcome: charge.outcome || null,
    metadata: charge.metadata || {},
    refundableMinor,
    canRefund: charge.status === "succeeded" && !!charge.captured && !charge.disputed && refundableMinor > 0,
    charge,
  };
};

/** Totals over the loaded page, in its dominant currency. */
export interface StripeSummary {
  currency: string;
  captured: number;
  refunded: number;
  net: number;
  failedCount: number;
  failedAmount: number;
  /** Rows left out because they are in another currency. */
  otherCurrencyCount: number;
  rows: number;
}

const round2 = (value: number) => Number(value.toFixed(2));

/** The most frequent currency among the rows; USD when there are none. */
export const dominantCurrency = (rows: StripePaymentRow[]): string => {
  const counts = new Map<string, number>();
  rows.forEach((row) => counts.set(row.currency, (counts.get(row.currency) || 0) + 1));
  let currency = "USD";
  let best = -1;
  counts.forEach((count, code) => {
    if (count > best) {
      best = count;
      currency = code;
    }
  });
  return currency;
};

export const summariseCharges = (rows: StripePaymentRow[]): StripeSummary => {
  const currency = dominantCurrency(rows);

  const mine = rows.filter((row) => row.currency === currency);
  const captured = mine.reduce((acc, row) => acc + row.amountCaptured, 0);
  const refunded = mine.reduce((acc, row) => acc + row.amountRefunded, 0);
  const failed = mine.filter((row) => row.status === "failed");

  return {
    currency,
    captured: round2(captured),
    refunded: round2(refunded),
    net: round2(captured - refunded),
    failedCount: failed.length,
    failedAmount: round2(failed.reduce((acc, row) => acc + row.amount, 0)),
    otherCurrencyCount: rows.length - mine.length,
    rows: rows.length,
  };
};
