import React, { FC, createContext, useCallback, useContext, useEffect, useRef, useState } from "react";

import { useDirectory } from "../directory/useDirectory";
import { StoredPaymentRequest, fetchPaymentRequests } from "./paymentRequestRecord";

export interface PaymentRequestsState {
  /** Every record of the organisation, newest first. */
  records: StoredPaymentRequest[];
  loading: boolean;
  error: string | null;
  loadedAt: number | null;
  /** Reloads the list; resolves when it has landed. */
  refresh: () => Promise<void>;
}

const PaymentRequestsContext = createContext<PaymentRequestsState | null>(null);

/**
 * The organisation's payment request records (`paymentRequestRecord.ts`),
 * loaded once per organisation and shared: the Transactions screen
 * lists them and the send wizard refreshes them after a run, so the
 * screen is current when the CFO switches to it.
 *
 * Keys off the Directory's organisation context, so it must sit inside
 * `DirectoryProvider`.
 */
export const PaymentRequestsProvider: FC = ({ children }) => {
  const { context } = useDirectory();
  const [records, setRecords] = useState<StoredPaymentRequest[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loadedAt, setLoadedAt] = useState<number | null>(null);
  const loadedFor = useRef<string | null>(null);
  const seq = useRef(0);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const load = useCallback(async () => {
    if (!context) return;
    const mine = ++seq.current;
    setLoading(true);
    try {
      const list = await fetchPaymentRequests(context);
      if (!mounted.current || mine !== seq.current) return;
      setRecords(list);
      setError(null);
      setLoadedAt(Date.now());
    } catch (e: any) {
      if (!mounted.current || mine !== seq.current) return;
      setError(e?.message || "The payment request list failed");
    }
    if (mounted.current && mine === seq.current) setLoading(false);
  }, [context]);

  /* One load per organisation. */
  useEffect(() => {
    if (!context) return;
    if (loadedFor.current === context.serviceId) return;
    loadedFor.current = context.serviceId;
    load();
  }, [context, load]);

  const refresh = useCallback(() => load(), [load]);

  const value: PaymentRequestsState = { records, loading, error, loadedAt, refresh };
  return <PaymentRequestsContext.Provider value={value}>{children}</PaymentRequestsContext.Provider>;
};

export const usePaymentRequests = (): PaymentRequestsState => {
  const state = useContext(PaymentRequestsContext);
  if (!state) throw new Error("usePaymentRequests must be used inside a PaymentRequestsProvider");
  return state;
};
