/**
 * Payment requests — the `pay` message one recipient receives.
 *
 * The mobile app renders `body`, `amount`, `currency` and `status`
 * (`succeeded` shows Paid, anything else Unpaid). Everything else is
 * the request itself: the configuration snapshot the CFO sent, the
 * adjustments applied, the amount breakdown, the payment schedule and
 * the reminder settings, so a scheduler can be built from the message
 * later without another source. `paymentRequestId` names the BDS record
 * of the request (`paymentRequestRecord.ts`), which is where payment
 * state is written back.
 *
 * `computePayRequest` is the one place the recipient's amounts are
 * worked out; the message and the record are both built from its result
 * so they can never disagree.
 */
import { AmountLine, AppliedAdjustments, PaymentConfig, PaymentRequestDraft, Reminders, ScheduleLine } from "../types";
import { buildPaymentPlan, computeAmountDue, money } from "../paymentConfig";
import { effectiveRequest } from "../SendPaymentRequest/draft";
import { PageMessage } from "./pageMessages";
import { ComputedRequest } from "./paymentRequestRecord";

export const PAY_MESSAGE_TYPE = "pay";
export const PAYMENT_REQUEST_KIND = "cfo-payment-request";
export const PAYMENT_REQUEST_VERSION = 2;

/** Initial status of a request; the payment flow moves it to `succeeded`. */
export const PAYMENT_REQUEST_STATUS = "requested";

export interface PaymentRequestAttributes {
  body: string;
  amount: number;
  currency: string;
  status: string;
  requestId: string;
  /** The BDS `payment:request` object behind this message. */
  paymentRequestId: string;
  kind: typeof PAYMENT_REQUEST_KIND;
  version: typeof PAYMENT_REQUEST_VERSION;
  sentAt: number;
  subject: string;
  recipient: { userId: string; name: string };
  sender: { userId: string };
  config: PaymentConfig;
  applied: AppliedAdjustments;
  note: string;
  amountDue: { total: number; lines: AmountLine[] };
  schedule: ScheduleLine[];
  reminders: Reminders;
}

/** The recipient's effective request with its amounts and schedule worked out at `now`. */
export const computePayRequest = (draft: PaymentRequestDraft, memberId: string, now: number): ComputedRequest => {
  const request = effectiveRequest(draft, memberId);
  const due = computeAmountDue(request.config, request.applied, now);
  const schedule = buildPaymentPlan(request.config, due.total, now);
  return { config: request.config, applied: request.applied, note: request.note, due, schedule };
};

export const buildPayMessage = (input: {
  request: ComputedRequest;
  requestId: string;
  paymentRequestId: string;
  recipient: { id: string; name: string };
  sender: { id: string };
  subject: string;
  now: number;
}): PageMessage & { attributes: PaymentRequestAttributes } => {
  const { request } = input;
  const currency = request.config.currency;
  return {
    type: PAY_MESSAGE_TYPE,
    attributes: {
      body: `${input.subject}: payment request for ${money(request.due.total, currency)}`,
      amount: request.due.total,
      currency,
      status: PAYMENT_REQUEST_STATUS,
      requestId: input.requestId,
      paymentRequestId: input.paymentRequestId,
      kind: PAYMENT_REQUEST_KIND,
      version: PAYMENT_REQUEST_VERSION,
      sentAt: input.now,
      subject: input.subject,
      recipient: { userId: input.recipient.id, name: input.recipient.name },
      sender: { userId: input.sender.id },
      config: request.config,
      applied: request.applied,
      note: request.note,
      amountDue: request.due,
      schedule: request.schedule,
      reminders: request.config.reminders,
    },
  };
};
