/**
 * Payment requests — the Directory's live rows in the shapes the wizard
 * reads: a `PaymentRequestTarget`, its roster of `ProjectMember`s, and
 * the configuration the draft starts from.
 */
import { BillableEntity, Domain, PaymentConfig, ProjectMember, ProjectRollup, ProjectSummary } from "../types";
import { cloneConfig, makeConfig } from "../paymentConfig";
import { DirectoryState } from "../directory/useDirectory";
import { DirectoryUser } from "../directory/directoryModel";

/** The wizard's inputs for a live target. */
export interface LiveWizardData {
  members: ProjectMember[];
  config: PaymentConfig;
  subject: string;
}

const memberOf = (id: string, usersById: Map<string, DirectoryUser>): ProjectMember => {
  const user = usersById.get(id);
  return user
    ? {
        id: user.id,
        name: user.name,
        role: user.roleName || "Member",
        household: user.email || "",
        beamId: user.beamId,
        email: user.email || null,
        phone: user.phone || null,
        stripeCustomerId: user.stripeCustomerId,
      }
    : { id, name: `User #${id}`, role: "Member", household: "", beamId: null };
};

/** Member ids of a live group or project, or null when the id is neither. */
const memberIdsOf = (projectId: string, directory: DirectoryState): string[] | null => {
  const group = directory.groups.find((g) => g._id === projectId);
  if (group) return (group.members || []).map((m) => String(m._id));
  const project = directory.projects.find((p) => p._id === projectId);
  /* Members only: managers are the coaches, not the people being billed. */
  if (project) return Array.from(new Set((project.liveUserIds || []).map((id) => String(id))));
  return null;
};

/** A live group or project as the wizard's project summary. */
export const liveProjectSummary = (row: ProjectRollup): ProjectSummary => ({
  id: row.id,
  name: row.name,
  kind: row.kind,
  domain: row.domain,
  paymentConfigId: row.paymentConfigId,
  paymentConfigName: row.paymentConfigName,
  currency: row.currency,
  totalAmount: row.totalAmount,
  memberCount: row.memberCount,
  startsAt: row.startsAt,
  endsAt: row.endsAt,
});

/** The team a player is billed through: their first group or project membership, or a direct request. */
export const projectForPlayer = (entity: BillableEntity, teams: ProjectRollup[], domain: Domain): ProjectSummary => {
  const first = entity.projectIds.map((id) => teams.find((t) => t.id === id)).find((t) => !!t);
  if (first) return liveProjectSummary(first);
  return {
    id: `user:${entity.id}`,
    name: entity.name,
    kind: "Direct request",
    domain,
    paymentConfigId: null,
    paymentConfigName: "",
    currency: entity.billing.currency,
    totalAmount: 0,
    memberCount: 1,
  };
};

/** The roster for a live target. */
export const liveMembers = (
  target: { project: ProjectSummary | null; focusMemberIds?: string[]; payee?: BillableEntity | null },
  directory: DirectoryState,
  people: BillableEntity[]
): ProjectMember[] => {
  if (target.payee) {
    const p = target.payee;
    const user = directory.users.find((u) => u.id === p.id);
    /* A kid's parent is not in the Directory's user list; their beamId comes from the family. */
    const payerBeamId = directory.families.find((f) => f.parent.id === p.id)?.parent.beamId;
    return [
      {
        id: p.id,
        name: p.name,
        role: p.role,
        household: p.email || p.category || p.department || "",
        beamId: user ? user.beamId : (payerBeamId ?? null),
        email: p.email || (user ? user.email : null) || null,
        phone: p.phone || (user ? user.phone : null) || null,
        stripeCustomerId: p.stripeCustomerId || (user ? user.stripeCustomerId : null) || null,
      },
    ];
  }
  if (!target.project) return [];
  const usersById = new Map(directory.users.map((u) => [u.id, u] as [string, DirectoryUser]));
  const focus = target.focusMemberIds || [];
  let ids = memberIdsOf(target.project.id, directory);
  if (ids === null) ids = focus.slice();
  /* The member the CFO clicked on is listed even when the team's member list does not carry them. */
  focus.forEach((id) => {
    if (ids!.indexOf(id) === -1) ids!.push(id);
  });
  const roster = ids.map((id) => {
    const person = people.find((e) => e.id === id);
    return person
      ? {
          id: person.id,
          name: person.name,
          role: person.role,
          household: person.email || "",
          beamId: usersById.get(id)?.beamId || null,
          email: person.email || usersById.get(id)?.email || null,
          phone: person.phone || usersById.get(id)?.phone || null,
          stripeCustomerId: person.stripeCustomerId || usersById.get(id)?.stripeCustomerId || null,
        }
      : memberOf(id, usersById);
  });
  roster.sort((a, b) => {
    const af = focus.indexOf(a.id) !== -1 ? 0 : 1;
    const bf = focus.indexOf(b.id) !== -1 ? 0 : 1;
    return af - bf || a.name.localeCompare(b.name);
  });
  return roster;
};

/** The configuration a live draft starts from: the stored one when attached, otherwise a blank one to fill in. */
export const seedConfig = (
  subject: string,
  paymentConfigId: string | null | undefined,
  byId: (id: string | null | undefined) => PaymentConfig | null,
  currency = "USD"
): PaymentConfig => {
  const stored = byId(paymentConfigId);
  if (stored) return cloneConfig(stored);
  return makeConfig({
    _id: `draft-${Date.now()}`,
    name: `${subject} payment request`,
    description: "",
    currency: currency as PaymentConfig["currency"],
    totalAmount: 0,
  });
};
