/**
 * Stripe payments — which Stripe customers belong to this organisation.
 *
 * The platform has one Stripe account and charges carry no organisation
 * id; the only link is `charge.customer`, the Stripe customer id a user
 * carries on their record. Two paths hold it: the app's saga writes
 * `persistent.static.live.alternativeIds.stripeCustomerId`, the payment
 * workflow writes `persistent.static.stripe.customerId`. One aggregate
 * over the cudb's users collects both.
 */
import { formatForRedis } from "utils/appUtil";

import { ECOSYSTEM, aggregateRows, bdsPost } from "../directory/bds";

export interface OrgCustomers {
  customerIds: string[];
  /** The platform user behind each Stripe customer id. */
  userIdByCustomer: Map<string, string>;
}

export const fetchOrgCustomers = async (context: { serviceId: string; connectionId: string }): Promise<OrgCustomers> => {
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:userNameIndex`,
        searchQuery: `@serviceId:{'${formatForRedis(context.serviceId)}'}`,
        searchOptions: "TIMEOUT 5000",
      },
      load: {
        id: "$.objectId",
        alt: "$.persistent.static.live.alternativeIds.stripeCustomerId",
        wf: "$.persistent.static.stripe.customerId",
      },
    },
    apply: { expression: "", name: "" },
    result: {},
    filter: { expression: "" },
    anyStatus: true,
  };
  const reply = await bdsPost("aggregateBds", request, context.connectionId);
  const rows = aggregateRows(reply);
  if (!rows) throw new Error(reply?.message || "The organisation's user list returned no list");
  const userIdByCustomer = new Map<string, string>();
  rows.forEach((row: any) => {
    [row?.alt, row?.wf].forEach((value) => {
      if (typeof value === "string" && value.trim() && !userIdByCustomer.has(value.trim())) {
        userIdByCustomer.set(value.trim(), String(row.id));
      }
    });
  });
  return { customerIds: Array.from(userIdByCustomer.keys()), userIdByCustomer };
};
