import React, { FC, createContext, useContext } from "react";

const CfoSocketContext = createContext<ISocket | null>(null);

/** Hands the dashboard's socket to the screens that send over it, without threading it through every prop. */
export const CfoSocketProvider: FC<{ socket?: ISocket }> = ({ socket, children }) => (
  <CfoSocketContext.Provider value={socket || null}>{children}</CfoSocketContext.Provider>
);

export const useCfoSocket = (): ISocket | null => useContext(CfoSocketContext);
