/**
 * Stripe payments tab — the filter, applied client-side over the
 * organisation's swept charges, and the request shape of the sweep.
 *
 * Stripe search cannot combine the organisation scope (an OR list of
 * customers) with further AND clauses, so the tab filters the shared
 * window in the browser instead of searching Stripe itself.
 */
import { DAY } from "../mockData";
import { StripePaymentRow, StripePaymentStatus } from "./chargeModel";

/** Stripe search allows at most ten filters per query. */
export const CUSTOMERS_PER_QUERY = 10;

export type StripeChargeStatus = "succeeded" | "pending" | "failed";
export type TriState = "any" | "yes" | "no";

export interface StripeChargeFilter {
  /** Epoch ms, inclusive. Never null. */
  range: { from: number; to: number };
  statuses: StripeChargeStatus[];
  refunded: TriState;
  disputed: TriState;
  /** Major units, like the rest of the dashboard. */
  amountMin: number | null;
  amountMax: number | null;
  /** Lowercase ISO code. */
  currency: string | null;
  cardBrand: string | null;
  last4: string;
  customerId: string;
  /** `metadata.type` of the charge, e.g. `smsPayment`. */
  metadataType: string | null;
}

export const defaultRange = (now = Date.now()) => ({ from: now - 30 * DAY, to: now });

export const DEFAULT_STRIPE_FILTER: StripeChargeFilter = {
  range: defaultRange(),
  statuses: [],
  refunded: "any",
  disputed: "any",
  amountMin: null,
  amountMax: null,
  currency: null,
  cardBrand: null,
  last4: "",
  customerId: "",
  metadataType: null,
};

export const STATUS_OPTIONS: { value: StripeChargeStatus; label: string }[] = [
  { value: "succeeded", label: "Succeeded" },
  { value: "pending", label: "Pending" },
  { value: "failed", label: "Failed" },
];

export const CURRENCY_OPTIONS = ["usd", "eur", "gbp", "cad", "aud", "inr", "pkr", "aed", "sar", "zar"].map(
  (code) => ({ value: code, label: code.toUpperCase() })
);

export const CARD_BRAND_OPTIONS = [
  "visa",
  "mastercard",
  "amex",
  "discover",
  "diners",
  "jcb",
  "unionpay",
].map((brand) => ({ value: brand, label: brand === "amex" ? "American Express" : brand[0].toUpperCase() + brand.slice(1) }));

/** How many panel filters are set, for the badge; the range is always visible on its own. */
export const countActiveStripeFilters = (filter: StripeChargeFilter): number =>
  [
    filter.statuses.length > 0,
    filter.refunded !== "any",
    filter.disputed !== "any",
    filter.amountMin !== null || filter.amountMax !== null,
    filter.currency !== null,
    filter.cardBrand !== null,
    filter.last4.trim() !== "",
    filter.customerId.trim() !== "",
    filter.metadataType !== null,
  ].filter(Boolean).length;

const REFUNDED_STATUSES: StripePaymentStatus[] = ["refunded", "partially_refunded"];

/** The rows of the window that pass every set filter. */
export const filterRows = (rows: StripePaymentRow[], filter: StripeChargeFilter): StripePaymentRow[] => {
  const last4 = filter.last4.trim();
  const customerId = filter.customerId.trim();
  return rows.filter((row) => {
    if (row.createdAt < filter.range.from || row.createdAt > filter.range.to) return false;
    if (filter.statuses.length > 0 && filter.statuses.indexOf(row.rawStatus) === -1) return false;
    if (filter.refunded !== "any" && (row.amountRefunded > 0) !== (filter.refunded === "yes")) return false;
    if (filter.disputed !== "any" && (row.status === "disputed") !== (filter.disputed === "yes")) return false;
    if (filter.amountMin !== null && row.amount < filter.amountMin) return false;
    if (filter.amountMax !== null && row.amount > filter.amountMax) return false;
    if (filter.currency && row.currency.toLowerCase() !== filter.currency.toLowerCase()) return false;
    if (filter.cardBrand && (!row.card || row.card.brand !== filter.cardBrand)) return false;
    if (last4 && (!row.card || row.card.last4 !== last4)) return false;
    if (customerId && row.customerId !== customerId) return false;
    if (filter.metadataType && row.metadata.type !== filter.metadataType) return false;
    return true;
  });
};

/** What the `searchCharges` op accepts for one customer chunk; no dates, so the workflow appends none. */
export interface ChargeSearchRequest {
  query?: string;
  startDate?: string;
  endDate?: string;
  limit: number;
  page?: string;
}

/** `customer:'a' OR customer:'b' …` for up to ten customers, as Stripe search accepts it. */
export const buildCustomerSearchRequest = (customerIds: string[], limit: number, page?: string): ChargeSearchRequest => ({
  query: customerIds.map((id) => `customer:'${id.replace(/'/g, "\\'")}'`).join(" OR "),
  limit,
  ...(page ? { page } : {}),
});

export { REFUNDED_STATUSES };
