import React, { FC } from "react";
import { Alert, Progress, Tag, Tooltip } from "antd";

import { ProjectMember } from "../types";
import { money } from "../paymentConfig";
import { SendOutcome, SendStatus } from "../payments/sendPaymentRequest";

const STATUS_META: Record<SendStatus, { label: string; color: string }> = {
  pending: { label: "Pending", color: "default" },
  "page-found": { label: "Page found", color: "blue" },
  "page-created": { label: "Page created", color: "geekblue" },
  recorded: { label: "Recorded", color: "purple" },
  sent: { label: "Sent", color: "green" },
  unconfirmed: { label: "Not confirmed", color: "orange" },
  failed: { label: "Failed", color: "red" },
};

/** Outcomes the run is finished with. */
const isSettled = (status: SendStatus) => status === "sent" || status === "failed" || status === "unconfirmed";

interface Props {
  outcomes: SendOutcome[];
  members: ProjectMember[];
  amountFor: (memberId: string) => number;
  currency: string;
  running: boolean;
}

/**
 * The fourth step: one row per recipient moving from pending through
 * the friend page and the request record to sent, or failed with the
 * reason, or not confirmed when the broker never answered (the message
 * may still have arrived; a retry resends it against the same record).
 * Sent means the broker acknowledged the message; the recipient sees it
 * on their page.
 */
const StepSending: FC<Props> = ({ outcomes, members, amountFor, currency, running }) => {
  const settled = outcomes.filter((o) => isSettled(o.status)).length;
  const sent = outcomes.filter((o) => o.status === "sent").length;
  const failed = outcomes.filter((o) => o.status === "failed" || o.status === "unconfirmed").length;
  const percent = outcomes.length > 0 ? Math.round((settled / outcomes.length) * 100) : 0;

  return (
    <div className="cfo-send">
      <Progress
        percent={percent}
        status={running ? "active" : failed > 0 ? "exception" : "success"}
        strokeColor={failed > 0 && !running ? "#E5484D" : "#1F9D55"}
      />
      <p className="cfo-send__counts">
        {sent} sent · {failed} failed · {outcomes.length - settled} pending
      </p>

      {!running && failed > 0 && (
        <Alert
          type="warning"
          showIcon
          className="cfo-stripe__notice"
          message={`${failed} ${failed === 1 ? "request was" : "requests were"} not confirmed as sent.`}
          description="Retry resends only those, against the same request records; recipients already sent are not messaged again."
        />
      )}

      <ul className="cfo-send__list">
        {outcomes.map((outcome) => {
          const meta = STATUS_META[outcome.status];
          const member = members.find((m) => m.id === outcome.memberId);
          return (
            <li key={outcome.memberId} className="cfo-send__row">
              <div className="cfo-cell">
                <div className="cfo-cell__main">{outcome.name}</div>
                <div className="cfo-cell__sub">
                  {member ? member.role : ""}
                  {outcome.pageId ? ` · page ${outcome.pageId}` : ""}
                  {outcome.paymentRequestId ? ` · record ${outcome.paymentRequestId}` : ""}
                  {outcome.attempts && outcome.attempts > 1 ? ` · attempt ${outcome.attempts}` : ""}
                </div>
              </div>
              <span className="cfo-send__amount">{money(amountFor(outcome.memberId), currency)}</span>
              <Tooltip title={outcome.error || undefined}>
                <Tag color={meta.color} className="cfo-send__status">
                  {meta.label}
                  {outcome.error ? `: ${outcome.error}` : ""}
                </Tag>
              </Tooltip>
            </li>
          );
        })}
      </ul>
    </div>
  );
};

export default StepSending;
