import React, { FC, createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";

import {
  OrgContext,
  RawEventPage,
  RawGroup,
  RawProject,
  fetchEventPages,
  fetchFamilies,
  fetchGroups,
  fetchOrgAdmin,
  fetchUsersByRoleIds,
} from "./directoryApi";
import { DirectoryUser, OrgRole, directoryRoleIds, toDirectoryUser } from "./directoryModel";
import { FamilyRow } from "../../../School3/Dashboard/Student/familyRows";

export interface DirectoryState {
  /** The organisation is known (the token has been read), so the lists can load. */
  ready: boolean;
  context: OrgContext | null;
  roles: OrgRole[];
  users: DirectoryUser[];
  groups: RawGroup[];
  projects: RawProject[];
  events: RawEventPage[];
  /** One row per parent and kid; only parents are users, the kids are read through them. */
  families: FamilyRow[];
  loading: boolean;
  /** One message per source that failed; the others still show. */
  errors: string[];
  loadedAt: number | null;
  refresh: () => void;
}

const DirectoryContext = createContext<DirectoryState | null>(null);

/**
 * The organisation's roles, projects, users, groups and events, read the
 * way the admin services read them (see `directoryApi.ts`), once per
 * organisation and shared, so the Directory screen - which unmounts on
 * every rail switch - opens instantly after the first visit.
 *
 * The organisation is the token's cudb service id; the connection id
 * goes into the topic header of each call, as the backend sends it.
 */
export const DirectoryProvider: FC = ({ children }) => {
  const { encrypted_token } = useSelector((state: RootState) => state.auth) as any;
  const [roles, setRoles] = useState<OrgRole[]>([]);
  const [users, setUsers] = useState<DirectoryUser[]>([]);
  const [groups, setGroups] = useState<RawGroup[]>([]);
  const [projects, setProjects] = useState<RawProject[]>([]);
  const [events, setEvents] = useState<RawEventPage[]>([]);
  const [families, setFamilies] = useState<FamilyRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);
  const [loadedAt, setLoadedAt] = useState<number | null>(null);
  const loadedFor = useRef<string | null>(null);
  const seq = useRef(0);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const serviceId: string | null = encrypted_token?.cudbServiceId || encrypted_token?.serviceId || null;
  const connectionId: string = String(encrypted_token?.connectionId || "");

  const context = useMemo<OrgContext | null>(
    () => (serviceId ? { serviceId: String(serviceId), connectionId } : null),
    [serviceId, connectionId]
  );

  const ready = !!context;

  const load = useCallback(async () => {
    if (!context) return;
    const mine = ++seq.current;
    setLoading(true);
    setErrors([]);
    const failures: string[] = [];

    /* Roles (and projects) first: the user list is filtered by role id. */
    const adminResult = await fetchOrgAdmin(context);
    if (!mounted.current || mine !== seq.current) return;
    let orgRoles: OrgRole[] = [];
    if (adminResult.ok === false) {
      failures.push(`Roles and projects: ${adminResult.error}`);
    } else {
      orgRoles = adminResult.data.roles;
      setProjects(adminResult.data.projects);
    }
    setRoles(orgRoles);

    const [userResult, groupResult, eventResult, familyResult] = await Promise.all([
      fetchUsersByRoleIds(context, directoryRoleIds(orgRoles)),
      fetchGroups(context),
      fetchEventPages(context),
      fetchFamilies(context),
    ]);
    if (!mounted.current || mine !== seq.current) return;
    if (userResult.ok === false) failures.push(`Users: ${userResult.error}`);
    else setUsers(userResult.data.map((raw) => toDirectoryUser(raw, orgRoles)).filter((u): u is DirectoryUser => u !== null));
    if (groupResult.ok === false) failures.push(`Groups: ${groupResult.error}`);
    else setGroups(groupResult.data);
    if (eventResult.ok === false) failures.push(`Events: ${eventResult.error}`);
    else setEvents(eventResult.data);
    if (familyResult.ok === false) failures.push(`Parents and kids: ${familyResult.error}`);
    else setFamilies(familyResult.data);
    setErrors(failures);
    setLoading(false);
    setLoadedAt(Date.now());
  }, [context]);

  /* One load per organisation. */
  useEffect(() => {
    if (!context) return;
    if (loadedFor.current === context.serviceId) return;
    loadedFor.current = context.serviceId;
    load();
  }, [context, load]);

  const refresh = useCallback(() => {
    if (ready) load();
  }, [ready, load]);

  const value: DirectoryState = {
    ready,
    context,
    roles,
    users,
    groups,
    projects,
    events,
    families,
    loading,
    errors,
    loadedAt,
    refresh,
  };
  return <DirectoryContext.Provider value={value}>{children}</DirectoryContext.Provider>;
};

export const useDirectory = (): DirectoryState => {
  const context = useContext(DirectoryContext);
  if (!context) throw new Error("useDirectory must be used inside a DirectoryProvider");
  return context;
};
