/**
 * Directory — the platform's users, groups and events in the shapes the
 * Directory tables already render, with the Stripe figures attached
 * where a user's `stripeCustomerId` matches a charge.
 *
 * What the platform does not record (plans, due dates, outstanding and
 * past-due balances, guardians, contracts) stays empty: the columns are
 * kept as they are and show "-".
 */
import moment, { Moment } from "moment";

import { BillableEntity, BillingSnapshot, Domain, EntityKind, ProjectRollup } from "../types";
import { billingStatusOf } from "../selectors";
import { StripePaymentRow } from "../stripe/chargeModel";
import { RawEventPage, RawGroup, RawProject, RawRole, RawUser } from "./directoryApi";
import { KidRow, kidName } from "../../../School3/Dashboard/Student/familyRows";

export type PeopleKind = Extract<EntityKind, "players" | "coaches" | "staff">;

/** One role of the org, as `role/getAll` returns it. */
export type OrgRole = RawRole;

/**
 * Which Directory table a role belongs to, by role name. Sport and Edu
 * names both count, whatever the domain toggle says, so an org's
 * "student" role lists under Players / Students either way.
 */
const ROLE_NAMES: Record<PeopleKind, string[]> = {
  players: ["player", "players", "student", "students"],
  coaches: ["coach", "coaches", "teacher", "teachers"],
  staff: ["staff"],
};

export const kindOfRole = (role: OrgRole): PeopleKind | null => {
  const name = (role.name || "").trim().toLowerCase();
  const kinds = Object.keys(ROLE_NAMES) as PeopleKind[];
  for (const kind of kinds) if (ROLE_NAMES[kind].indexOf(name) !== -1) return kind;
  return null;
};

/** The role ids of every role that lists in one of the three tables. */
export const directoryRoleIds = (roles: OrgRole[]): string[] =>
  roles.filter((role) => kindOfRole(role) !== null).map((role) => String(role._id));

/* ------------------------------------------------------------------ */
/* Stripe match                                                        */
/* ------------------------------------------------------------------ */

export interface CustomerFigures {
  currency: string;
  charged: number;
  refunded: number;
  net: number;
  charges: number;
  lastChargeAt: number;
}

/** Captured charges rolled up per Stripe customer id. */
export const figuresByCustomer = (rows: StripePaymentRow[]): Map<string, CustomerFigures> => {
  const map = new Map<string, CustomerFigures>();
  rows.forEach((row) => {
    if (!row.customerId) return;
    if (!(row.rawStatus === "succeeded" && row.charge.captured)) return;
    const acc = map.get(row.customerId) || {
      currency: row.currency,
      charged: 0,
      refunded: 0,
      net: 0,
      charges: 0,
      lastChargeAt: 0,
    };
    acc.charged += row.amountCaptured;
    acc.refunded += row.amountRefunded;
    acc.net = acc.charged - acc.refunded;
    acc.charges += 1;
    acc.lastChargeAt = Math.max(acc.lastChargeAt, row.createdAt);
    map.set(row.customerId, acc);
  });
  return map;
};

const round2 = (value: number) => Number(value.toFixed(2));

const emptyBilling = (currency: string): BillingSnapshot => ({
  currency,
  billed: 0,
  collected: 0,
  outstanding: 0,
  pastDue: 0,
  nextDueAt: null,
  lastActivityAt: null,
});

/** Stripe figures as the Directory's billing snapshot: charged as billed, net as collected; nothing is scheduled. */
const billingFrom = (figures: CustomerFigures | undefined, currency: string): BillingSnapshot =>
  figures
    ? {
        currency: figures.currency,
        billed: round2(figures.charged),
        collected: round2(figures.net),
        outstanding: 0,
        pastDue: 0,
        nextDueAt: null,
        lastActivityAt: figures.lastChargeAt || null,
      }
    : emptyBilling(currency);

const sumBilling = (parts: BillingSnapshot[], currency: string): BillingSnapshot =>
  parts.reduce<BillingSnapshot>(
    (acc, part) => ({
      ...acc,
      billed: round2(acc.billed + part.billed),
      collected: round2(acc.collected + part.collected),
      outstanding: round2(acc.outstanding + part.outstanding),
      pastDue: round2(acc.pastDue + part.pastDue),
      lastActivityAt:
        part.lastActivityAt !== null && (acc.lastActivityAt === null || part.lastActivityAt > acc.lastActivityAt)
          ? part.lastActivityAt
          : acc.lastActivityAt,
    }),
    emptyBilling(currency)
  );

/* ------------------------------------------------------------------ */
/* Users                                                               */
/* ------------------------------------------------------------------ */

export interface DirectoryUser {
  id: string;
  name: string;
  email: string;
  phone: string;
  customId: string;
  roleId: string;
  roleName: string;
  kind: PeopleKind;
  stripeCustomerId: string | null;
  userStatus: string;
  beamId: string | null;
}

export const toDirectoryUser = (raw: RawUser, roles: OrgRole[]): DirectoryUser | null => {
  const roleId = raw.roleId === null || raw.roleId === undefined ? "" : String(raw.roleId);
  const role = roles.find((r) => String(r._id) === roleId);
  const kind = role ? kindOfRole(role) : null;
  if (!kind) return null;
  const name = `${raw.firstName || ""} ${raw.lastName || ""}`.trim();
  return {
    id: String(raw._id),
    name: name || raw.email || raw.customId || String(raw._id),
    email: raw.email || "",
    phone: raw.phoneNumber || "",
    customId: raw.customId || "",
    roleId,
    roleName: role ? role.name : "",
    kind,
    stripeCustomerId: raw.stripeCustomerId ? String(raw.stripeCustomerId) : null,
    userStatus: raw.status || "",
    beamId: raw.beamId ? String(raw.beamId) : null,
  };
};

const ROLE_LABELS: Record<PeopleKind, { sport: string; edu: string }> = {
  players: { sport: "Player", edu: "Student" },
  coaches: { sport: "Coach", edu: "Teacher" },
  staff: { sport: "Staff", edu: "Staff" },
};

/** Something a user can belong to: a group or a project, by id and name. */
export interface Membership {
  id: string;
  name: string;
}

/** The groups and projects a user belongs to (projects by member or manager), by user id. */
export const membershipsByUser = (groups: RawGroup[], projects: RawProject[]): Map<string, Membership[]> => {
  const map = new Map<string, Membership[]>();
  const add = (userId: string, membership: Membership) => {
    const list = map.get(userId) || [];
    if (!list.some((m) => m.id === membership.id)) list.push(membership);
    map.set(userId, list);
  };
  groups.forEach((group) => {
    (group.members || []).forEach((member) => add(String(member._id), { id: group._id, name: group.name || group._id }));
  });
  projects.forEach((project) => {
    const membership = { id: project._id, name: project.name || project.customId || project._id };
    (project.liveUserIds || []).forEach((id) => add(String(id), membership));
    (project.managerLiveUserIds || []).forEach((id) => add(String(id), membership));
  });
  return map;
};

export const toBillableEntity = (
  user: DirectoryUser,
  domain: Domain,
  memberOf: Membership[],
  figures: Map<string, CustomerFigures>,
  currency: string
): BillableEntity => {
  const kind: BillableEntity["kind"] = user.kind === "players" ? "player" : user.kind === "coaches" ? "coach" : "staff";
  return {
    id: user.id,
    domain,
    kind,
    side: user.kind === "players" ? "ar" : "ap",
    name: user.name,
    role: user.roleName || ROLE_LABELS[user.kind][domain],
    email: user.email,
    phone: user.phone,
    projectIds: memberOf.map((m) => m.id),
    projectNames: memberOf.map((m) => m.name),
    paymentConfigId: null,
    billing: billingFrom(user.stripeCustomerId ? figures.get(user.stripeCustomerId) : undefined, currency),
    stripeCustomerId: user.stripeCustomerId,
  };
};

/**
 * A kid as a player row (one per kid, with both parents folded in). Money and
 * requests go through a parent (the only users): the primary parent is the
 * `payer` (the first listed when none is marked primary) and billing reads
 * their Stripe customer. The Guardian column names both parents.
 */
export const toFamilyEntity = (
  row: KidRow,
  domain: Domain,
  memberOf: Membership[],
  figures: Map<string, CustomerFigures>,
  currency: string,
  roles: OrgRole[] = []
): BillableEntity => {
  /* Recreational / Travelling is the kid's own role (their registration record). */
  const kidRole = roles.find((r) => String(r._id) === String(row.kid.roleId));
  const playerType = kidRole && /recreation|travel/i.test(kidRole.name || "") ? kidRole.name : "";
  const live = row.kid.user?.live;
  const payerParent = row.parents[0];
  const stripeCustomerId = payerParent.stripeCustomerId || null;
  return {
    id: `kid:${row.key}`,
    domain,
    kind: "player",
    side: "ar",
    name: kidName(row.kid),
    role: ROLE_LABELS.players[domain],
    email: live?.alternativeIds?.email || "",
    phone: live?.alternativeIds?.phone || "",
    household: row.parents
      .map((p) => [p.name, p.relation].filter(Boolean).join(" · "))
      .join(", "),
    playerType,
    projectIds: memberOf.map((m) => m.id),
    projectNames: memberOf.map((m) => m.name),
    paymentConfigId: null,
    billing: billingFrom(stripeCustomerId ? figures.get(stripeCustomerId) : undefined, currency),
    stripeCustomerId,
    payer: {
      id: payerParent.id,
      name: payerParent.name,
      email: payerParent.email || null,
      phone: payerParent.phone || null,
      beamId: payerParent.beamId || null,
      stripeCustomerId,
    },
  };
};

/* ------------------------------------------------------------------ */
/* Groups → teams                                                      */
/* ------------------------------------------------------------------ */

const GROUP_KIND: Record<string, string> = {
  static: "Team",
  dynamic: "Dynamic group",
  nonbeamer: "Non-beamer group",
  organization: "Organization",
};

export const toTeamRollup = (
  group: RawGroup,
  domain: Domain,
  usersById: Map<string, DirectoryUser>,
  figures: Map<string, CustomerFigures>,
  currency: string
): ProjectRollup => {
  const members = group.members || [];
  const parts = members.map((member) => {
    const user = usersById.get(String(member._id));
    return billingFrom(user && user.stripeCustomerId ? figures.get(user.stripeCustomerId) : undefined, currency);
  });
  const billing = sumBilling(parts, currency);
  return {
    id: group._id,
    name: group.name || group._id,
    kind: GROUP_KIND[group.type || ""] || (group.type ? group.type : "Group"),
    domain,
    paymentConfigId: null,
    paymentConfigName: "",
    currency,
    totalAmount: 0,
    memberCount: members.length,
    group: "team",
    billing,
    collectedPct: billing.billed > 0 ? Math.min(100, Math.round((billing.collected / billing.billed) * 100)) : 0,
    status: billingStatusOf(billing),
  };
};

/* ------------------------------------------------------------------ */
/* Projects → teams                                                    */
/* ------------------------------------------------------------------ */

const PROJECT_KIND_LABELS: Record<string, string> = {
  vehicle: "Vehicle project",
};

/** The free-form dates projects store; epoch ms or null. */
const projectDate = (value: unknown): number | undefined => {
  if (value === null || value === undefined || value === "") return undefined;
  const m = parseScheduleDate(value);
  return m ? m.valueOf() : undefined;
};

/**
 * A project as a Teams row: its members (and managers) carry the Stripe
 * figures; its payment configuration id is kept for the Plan column.
 */
export const toProjectRollup = (
  project: RawProject,
  domain: Domain,
  usersById: Map<string, DirectoryUser>,
  figures: Map<string, CustomerFigures>,
  currency: string
): ProjectRollup => {
  const memberIds = Array.from(new Set((project.liveUserIds || []).map((id) => String(id))));
  const parts = memberIds.map((id) => {
    const user = usersById.get(id);
    return billingFrom(user && user.stripeCustomerId ? figures.get(user.stripeCustomerId) : undefined, currency);
  });
  const billing = sumBilling(parts, currency);
  const typeLabel = project.type ? PROJECT_KIND_LABELS[project.type] || `${project.type} project` : "Project";
  return {
    id: project._id,
    name: project.name || project.customId || project._id,
    kind: project.status ? `${typeLabel} · ${project.status}` : typeLabel,
    domain,
    paymentConfigId: project.paymentConfigId || null,
    paymentConfigName: project.payment?.info?.name || "",
    currency,
    totalAmount: Number(project.payment?.info?.amount) || 0,
    memberCount: memberIds.length,
    startsAt: projectDate(project.startDate),
    endsAt: projectDate(project.endDate),
    group: "team",
    billing,
    collectedPct: billing.billed > 0 ? Math.min(100, Math.round((billing.collected / billing.billed) * 100)) : 0,
    status: billingStatusOf(billing),
  };
};

/* ------------------------------------------------------------------ */
/* Event pages → events                                                */
/* ------------------------------------------------------------------ */

/** The free-form schedule date of an event page, in the formats School3 accepts. */
export const parseScheduleDate = (scheduleDate: unknown): Moment | undefined => {
  if (scheduleDate === null || scheduleDate === undefined || scheduleDate === "") return undefined;
  const formats = ["MM/DD/YYYY HH:mm:ss", "MM/DD/YYYY", "YYYY-MM-DD HH:mm:ss", "YYYY-MM-DD", moment.ISO_8601];
  let m = moment(scheduleDate as any, formats as any, false);
  if (!m.isValid()) m = moment(scheduleDate as any);
  if (!m.isValid() && !isNaN(Number(scheduleDate))) m = moment(Number(scheduleDate));
  return m.isValid() ? m : undefined;
};

export const toEventRollup = (page: RawEventPage, domain: Domain, currency: string): ProjectRollup => {
  const event = page.profile?.event || {};
  const day = parseScheduleDate(event.scheduleDate);
  const billing = emptyBilling(currency);
  return {
    id: page.pageId,
    name: event.title || page.profile?.title || "Event",
    kind: page.status ? `Event · ${page.status}` : "Event",
    domain,
    paymentConfigId: null,
    paymentConfigName: "",
    currency,
    totalAmount: 0,
    memberCount: 0,
    startsAt: day ? day.valueOf() : undefined,
    endsAt: undefined,
    group: "event",
    billing,
    collectedPct: 0,
    status: billingStatusOf(billing),
  };
};
