import moment from "moment";

/**
 * TANF outcome stats for the Lighthouse dashboard.
 *
 * Customer records hold only current answers, with no change history, so most
 * stats read from them are "all time" totals. Two kinds of stat have a real date
 * and follow the dashboard's date filter: service event pages, and employment
 * stats, which use employmentStartingDate.
 */

export type TanfStatScope = "allTime" | "selectedRange";
export type TanfStatFormat = "count" | "currency";

export interface TanfStat {
    key: string;
    label: string;
    /** null means there is no data source yet, shown as "Not tracked yet". A real zero stays 0. */
    value: number | null;
    format: TanfStatFormat;
    /** True when the value counts clients, so a share of TANF clients makes sense. */
    countsClients: boolean;
}

export interface TanfStatGroup {
    key: string;
    title: string;
    scope: TanfStatScope;
    stats: TanfStat[];
    /** Caveat shown under the group, for example clients left out for lacking a date. */
    note?: string;
}

export interface TanfStatsResult {
    totalClients: number;
    groups: TanfStatGroup[];
}

interface TanfServiceConfig {
    name: string;
    projectIds?: string[];
}

interface TanfBuildingConfig {
    name: string;
    includeStats?: boolean;
    categories: { services: TanfServiceConfig[] }[];
}

export interface TanfDateRange {
    start: number;
    end: number;
}

export interface TanfStatsInput {
    customers: any[];
    pages: any[];
    config: { buildings: TanfBuildingConfig[] } | null;
    isEligible: (customer: any) => boolean;
    /** The date filter's range in milliseconds. Null means no filter is applied. */
    dateRange?: TanfDateRange | null;
    now?: moment.MomentInput;
}

/**
 * Which report config services feed the service-based stats, matched on service name.
 * These are keyword defaults: replace them with the exact names from the TANF report
 * config, otherwise an unrelated service containing the keyword would be counted.
 */
export const TANF_SERVICE_MATCHERS = {
    classes: /\bclass/i,
    rides: /\bride/i,
    foodPantryBicyclesClothes: /food pantry|bicycle|cloth/i,
};

const EMPLOYED_STATUSES = ["full-time", "part-time", "self-employed"];
const DATE_FORMATS = ["MM/DD/YYYY", "YYYY-MM-DD", "MMDDYYYY", moment.ISO_8601];

// Handles both a single projectId and an array of them
export const getPageProjectIds = (page: any): string[] => {
    // Try multiple paths for projectId
    const projectId = page?.static?.profile?.projectId || page?.projectId;

    // Handle array case
    if (Array.isArray(projectId)) {
        return projectId.filter(id => id != null && id !== '');
    }

    // Handle single value
    if (projectId != null && projectId !== '') {
        return [projectId];
    }

    return [];
};

export const getPageBuildingName = (page: any): string | null => {
    const buildingName = page?.static?.profile?.buildingName || page?.buildingName;
    return buildingName != null && buildingName !== '' ? buildingName : null;
};

const getPageCustomerId = (page: any) => page?.static?.profile?.customerId || page?.customerId;

// Same building rule as calculateStats, so these numbers reconcile with the building cards
const pageMatchesBuilding = (page: any, building: TanfBuildingConfig): boolean => {
    const pageBuildingName = getPageBuildingName(page);
    return building.includeStats
        ? pageBuildingName === building.name
        : !pageBuildingName || pageBuildingName === building.name;
};

// Saved values vary in case, for example "Have It" and "Have it"
const normalize = (value: unknown): string => String(value ?? "").trim().toLowerCase();
const isYes = (value: unknown): boolean => normalize(value) === "yes";
const hasIt = (value: unknown): boolean => normalize(value) === "have it";
const isBlank = (value: unknown): boolean => normalize(value) === "";

const parseAmount = (value: unknown): number | null => {
    if (isBlank(value)) return null;
    const amount = Number(String(value).replace(/[$,\s]/g, ""));
    return Number.isFinite(amount) && amount > 0 ? amount : null;
};

const average = (values: unknown[]): number | null => {
    const amounts = values.map(parseAmount).filter((amount): amount is number => amount !== null);
    if (!amounts.length) return null;
    return amounts.reduce((sum, amount) => sum + amount, 0) / amounts.length;
};

const parseDate = (value: unknown): moment.Moment | null => {
    if (isBlank(value)) return null;
    const date = moment(String(value).trim(), DATE_FORMATS as any, true);
    return date.isValid() ? date : null;
};

const isEmployed = (client: any): boolean =>
    hasIt(client.Employment) || EMPLOYED_STATUSES.includes(normalize(client.employmentStatus));

const receivedCredential = (client: any): boolean =>
    hasIt(client.HighSchoolDiplomaGED) ||
    hasIt(client.ProfessionalLicenseCertification) ||
    isYes(client.obtainedGEDNEDPAdultHSDiploma);

const clientStat = (key: string, label: string, value: number | null): TanfStat => ({
    key,
    label,
    value,
    format: "count",
    countsClients: true,
});

const eventStat = (key: string, label: string, value: number | null): TanfStat => ({
    key,
    label,
    value,
    format: "count",
    countsClients: false,
});

const currencyStat = (key: string, label: string, value: number | null): TanfStat => ({
    key,
    label,
    value,
    format: "currency",
    countsClients: false,
});

const calculateServiceStats = (
    tanfCustomerIds: Set<any>,
    pages: any[],
    config: TanfStatsInput["config"]
) => {
    const configuredServices = (config?.buildings || []).flatMap(building =>
        (building.categories || []).flatMap(category =>
            (category.services || [])
                .filter(service => (service.projectIds || []).length > 0)
                .map(service => ({ building, service }))
        )
    );

    const hasService = (matcher: RegExp) =>
        configuredServices.some(({ service }) => matcher.test(service.name));

    const participants = new Set<any>();
    const classSessions = new Set<string>();
    const foodPantryClients = new Set<any>();
    let rides = 0;

    pages.forEach((page, pageIndex) => {
        const customerId = getPageCustomerId(page);
        if (!customerId || !tanfCustomerIds.has(customerId)) return;

        const pageProjectIds = getPageProjectIds(page);
        const matches = configuredServices.filter(({ building, service }) =>
            pageMatchesBuilding(page, building) &&
            pageProjectIds.some(id => (service.projectIds || []).includes(id))
        );
        if (!matches.length) return;

        const matchesService = (matcher: RegExp) =>
            matches.some(({ service }) => matcher.test(service.name));

        participants.add(customerId);

        if (matchesService(TANF_SERVICE_MATCHERS.classes)) {
            // Each attendee has their own page, so one session is identified by its schedule
            const { scheduleDate, scheduleTime } = page?.static?.profile || {};
            classSessions.add(
                scheduleDate && scheduleTime
                    ? `${pageProjectIds[0]}|${scheduleDate}|${scheduleTime}`
                    : `page|${page?.objectId ?? pageIndex}`
            );
        }
        if (matchesService(TANF_SERVICE_MATCHERS.rides)) {
            rides++;
        }
        if (matchesService(TANF_SERVICE_MATCHERS.foodPantryBicyclesClothes)) {
            foodPantryClients.add(customerId);
        }
    });

    return {
        participants: configuredServices.length ? participants.size : null,
        classesHeld: classSessions.size,
        rides: hasService(TANF_SERVICE_MATCHERS.rides) ? rides : null,
        foodPantryClients: hasService(TANF_SERVICE_MATCHERS.foodPantryBicyclesClothes)
            ? foodPantryClients.size
            : null,
    };
};

export const calculateTanfStats = ({
    customers,
    pages,
    config,
    isEligible,
    dateRange,
    now,
}: TanfStatsInput): TanfStatsResult => {
    const tanfCustomers = customers.filter(customer => isEligible(customer));
    const clients = tanfCustomers.map(customer => customer.info.customer);
    const count = (predicate: (client: any) => boolean) => clients.filter(predicate).length;

    const service = calculateServiceStats(
        new Set(tanfCustomers.map(customer => customer.id).filter(Boolean)),
        pages,
        config
    );

    const employed = clients.filter(isEmployed);
    const startDateOf = (client: any) => parseDate(client.employmentStartingDate);
    const today = moment(now);
    const rangeStart = dateRange ? moment(dateRange.start) : null;
    const rangeEnd = dateRange ? moment(dateRange.end) : null;

    const missingStartDates = employed.filter(client => !startDateOf(client)).length;
    const hasStartDates = missingStartDates < employed.length;

    // With a date filter, only a start date inside the range counts as entering employment
    const enteredEmployment = rangeStart
        ? employed.filter(client => {
            const startDate = startDateOf(client);
            return !!startDate && startDate.isBetween(rangeStart, rangeEnd, "day", "[]");
        })
        : employed;
    const enteredCount = (predicate: (client: any) => boolean = () => true): number | null =>
        rangeStart && !hasStartDates ? null : enteredEmployment.filter(predicate).length;

    // With a date filter, counts clients who reached the milestone inside the range.
    // Without one, counts everyone who has reached it so far.
    const employedForMonths = (months: number): number | null => {
        if (!hasStartDates) return null;
        const latest = rangeEnd && rangeEnd.isBefore(today) ? rangeEnd : today;
        return employed.filter(client => {
            const startDate = startDateOf(client);
            if (!startDate) return false;
            const milestone = startDate.clone().add(months, "months");
            if (milestone.isAfter(latest, "day")) return false;
            return !rangeStart || milestone.isSameOrAfter(rangeStart, "day");
        }).length;
    };

    const missingStartDatesNote = missingStartDates > 0
        ? `${missingStartDates.toLocaleString()} employed ${missingStartDates === 1 ? "client has" : "clients have"} no start date and ${missingStartDates === 1 ? "isn't" : "aren't"} counted here.`
        : undefined;

    const benefitsTracked = clients.some(client => !isBlank(client.employedWithBenefits));

    // Counts every customer answering Yes, including any who fail the calculated eligibility
    // check, so it isn't shown as a share of TANF clients
    const allClients = customers.map(customer => customer?.info?.customer).filter(Boolean);
    const receivingBenefitsTracked = allClients.some(client => !isBlank(client.receivingTanFBenefits));
    const receivingBenefits = receivingBenefitsTracked
        ? allClients.filter(client => isYes(client.receivingTanFBenefits)).length
        : null;

    return {
        totalClients: clients.length,
        groups: [
            {
                key: "participation",
                title: "Participation",
                scope: "selectedRange",
                stats: [
                    clientStat("participatingInServices", "Participating in services", service.participants),
                    eventStat("classesHeld", "Classes held at the Education Center", service.classesHeld),
                    eventStat("ridesToTanfStops", "Rides to TANF stops", service.rides),
                    clientStat("foodPantryBicyclesClothes", "Accessing Food Pantry/Bicycles/Clothes", service.foodPantryClients),
                ],
            },
            {
                key: "employmentStarts",
                title: "Entering employment",
                scope: "selectedRange",
                note: rangeStart ? missingStartDatesNote : undefined,
                stats: [
                    clientStat("enteredEmployment", "Entered employment", enteredCount()),
                    clientStat("enteredPartTime", "Entered employment part-time", enteredCount(c => normalize(c.employmentStatus) === "part-time")),
                    clientStat("enteredFullTime", "Entered employment full-time", enteredCount(c => normalize(c.employmentStatus) === "full-time")),
                    currencyStat("averageStartingWage", "Average starting hourly wage", average(enteredEmployment.map(c => c.averageStartingHourlyWage))),
                ],
            },
            {
                key: "retention",
                title: "Job retention",
                scope: "selectedRange",
                note: missingStartDatesNote,
                stats: [
                    clientStat("employedThreeMonths", "Employed for 3 months", employedForMonths(3)),
                    clientStat("employedSixMonths", "Employed for 6 months", employedForMonths(6)),
                    clientStat("employedOneYear", "Employed for 1 year", employedForMonths(12)),
                ],
            },
            {
                key: "employmentOutcomes",
                title: "Employment outcomes",
                scope: "allTime",
                stats: [
                    clientStat(
                        "employedWithBenefits",
                        "Employed with benefits",
                        benefitsTracked ? employed.filter(c => isYes(c.employedWithBenefits)).length : null
                    ),
                    clientStat("partTimeToFullTime", "Moved from part-time to full-time", count(c => isYes(c.movedFromPartTimeToFullTimeEmployment))),
                    clientStat("careerPathways", "Obtained jobs in a Career Pathway", count(c => isYes(c.obtainedJobsInCareerPathways))),
                    clientStat("obtainedWageIncrease", "Obtained wage increase", count(c => isYes(c.obtainedWageIncrease))),
                    currencyStat(
                        "averageWageIncrease",
                        "Average hourly wage increase",
                        average(clients.filter(c => isYes(c.obtainedWageIncrease)).map(c => c.hourlyWageIncrease))
                    ),
                ],
            },
            {
                key: "education",
                title: "Education & training",
                scope: "allTime",
                stats: [
                    clientStat("adultEducation", "In Adult Education Classes", count(c => isYes(c.adultEducationClasses))),
                    clientStat("educationCenter", "In Lighthouse Education Center Classes", count(c => isYes(c.lighthouseEducationCenterClasses))),
                    clientStat("jobSkillsTraining", "In Job Skills Training (IET or FastForward)", count(c => isYes(c.participatingJobSkillsTraining))),
                    clientStat("credential", "Received a credential", count(receivedCredential)),
                    clientStat("gedDiploma", "Obtained GED/NEDP Adult HS Diploma", count(c => isYes(c.obtainedGEDNEDPAdultHSDiploma))),
                ],
            },
            {
                key: "support",
                title: "Health, housing & support",
                scope: "allTime",
                stats: [
                    { ...clientStat("receivingTanfBenefits", "Receiving TANF benefits", receivingBenefits), countsClients: false },
                    clientStat("obtainedSsi", "Obtained SSI", count(c => isYes(c.obtainedSSI))),
                    clientStat("completedTreatment", "Completed their treatment", count(c => isYes(c.completedTreatment))),
                    clientStat("mentalHealthServices", "In Mental Health/Psych Services", count(c => isYes(c.obtainingMentalHealthPsychServices))),
                    clientStat("lodgeHousing", "Living in TANF Lighthouse Lodge Housing", count(c => isYes(c.livingInTANFLighthouseLodgeHousing))),
                    clientStat("otherAchievements", "Other achievements (received job coaching)", count(c => isYes(c.otherAchievementsReceivedJobCoaching))),
                ],
            },
        ],
    };
};
