import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Button, Row, Col, Table, Input, Skeleton, DatePicker, Radio, Select, Rate, Tag } from "antd";

import { ReactSVG } from "react-svg";
import {
  SearchOutlined,
  ArrowLeftOutlined,
  EditOutlined,
  SettingOutlined,
  StarOutlined,
  EyeOutlined,
} from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import { formatForRedis } from "utils/appUtil";
import { USER_TYPES, PERMISSION_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { SocketTopics, UserTopics, ExtendedBioTopics } from "constants/enums";
import useSocketActions from "../../../../../hooks/socketActions";
import { pushNotification } from "utils/notifications";
import moment from "moment";
import AddToGroupModal, { GroupUser } from "../Groups/AddToGroupModal";
import ShowRatingsModal from "./ShowRatingsModal";
import AssignCoachesModal from "../Groups/AssignCoachesModal";
import RatingModal from "./RatingModal";
import {
  FamilyRow,
  KidRow,
  distinctKidCount,
  familyMembers,
  fetchFamilyRows,
  groupByKid,
  kidInCoachScope,
  kidName,
} from "./familyRows";
import {
  CoachScope,
  fetchRatedUserIds,
  fetchTeamMemberIds,
  PlayerRating,
  useOrgTeamOptions,
  usePageOptions,
  useSurveyOptions,
} from "./ratingSources";
import "../Dashboard.scss";

let timeout;

// Sports dashboard: the Players screen can be narrowed to one player team role
// via the Team dropdown. The roles differ per organization, so they are matched
// by name on the org's own roles (mirrors SIGNUP_ROLE_CANDIDATES in Programs)
// rather than hardcoding their ids.
const PLAYER_TEAM_ROLE_NAMES = [
  "recreational",
  "travelling",
  "traveller",
  "traveler",
  "travel",
];

// Only travel-registered players can be rated or assigned coaches (tryouts).
const TRAVEL_ROLE_NAMES = ["travelling", "traveller", "traveler", "travel"];

const StudentsModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userRole?: any;
  /** For a coach: their teams and those teams' members (see useCoachScope). */
  coachScope?: CoachScope;
}> = ({ socket, params, componentUuid, userRole, coachScope }) => {
  const { selectedPage, encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const [tableDataSource, setTableDataSource] = useState<any>([]);
  const [tableColumns, setTableColumns] = useState<any>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const students = useRef<any>();
  const [iframeStudentId, setIframeStudentId] = useState<any>(undefined);
  const [iframeStudentName, setIframeStudentName] = useState<any>("");
  // Player whose Rating popup is open (survey + page pickers, then the form).
  const [ratingUser, setRatingUser] = useState<
    { userId: any; name?: string } | undefined
  >(undefined);
  // Player whose "Show Ratings" popup is open (each coach's rating + overall).
  const [showRatingsUser, setShowRatingsUser] = useState<
    { userId: any; name?: string } | undefined
  >(undefined);
  // Pages filter: picking a page reads the survey responses stored on it and
  // keeps only the players who were rated there.
  const { pages: pageOptions, loading: pagesLoading } = usePageOptions();
  const { surveys: surveyOptions } = useSurveyOptions();
  const [pageFilter, setPageFilter] = useState<string | undefined>(undefined);
  const pageFilterRef = useRef<string | undefined>(undefined);
  const [ratedUserIds, setRatedUserIds] = useState<string[] | undefined>(undefined);
  // Each rated player's score on the selected page, shown in the Rating column.
  const [ratings, setRatings] = useState<Record<string, PlayerRating> | undefined>(
    undefined
  );
  const [ratedLoading, setRatedLoading] = useState<boolean>(false);
  const [configureMode, setConfigureMode] = useState<boolean>(false);
  const isMounted = useRef(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  const [selectedRole, setSelectedRole] = useState<any>({});
  useEffect(() => {
    if (adminUserRoles.length > 0) {
      const coachRole = adminUserRoles.filter(
        (x: any) =>
          x.name.toLowerCase() === "player" &&
          x.permissions.indexOf(PERMISSION_TYPES.OnMove) === -1 &&
          x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1 &&
          x.permissions.indexOf(PERMISSION_TYPES.Dashboard) === -1 && x.permissions.indexOf(PERMISSION_TYPES.Live) !== -1
      );
      setSelectedRole(coachRole[0] || {});

    }
  }, [adminUserRoles]);

  // Attendance: track the date being managed and the per-student status map.
  // Refs mirror state so the (memoised) column renderers always read fresh values.
  const [attendanceDate, setAttendanceDate] = useState<any>(moment());
  const attendanceDateRef = useRef<any>(attendanceDate);
  const [attendance, setAttendance] = useState<any>({});
  const attendanceRef = useRef<any>({});
  const [savingAttendanceId, setSavingAttendanceId] = useState<any>(undefined);
  const savingAttendanceRef = useRef<any>(undefined);

  // Class assignment: classes are projects. Map keeps the assigned project ids
  // per user; refs mirror state so the (memoised) column renderers stay fresh.
  const [classesByUser, setClassesByUser] = useState<any>({});
  const classesByUserRef = useRef<any>({});
  const [savingClassesId, setSavingClassesId] = useState<any>(undefined);
  const savingClassesRef = useRef<any>(undefined);
  // Selected class to filter the table by (client-side, against assigned classes).
  const [classFilter, setClassFilter] = useState<any>(undefined);
  const classFilterRef = useRef<any>(undefined);
  // Selected team (Recreational / Travel) — narrows the query by roleId. The ref
  // mirrors state so the debounced search reads the current selection.
  // Multi-select + "Add to Group": adds the selected players to a BDS group.
  // Row keys are the numeric user ids (x.id), so keep React.Key here — forcing
  // them to strings would stop the controlled selection from matching the rows.
  const [selectedKeys, setSelectedKeys] = useState<React.Key[]>([]);
  const [groupModalOpen, setGroupModalOpen] = useState(false);
  const [coachesModalOpen, setCoachesModalOpen] = useState(false);
  // Date-of-birth month-range filter (MM-YYYY) over live.profile.doB.
  const [dobRange, setDobRange] = useState<[any, any] | null>(null);
  // Recreational / Travel dropdown (server-side roleId filter, using the player
  // team roles resolved from the org's own roles in playerTeamOptions).
  const [teamFilter, setTeamFilter] = useState<string | undefined>(undefined);
  const teamFilterRef = useRef<string | undefined>(undefined);
  // Dynamic filters (same source as Programs / Teams): the players' extendedBio
  // survey configs, with the selected values applied client-side to the rows.
  const [surveyConfigs, setSurveyConfigs] = useState<any[]>([]);
  const [filterValues, setFilterValues] = useState<Record<string, any>>({});
  const [playerUsers, setPlayerUsers] = useState<any[]>([]);
  // The Team dropdown lists only the org's teams (projects of the "org" type).
  const { teams: allTeams, loading: teamsLoading } = useOrgTeamOptions();
  // A coach works with the teams they manage and those teams' players (shared
  // with the Dashboard); everyone else sees all org teams.
  const scoped = !!coachScope?.scoped;
  const classOptions = scoped ? coachScope!.teams : allTeams;
  // Players on the coach's teams; undefined until read, and the table shows
  // nobody until then.
  const scopeMemberIds = coachScope?.memberIds;
  const scopeMemberBeamIds = coachScope?.memberBeamIds;
  // Players on the selected team (its group members + liveUserIds), read when a
  // team is picked. While they load, the table shows no rows for that team.
  const [teamMemberIds, setTeamMemberIds] = useState<string[] | undefined>(undefined);
  const [teamMembersLoading, setTeamMembersLoading] = useState<boolean>(false);
  // The Recreational / Travel dropdown options, resolved from the org's own
  // roles by name (ids differ per org) instead of a hardcoded list.
  const playerTeamOptions = useMemo(
    () =>
      (adminUserRoles || [])
        .filter((role: any) =>
          PLAYER_TEAM_ROLE_NAMES.includes((role?.name || "").trim().toLowerCase())
        )
        .map((role: any) => ({ label: role.name, value: role._id })),
    [adminUserRoles]
  );

  // Parents and their kids: the Players page lists one row per parent and kid.
  // Only parents are real users; the kids are non-beamer records read through
  // them (see familyRows.ts). The org is the one the token resolved to.
  const [familyRows, setFamilyRows] = useState<FamilyRow[]>([]);
  const [familySearch, setFamilySearch] = useState("");
  const orgServiceId: string | undefined = projects?.userServiceId;
  useEffect(() => {
    if (!orgServiceId) return;
    let active = true;
    fetchFamilyRows(dispatch, orgServiceId).then((rows) => {
      if (!active) return;
      console.log("[Players] family rows", rows.length);
      setFamilyRows(rows);
    });
    return () => {
      active = false;
    };
  }, [orgServiceId, dispatch]);

  // Travel applies when the org has a Travel role: a kid counts as travel when
  // their own role is one. An org with no Travel role is not restricted.
  const travelRoleIdList = useMemo(
    () =>
      (adminUserRoles || [])
        .filter((r: any) => TRAVEL_ROLE_NAMES.includes((r?.name || "").trim().toLowerCase()))
        .map((r: any) => `${r._id}`),
    [adminUserRoles]
  );

  // The kid rows, in the shape of the other Players rows: one row per kid, with
  // both parents (primary first) listed on it.
  const kidRows = useMemo(() => groupByKid(familyRows), [familyRows]);
  const familyTableRows = useMemo(
    () =>
      kidRows.map((fr) => ({
        // Prefixed so a kid's id never equals a player's user id.
        key: `kid:${fr.key}`,
        userStatus: fr.kid.user?.status?.name,
        name: kidName(fr.kid),
        parents: fr.parents,
        parentName: fr.parents.map((p) => p.name).join(" "),
        email: fr.kid.user?.live?.alternativeIds?.email,
        phone: fr.kid.user?.live?.alternativeIds?.phone,
        customId: fr.kid.user?.live?.alternativeIds?.customId,
        action: {
          userId: fr.kid.id,
          // A kid's Recreational / Travelling role is on their own record.
          isTravel:
            !travelRoleIdList.length ||
            (!!fr.kid.roleId && travelRoleIdList.includes(fr.kid.roleId)),
          user: fr.kid.user,
          name: kidName(fr.kid),
          family: fr,
        },
      })),
    [kidRows, travelRoleIdList]
  );
  // Players that are still users of their own (older registrations), then the kids.
  // Every row gets its Recreational / Travelling type from the player's role.
  const teamNameByRoleId = useMemo(() => {
    const map: Record<string, string> = {};
    playerTeamOptions.forEach((o: any) => {
      map[`${o.value}`] = `${o.label}`;
    });
    return map;
  }, [playerTeamOptions]);
  const allRows = useMemo(
    () =>
      [...(tableDataSource || []), ...familyTableRows].map((row: any) => ({
        ...row,
        typeName: teamNameByRoleId[`${row?.action?.family?.kid?.roleId ?? row?.action?.user?.roleId}`] || "",
      })),
    [tableDataSource, familyTableRows, teamNameByRoleId]
  );

  const updateClasses = (userId: string, classIds: string[]) => {
    if (!userId) return;
    const newMap = { ...classesByUserRef.current, [userId]: classIds };
    classesByUserRef.current = newMap;
    setClassesByUser(newMap);
    savingClassesRef.current = userId;
    setSavingClassesId(userId);

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(userId, [
        {
          op: "add",
          path: "/persistent/static/school/classes",
          value: classIds,
        },
      ]),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        savingClassesRef.current = undefined;
        setSavingClassesId(undefined);
        pushNotification(
          "Classes updated successfully",
          "success",
          "TOP_CENTER",
          2000
        );
      }
    );
  };

  const handleAttendanceDateChange = (date: any) => {
    if (!date) return;
    attendanceDateRef.current = date;
    setAttendanceDate(date);
  };

  const updateAttendance = (userId: string, status: string) => {
    const dateKey = attendanceDateRef.current?.format("YYYY-MM-DD");
    if (!userId || !dateKey) return;
    const record = {
      status,
      markedAt: new Date().getTime(),
      markedBy: encrypted_token?.userId,
    };
    // Merge into the existing map so prior days are preserved, then write the
    // whole attendance object one level under schoolBus (mirrors locationList).
    const userAttendance = {
      ...(attendanceRef.current?.[userId] || {}),
      [dateKey]: record,
    };
    const newMap = { ...attendanceRef.current, [userId]: userAttendance };
    attendanceRef.current = newMap;
    setAttendance(newMap);
    savingAttendanceRef.current = userId;
    setSavingAttendanceId(userId);

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(userId, [
        {
          op: "add",
          path: "/persistent/static/school/attendance",
          value: userAttendance,
        },
      ]),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        savingAttendanceRef.current = undefined;
        setSavingAttendanceId(undefined);
        pushNotification(
          "Attendance updated successfully",
          "success",
          "TOP_CENTER",
          2000
        );
      }
    );
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const formatUserFilterText = (text: string) => {
    var result = "";
    let comp = text
      .trim()
      .split(" ")
      .filter((word) => word.length > 2)
      .map((x) => {
        return "*" + formatForRedis(x) + "*";
      });
    if (comp.length == 0) {
      return result;
    }
    comp.forEach((element) => {
      result += `@firstName:(${element})|@lastName:(${element})|`;
    });
    result += `@beamIds:{${comp.join("|")}}`;
    return `(${result})`;
  };

  const getUsersByRole = (roles, filterText = undefined) => {
    // Without the org's roles the role filter below would be empty and the
    // server would answer "no rows"; wait for them (the effect re-runs).
    if (!roles || roles.length === 0) return;
    let searchQuery = `@serviceId:{'${formatForRedis(
      projects?.userServiceId
    )}'}`;
    if (filterText && filterText.length > 2) {
      searchQuery += formatUserFilterText(filterText);
    }
    const travelRoleIds = roles
      .filter((r: any) => TRAVEL_ROLE_NAMES.includes((r?.name || "").trim().toLowerCase()))
      .map((r: any) => r._id);
    const userRoles = roles.filter(
      (x: any) =>
        x.name.toLowerCase() === "player" &&
        x.permissions.indexOf(PERMISSION_TYPES.OnMove) === -1 &&
        x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1 &&
        x.permissions.indexOf(PERMISSION_TYPES.Dashboard) === -1 && x.permissions.indexOf(PERMISSION_TYPES.Live) !== -1
    );

    // Recreational / Travel selected: narrow to that single roleId; otherwise
    // load every player role plus both hardcoded team roleIds.
    const selectedTeam = teamFilterRef.current;
    const rolesQuery = selectedTeam
      ? [`@roleId === '${selectedTeam}'`]
      : [
          ...userRoles.map((y: any) => `@roleId === '${y._id}'`),
          ...playerTeamOptions.map((team) => `@roleId === '${team.value}'`),
        ];
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        list: {
          // Drivers see only themselves; a coach (scoped) never does.
          objectIds:
            userRole === "driver" && !coachScope?.scoped
              ? [encrypted_token?.userId]
              : undefined,
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
          schoolBus: "$..schoolBus",
          school: "$.persistent.static.school",
          extendedBio: "$..extendedBio",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.length ? rolesQuery.join("||") : "@roleId === ''"})`,
      },
      anyStatus: false,
    };
    setLoading(true);
    console.log("[Players] query", {
      userRole,
      roleCount: roles.length,
      filter: userRequest.filter.expression,
      onlyIds: userRequest.select.list.objectIds,
    });
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          setLoading(false);
          let sourceData = [];
          let columns: any = [
            {
              title: "#",
              key: "no",
              dataIndex: "no",
              width: 60,
            },
            {
              title: "Status",
              key: "userStatus",
              dataIndex: "userStatus",
              render: (status: string) => (
                <Button className="beam-btn icon-btn ml-2">
                  <ReactSVG
                    src="/images/flag-icon.svg"
                    className={`${status ?? "gray"}-icon`}
                  />
                </Button>
              ),
            },
            {
              title: "Name",
              key: "name",
              dataIndex: "name",
              sorter: (a: any, b: any) => `${a?.name ?? ""}`.localeCompare(`${b?.name ?? ""}`),
            },
            {
              title: "Type",
              key: "type",
              dataIndex: "typeName",
              width: 130,
              sorter: (a: any, b: any) => `${a?.typeName ?? ""}`.localeCompare(`${b?.typeName ?? ""}`),
              filters: playerTeamOptions.map((o: any) => ({ text: o.label, value: o.label })),
              onFilter: (value: any, record: any) => `${record?.typeName ?? ""}` === `${value}`,
              render: (value: any) =>
                value ? (
                  <Tag color={/travel/i.test(`${value}`) ? "blue" : "green"}>{value}</Tag>
                ) : (
                  "—"
                ),
            },
            {
              title: "Parents",
              key: "parent",
              dataIndex: "parentName",
              sorter: (a: any, b: any) =>
                `${a?.parents?.[0]?.name ?? ""}`.localeCompare(`${b?.parents?.[0]?.name ?? ""}`),
              render: (_: any, record: any) =>
                record?.parents?.length ? (
                  <div>
                    {record.parents.map((p: any) => (
                      <div key={p.id} style={{ marginBottom: 4 }}>
                        <div>
                          {p.name}
                          {p.relation ? (
                            <Tag
                              color={p.relation === "primary" ? "geekblue" : "default"}
                              style={{ marginLeft: 6, textTransform: "capitalize" }}
                            >
                              {p.relation}
                            </Tag>
                          ) : null}
                        </div>
                        <div style={{ color: "#8c8c8c", fontSize: 12 }}>{p.email || "no email"}</div>
                      </div>
                    ))}
                  </div>
                ) : (
                  "—"
                ),
            },
            {
              title: "Custom id",
              key: "customId",
              dataIndex: "customId",
            },
            {
              title: "Email",
              key: "email",
              dataIndex: "email",
            },
            {
              title: "Phone",
              key: "phone",
              dataIndex: "phone",
            },
            // {
            //   title: "Class",
            //   key: "classes",
            //   dataIndex: "classes",
            //   render: (_: any, record: any) => {
            //     const userId = record?.action?.userId;
            //     return (
            //       <Select
            //         mode="multiple"
            //         allowClear
            //         size="small"
            //         style={{ minWidth: 200 }}
            //         placeholder="Assign classes"
            //         options={classOptions}
            //         value={record?.classes || []}
            //         loading={record?.savingClasses}
            //         disabled={record?.savingClasses}
            //         onChange={(ids) => updateClasses(userId, ids)}
            //         filterOption={(input, option) =>
            //           (option?.label ?? "")
            //             .toString()
            //             .toLowerCase()
            //             .includes(input.toLowerCase())
            //         }
            //       />
            //     );
            //   },
            // },
            // {
            //   title: "Attendance",
            //   key: "attendance",
            //   dataIndex: "attendance",
            //   render: (_: any, record: any) => {
            //     const userId = record?.action?.userId;
            //     return (
            //       <Radio.Group
            //         size="small"
            //         optionType="button"
            //         buttonStyle="solid"
            //         value={record?.attendanceStatus}
            //         disabled={record?.savingAttendance}
            //         onChange={(e) => updateAttendance(userId, e.target.value)}
            //       >
            //         <Radio.Button value="present">Present</Radio.Button>
            //         <Radio.Button value="absent">Absent</Radio.Button>
            //         <Radio.Button value="late">Late</Radio.Button>
            //       </Radio.Group>
            //     );
            //   },
            // },
            {
              title: "Action",
              key: "action",
              dataIndex: "action",
              render: (action: any) => (
                <Row style={{ width: 135 }}>
                  <Col span={8}>
                    <Button
                      style={{ boxShadow: "none" }}
                      className="beam-btn icon-btn yellow-btn cover"
                      onClick={() => {
                        setIframeStudentId(action.userId);
                        setIframeStudentName(action.name);
                      }}
                    >
                      <EditOutlined />
                    </Button>
                  </Col>
                  <Col span={8}>
                    <Button
                      title={action.isTravel ? "Rating" : "Only travel players can be rated"}
                      disabled={!action.isTravel}
                      style={{ boxShadow: "none" }}
                      className="beam-btn icon-btn cover"
                      onClick={() =>
                        setRatingUser({
                          userId: action.userId,
                          name: action.name,
                        })
                      }
                    >
                      <StarOutlined />
                    </Button>
                  </Col>
                  <Col span={8}>
                    <Button
                      title="Show Ratings"
                      style={{ boxShadow: "none" }}
                      className="beam-btn icon-btn cover"
                      onClick={() =>
                        setShowRatingsUser({
                          userId: action.userId,
                          name: action.name,
                        })
                      }
                    >
                      <EyeOutlined />
                    </Button>
                  </Col>
                </Row>
              ),
            },
          ];
          const attendanceMap: any = {};
          const classesMap: any = {};
          response?.map((x, i) => {
            if (x?.school?.attendance) {
              attendanceMap[x?.id] = x?.school?.attendance;
            }
            if (x?.school?.classes) {
              classesMap[x?.id] = x?.school?.classes;
            }
            const isTravel = !travelRoleIds.length || travelRoleIds.includes(x?.roleId);
            sourceData.push({
              key: x.id,
              userStatus: x?.status?.name,
              name: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
              email: x?.live?.alternativeIds?.email,
              phone: x?.live?.alternativeIds?.phone,
              customId: x?.live?.alternativeIds?.customId,
              action: {
                userId: x?.id,
                isTravel,
                user: x,
                name: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
              },
            });
          });
          attendanceRef.current = attendanceMap;
          setAttendance(attendanceMap);
          classesByUserRef.current = classesMap;
          setClassesByUser(classesMap);
          students.current = sourceData;
          setPlayerUsers(response || []);
          setTableColumns(columns);
          setTableDataSource(sourceData);
        },
      })
    );
  };

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  // The players' `user:extendedBio` survey configs — the source of the dynamic
  // filters (same shape Programs and the Teams tab read their filters from).
  const fetchFilterConfigs = () => {
    if (!projects?.userServiceId) return;
    const requestData = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:query:bulk`,
          searchQuery: `@type:{project\\:extendedBio}@partitions:{org\\:${formatForRedis(
            projects?.userServiceId
          )}}@objectStatus:{active}`,
        },
        load: {
          objectId: "$.objectId",
          info: "$.info",
          createdAt: "$.info.createdAt",
        },
      },
      sortBy: {
        properties: [{ field: "@createdAt", order: "DESC" }],
        max: 100000,
      },
      result: { pagination: { offset: 0, limit: 1000 } },
    };
    dispatch(
      GET_AGGREGATE({
        requestData,
        callback: (data: any[]) => {
          if (!isMounted.current) return;
          setSurveyConfigs(Array.isArray(data) ? data : []);
        },
      })
    );
  };

  useEffect(() => {
    if (projects?.adminUserId) {
      getUsersByRole(adminUserRoles);
      fetchFilterConfigs();
    }
    // The roles can arrive after the page mounts, so load again when they do.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects, adminUserRoles?.length]);

  const loadingColumns = [
    {
      title: "...",
      dataIndex: "loading",
      key: "loading",
      render: () => (
        <Skeleton
          active
          title={false}
          paragraph={{
            rows: 7,
            width: "100%",
          }}
        />
      ),
    },
  ];

  const loadingData = Array(1)
    .fill({})
    .map((_, index) => ({ key: `loading-${index}` }));

  // Strip the HTML wrapper survey headlines/choices ship with down to text,
  // decoding the common entities (e.g. `&amp;` -> `&`) so labels read cleanly.
  const stripHtml = (value: any) =>
    (value || "")
      .toString()
      .replace(/<[^>]*>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/\s+/g, " ")
      .trim();

  // Distinct answer values across the loaded players for a survey element id,
  // flattening array answers (multi-choice, ranking, contactInfo, address).
  const distinctAnswerValues = (elementId: string) => {
    const set = new Set<any>();
    (playerUsers || []).forEach((u: any) => {
      const answer = u?.extendedBio?.answers?.[elementId];
      if (answer === undefined || answer === null || answer === "") return;
      if (Array.isArray(answer)) {
        answer.forEach((v) => {
          if (v !== undefined && v !== null && v !== "") set.add(v);
        });
      } else if (typeof answer !== "object") {
        set.add(answer);
      }
    });
    return Array.from(set).map((v) => ({ label: `${v}`, value: v }));
  };

  // Dynamic filter definitions, built from the org's `project:extendedBio`
  // survey configs (the same source Programs reads): every `isFilter` widget
  // becomes one dropdown. Gender and Age group are left out here — Gender is a
  // fixed dropdown built below, and Age group was dropped.
  const filterFields = useMemo(() => {
    const seen = new Set<string>();
    const fields: any[] = [];

    (surveyConfigs || []).forEach((survey: any) => {
      const blocks = survey?.info?.data?.blocks || [];
      blocks.forEach((block: any) => {
        (block?.elements || []).forEach((el: any) => {
          if (!el?.isFilter || !el?.id || seen.has(el.id)) return;

          const label = stripHtml(el?.headline?.default) || el.id;
          // Gender is a fixed dropdown; Age group and Subtype were removed.
          if (
            /gender/i.test(label) ||
            /\bage\b/i.test(label) ||
            /subtype/i.test(label)
          )
            return;
          seen.add(el.id);

          let options: { label: string; value: any }[] = [];

          if (
            el.type === "multipleChoiceSingle" ||
            el.type === "multipleChoiceMulti" ||
            el.type === "ranking" ||
            el.type === "pictureSelection"
          ) {
            options = (el.choices || []).map((c: any) => ({
              label: stripHtml(c?.label?.default),
              value: stripHtml(c?.label?.default),
            }));
          } else if (el.type === "rating") {
            options = Array.from({ length: el?.range || 5 }, (_, i) => ({
              label: `${i + 1}`,
              value: i + 1,
            }));
          } else if (el.type === "nps") {
            options = Array.from({ length: 11 }, (_, i) => ({
              label: `${i}`,
              value: i,
            }));
          } else if (el.type === "matrix" || el.type === "selectUsers") {
            // Object-valued answers don't map to a single dropdown; skip.
            return;
          } else {
            options = distinctAnswerValues(el.id);
          }

          fields.push({ id: el.id, label, kind: "value", options });
        });
      });
    });

    // Gender is a standard profile field (live.profile.gender), not a survey
    // answer, so it's a fixed dropdown shown first. Stored values are lowercase
    // ("female"), so options carry the lowercase value and matching is
    // case-insensitive.
    const special = [
      {
        id: "__gender",
        label: "Gender",
        kind: "gender",
        options: [
          { label: "Male", value: "male" },
          { label: "Female", value: "female" },
          { label: "Coed", value: "coed" },
        ],
      },
    ];

    return [...special, ...fields];
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [surveyConfigs, playerUsers]);

  // Filters that currently have a value selected (drives the clear button).
  const activeFilters = useMemo(
    () =>
      filterFields.filter(
        (f: any) =>
          filterValues[f.id] !== undefined &&
          filterValues[f.id] !== null &&
          filterValues[f.id] !== ""
      ),
    [filterFields, filterValues]
  );

  // Derive per-row attendance/class values so each row gets a NEW reference when
  // these change. rc-table memoises rows by record reference, so without this the
  // cells wouldn't re-render on update or when the attendance date changes.
  const tableData = useMemo(() => {
    const dateKey = attendanceDate?.format("YYYY-MM-DD");
    const needle = familySearch.trim().toLowerCase();
    return (allRows || [])
      .filter((row: any) => {
        const fam: KidRow | undefined = row?.action?.family;
        // Kids are filtered here (the server query only lists users): by the
        // search text, which also matches the parent, and by the Team dropdown,
        // which is the kid's own Recreational / Travelling role.
        if (fam) {
          if (needle) {
            const hay = [
              row.name,
              row.email,
              row.customId,
              fam.kid.beamId,
              ...fam.parents.flatMap((p) => [p.name, p.email]),
            ]
              .filter(Boolean)
              .join(" ")
              .toLowerCase();
            if (!hay.includes(needle)) return false;
          }
          if (teamFilter && fam.kid.roleId !== teamFilter) return false;
        }
        // A coach sees only players on their own teams and pages. A kid is on a
        // page through their parent: the page lists the kid's beamId on the parent.
        if (scoped) {
          const uid = `${row?.action?.userId}`;
          const inScope = fam
            ? kidInCoachScope(fam, scopeMemberIds, scopeMemberBeamIds)
            : !!scopeMemberIds?.includes(uid);
          if (!inScope) return false;
        }
        // Pages filter: every player stays listed; the Overall rating column
        // shows each one's score on the page (0 when no coach rated them).
        // Team filter: only players who belong to the selected team.
        if (classFilter) {
          const onTeam =
            !!teamMemberIds &&
            (teamMemberIds.includes(`${row?.action?.userId}`) ||
              (!!fam && fam.parents.some((p) => teamMemberIds.includes(p.id))));
          if (!onTeam) return false;
        }
        // Dynamic extendedBio filters: a row matches when its answer equals the
        // selected value (array answers match when any item does; objects by id).
        const answers = row?.action?.user?.extendedBio?.answers || {};
        const profile = row?.action?.user?.live?.profile || {};
        // Date-of-birth range (month granularity): keep players whose doB falls
        // within the selected MM-YYYY range.
        if (dobRange && (dobRange[0] || dobRange[1])) {
          const dob = profile.doB ?? profile.dob;
          const m = dob ? moment(dob) : null;
          if (!m || !m.isValid()) return false;
          if (dobRange[0] && m.isBefore(moment(dobRange[0]).startOf("month"))) return false;
          if (dobRange[1] && m.isAfter(moment(dobRange[1]).endOf("month"))) return false;
        }
        for (const f of activeFilters) {
          const value = filterValues[f.id];
          // Gender and Age group read the player profile, not the survey answers.
          if (f.kind === "gender") {
            if (`${profile.gender ?? ""}`.trim().toLowerCase() !== `${value}`.toLowerCase())
              return false;
            continue;
          }
          const answer = answers[f.id];
          if (Array.isArray(answer)) {
            const ok = answer.some((a: any) =>
              a && typeof a === "object"
                ? `${a.id}` === `${value}`
                : `${a}` === `${value}`
            );
            if (!ok) return false;
          } else if (`${answer}` !== `${value}`) {
            return false;
          }
        }
        return true;
      })
      .map((row: any, index: number) => {
        const userId = row?.action?.userId;
        return {
          ...row,
          no: index + 1,
          attendanceStatus: attendance?.[userId]?.[dateKey]?.status,
          classes: classesByUser?.[userId] || [],
          savingAttendance: savingAttendanceId === userId,
          savingClasses: savingClassesId === userId,
          rating: ratings?.[`${userId}`],
        };
      });
  }, [
    allRows,
    familySearch,
    teamFilter,
    scopeMemberBeamIds,
    attendance,
    classesByUser,
    attendanceDate,
    savingAttendanceId,
    savingClassesId,
    classFilter,
    teamMemberIds,
    scoped,
    scopeMemberIds,
    activeFilters,
    filterValues,
    dobRange,
    ratedUserIds,
    ratings,
  ]);

  // The Rating column only exists while a page is selected, placed before Action.
  const displayColumns = useMemo(() => {
    if (!ratedUserIds) return tableColumns;
    const ratingColumn = {
      title: "Overall rating",
      key: "rating",
      dataIndex: "rating",
      // Highest total first; unrated players count as 0.
      defaultSortOrder: "descend" as const,
      sorter: (a: any, b: any) =>
        (a?.rating?.value ?? 0) - (b?.rating?.value ?? 0),
      render: (rating?: PlayerRating) =>
        rating ? (
          <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
            <Rate
              disabled
              allowHalf
              count={rating.range}
              value={rating.value}
              style={{ fontSize: 14 }}
            />
            <span>
              {rating.value}/{rating.range}
            </span>
          </span>
        ) : (
          <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
            <Rate disabled count={5} value={0} style={{ fontSize: 14 }} />
            <span>0/5</span>
          </span>
        ),
    };
    const cols = [...(tableColumns || [])];
    const actionAt = cols.findIndex((c: any) => c?.key === "action");
    cols.splice(actionAt >= 0 ? actionAt : cols.length, 0, ratingColumn);
    return cols;
  }, [tableColumns, ratedUserIds]);

  // Diagnostics for a coach's view: who was loaded, who is in scope, who is kept.
  useEffect(() => {
    if (!scoped) return;
    console.log("[Players] coach view", {
      teams: classOptions.map((t) => t.label),
      scopeMemberIds,
      playersLoaded: (allRows || []).map((r: any) => r?.action?.userId),
      shown: tableData.map((r: any) => r?.action?.userId),
    });
  }, [scoped, classOptions, scopeMemberIds, allRows, tableData]);

  // Picking a team: read its members, then the table narrows to those players.
  const onTeamFilterChange = (teamId?: string) => {
    setClassFilter(teamId);
    setTeamMemberIds(undefined);
    if (!teamId) {
      setTeamMembersLoading(false);
      return;
    }
    const team = classOptions.find((t) => t.value === teamId);
    if (!team) return;
    setTeamMembersLoading(true);
    fetchTeamMemberIds(team).then((ids) => {
      // Ignore a slow reply for a team that is no longer selected.
      if (!isMounted.current || classFilterRef.current !== teamId) return;
      console.log("[Players] filter selection", {
        filter: "Team",
        value: teamId,
        team: team.label,
        memberIds: ids,
      });
      setTeamMemberIds(ids);
      setTeamMembersLoading(false);
    });
  };

  // Picking a page: fetch the survey responses stored on it. When the org has
  // rating surveys, only those count; otherwise every survey entry on the page.
  const onPageFilterChange = (pageId?: string) => {
    setPageFilter(pageId);
    pageFilterRef.current = pageId;
    if (!pageId) {
      setRatedUserIds(undefined);
      setRatings(undefined);
      return;
    }
    setRatedLoading(true);
    const ratingSurveyIds = surveyOptions
      .filter((s) => /rating/i.test(s.label))
      .map((s) => s.value);
    fetchRatedUserIds(dispatch, projects?.userServiceId, pageId, ratingSurveyIds).then(
      ({ userIds, surveyIds, ratings: scores }) => {
        // Ignore a slow reply for a page that is no longer selected.
        if (!isMounted.current || pageFilterRef.current !== pageId) return;
        console.log("[Players] filter selection", {
          filter: "Page",
          value: pageId,
          surveyIds,
          ratedUserIds: userIds,
          ratings: scores,
        });
        setRatedUserIds(userIds);
        setRatings(scores);
        setRatedLoading(false);
      }
    );
  };

  // The selected rows. A kid is listed as a player, but a parent is the user, so
  // the group and the page get the parent (once, however many of their kids are
  // selected) with the kids' beamIds attached.
  const selectedRows = useMemo(() => {
    const byKey: Record<string, any> = {};
    (allRows || []).forEach((row: any) => {
      byKey[`${row.key}`] = row;
    });
    return selectedKeys.map((k) => byKey[`${k}`]).filter(Boolean);
  }, [selectedKeys, allRows]);

  const usersOfRows = (rows: any[]): GroupUser[] => {
    const own: GroupUser[] = rows
      .filter((row) => !row?.action?.family)
      .map((row) => ({ id: `${row.key}`, beamId: row?.action?.user?.live?.beamIds?.[0] }));
    const parents: GroupUser[] = familyMembers(
      rows.filter((row) => row?.action?.family).map((row) => row.action.family as KidRow)
    ).map((m) => ({ id: m.id, beamId: m.beamId, associatedBeamIds: m.associatedBeamIds }));
    return [...own, ...parents];
  };

  const selectedUsers: GroupUser[] = useMemo(() => usersOfRows(selectedRows), [selectedRows]); // eslint-disable-line react-hooks/exhaustive-deps

  // Assign coaches applies to the selected travel players only.
  const travelSelectedRows = useMemo(
    () => selectedRows.filter((row: any) => !!row?.action?.isTravel),
    [selectedRows]
  );
  const travelSelectedUsers: GroupUser[] = useMemo(() => usersOfRows(travelSelectedRows), [travelSelectedRows]); // eslint-disable-line react-hooks/exhaustive-deps

  // id -> name for labelling users in the group and page popups; a parent reads
  // "Parent (kids: kid, kid)" for the kids selected with them.
  const usersById = useMemo(() => {
    const map: Record<string, string> = {};
    (allRows || []).forEach((row: any) => {
      if (row?.action?.family) {
        row.action.family.parents.forEach((p: any) => {
          map[p.id] = p.name;
        });
      } else {
        map[`${row.key}`] = row?.name || `#${row.key}`;
      }
    });
    const kidsOfParent: Record<string, string[]> = {};
    selectedRows.forEach((row: any) => {
      (row?.action?.family?.parents || []).forEach((p: any) => {
        (kidsOfParent[p.id] = kidsOfParent[p.id] || []).push(row.name);
      });
    });
    Object.keys(kidsOfParent).forEach((id) => {
      map[id] = `${map[id]} (kids: ${kidsOfParent[id].join(", ")})`;
    });
    return map;
  }, [allRows, selectedRows]);

  if (iframeStudentId !== undefined || configureMode) {
    const iframeUrl = configureMode
      ? selectedRole?.extendedBioId ? `https://cpc.staging.beam.live/admin/extendedBio/${selectedRole?.extendedBioId}/edit?serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}` : `https://cpc.staging.beam.live/admin/extendedBio/new?t=user&serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}&roleId=${selectedRole?._id}`
      : selectedRole?.extendedBioId ? `https://cpc.staging.beam.live/eb/${selectedRole?.extendedBioId}?serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}&userId=${iframeStudentId}` : undefined;
    return (
      <React.Fragment>
        <Row>
          <Col span={24} className="d-flex justify-content-start">
            <Button
              style={{ boxShadow: "none" }}
              className="beam-btn icon-btn cover mr-2"
              onClick={() => {
                setIframeStudentId(undefined);
                setConfigureMode(false);
              }}
            >
              <ArrowLeftOutlined />
            </Button>
            <div>
              <h2 style={{ marginBottom: 0 }}>
                {configureMode ? "" : iframeStudentName}
              </h2>
            </div>
          </Col>
        </Row>
        <Row className="mt-3">
          <Col span={24}>
            <iframe
              title="student-detail"
              src={iframeUrl}
              style={{ width: "100%", height: "100vh", border: "none" }}
            />
          </Col>
        </Row>
      </React.Fragment>
    );
  }

  return (
    <React.Fragment>
      <Row>
        <Col span={24}>
          <div>
            <h2 style={{ marginBottom: 4 }}>Players</h2>
            <p style={{ marginBottom: 0, color: "#8c8c8c" }}>Home &gt; Players</p>
          </div>
        </Col>
      </Row>

      <Row className="mt-3">
        <Col
          span={24}
          style={{
            display: "flex",
            flexDirection: isMobile ? "column" : "row",
            flexWrap: "wrap",
            alignItems: isMobile ? "stretch" : "flex-end",
            gap: 10,
            width: "100%",
          }}
        >
            <Input
              allowClear
              onChange={(e) => {
                let value: string = e.target.value;
                if (timeout) clearTimeout(timeout);
                setFamilySearch(value);
                timeout = setTimeout(() => {
                  if (value.includes("-")) value = formatForRedis(value);
                  getUsersByRole(adminUserRoles, value);
                }, 500);
              }}
              style={{ width: isMobile ? "100%" : 240, flexShrink: 0 }}
              placeholder="Search by name"
              prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
            />
            <Select
              allowClear
              placeholder="Recreational / Travel"
              options={playerTeamOptions}
              value={teamFilter}
              onChange={(value) => {
                console.log("[Players] filter selection", {
                  filter: "Recreational / Travel",
                  value,
                });
                teamFilterRef.current = value;
                setTeamFilter(value);
                getUsersByRole(adminUserRoles);
              }}
              style={{ width: isMobile ? "100%" : 200, flexShrink: 0 }}
            />
            <Select
              allowClear
              showSearch
              placeholder="Team"
              loading={teamsLoading || teamMembersLoading}
              options={classOptions}
              value={classFilter}
              onChange={(value) => {
                classFilterRef.current = value;
                onTeamFilterChange(value);
              }}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
              style={{ width: isMobile ? "100%" : 200, flexShrink: 0 }}
            />
            <Select
              allowClear
              showSearch
              placeholder="Page (rated)"
              loading={pagesLoading || ratedLoading}
              options={pageOptions}
              value={pageFilter}
              onChange={(value) => onPageFilterChange(value)}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
              style={{ width: isMobile ? "100%" : 200, flexShrink: 0 }}
              notFoundContent={pagesLoading ? "Loading..." : "No pages found"}
            />
            {ratedUserIds && (
              <span
                style={{
                  alignSelf: "center",
                  fontSize: 12,
                  color: "#8c8c8c",
                  whiteSpace: "nowrap",
                }}
              >
                {ratedUserIds.length} rated on this page
              </span>
            )}
            {filterFields.map((f: any) => (
              <div
                key={f.id}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 4,
                  width: isMobile ? "100%" : 180,
                  flexShrink: 0,
                }}
              >
                <span
                  title={f.label}
                  style={{
                    fontSize: 12,
                    color: "#8c8c8c",
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  {f.label}
                </span>
                <Select
                  allowClear
                  showSearch
                  placeholder="All"
                  options={f.options}
                  value={filterValues[f.id]}
                  onChange={(value) => {
                    console.log("[Players] filter selection", {
                      filter: f.label,
                      id: f.id,
                      value,
                    });
                    setFilterValues((prev) => ({ ...prev, [f.id]: value }));
                  }}
                  filterOption={(input, option) =>
                    (option?.label ?? "")
                      .toString()
                      .toLowerCase()
                      .includes(input.toLowerCase())
                  }
                  style={{ width: "100%" }}
                />
              </div>
            ))}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 4,
                width: isMobile ? "100%" : 240,
                flexShrink: 0,
              }}
            >
              <span style={{ fontSize: 12, color: "#8c8c8c" }}>Date of birth</span>
              <DatePicker.RangePicker
                picker="month"
                format="MM-YYYY"
                value={dobRange as any}
                onChange={(vals) => setDobRange(vals as any)}
                style={{ width: "100%" }}
              />
            </div>
            {activeFilters.length > 0 && (
              <Button
                type="link"
                onClick={() => setFilterValues({})}
                style={{ flexShrink: 0, paddingLeft: 0 }}
              >
                Clear filters
              </Button>
            )}
            <DatePicker
              allowClear={false}
              value={attendanceDate}
              onChange={handleAttendanceDateChange}
              format="YYYY-MM-DD"
              disabledDate={(current) =>
                current && current > moment().endOf("day")
              }
              style={{ width: isMobile ? "100%" : 150, flexShrink: 0 }}
            />
            {userRole === "admin" && (
              <Button
                className="beam-btn configure-btn"
                icon={<SettingOutlined />}
                onClick={() => setConfigureMode(true)}
                style={{ flexShrink: 0, width: isMobile ? "100%" : "auto" }}
              >

              </Button>
            )}
        </Col>
      </Row>

      {selectedKeys.length > 0 && (
        <Row className="mt-3">
          <Col span={24} style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <span style={{ color: "#595959" }}>{selectedKeys.length} selected</span>
            <Button
              type="primary"
              className="beam-btn"
              onClick={() => setGroupModalOpen(true)}
            >
              Add to Group
            </Button>
            {!scoped && (
              <Button
                className="beam-btn"
                disabled={travelSelectedRows.length === 0}
                title={
                  travelSelectedRows.length === 0
                    ? "Select travel players to assign coaches"
                    : undefined
                }
                onClick={() => setCoachesModalOpen(true)}
              >
                Assign coaches ({distinctKidCount(travelSelectedRows)})
              </Button>
            )}
          </Col>
        </Row>
      )}

      <Row
        gutter={20}
        className="scrollable-table mt-3"
        style={{ display: "grid", marginRight: -20 }}
      >
        <Col xs={24} sm={24} md={24} style={{ maxHeight: 1000, overflow: "scroll" }}>
          <Table
            dataSource={loading ? loadingData : tableData}
            columns={loading ? loadingColumns : displayColumns}
            scroll={{ x: true }}
            onChange={(e) => { }}
            rowKey="key"
            rowSelection={
              loading
                ? undefined
                : {
                    selectedRowKeys: selectedKeys,
                    onChange: (keys) => setSelectedKeys(keys),
                  }
            }
            rowClassName={(record, index) => {
              if (record?.key === selectedPage?.page?.pageId) return "row-selected";
              return "";
            }}
          />
        </Col>
      </Row>

      <AddToGroupModal
        open={groupModalOpen}
        users={selectedUsers}
        usersById={usersById}
        serviceId={projects?.userServiceId}
        adminUserId={projects?.adminUserId}
        connectionId={encrypted_token?.connectionId}
        socket={socket}
        onClose={() => setGroupModalOpen(false)}
        onAdded={() => setSelectedKeys([])}
      />

      <AssignCoachesModal
        open={coachesModalOpen}
        users={travelSelectedUsers}
        usersById={usersById}
        playerCount={distinctKidCount(travelSelectedRows)}
        serviceId={projects?.userServiceId}
        connectionId={encrypted_token?.connectionId}
        socket={socket}
        onClose={() => setCoachesModalOpen(false)}
        onCreated={() => setSelectedKeys([])}
      />

      <ShowRatingsModal
        open={showRatingsUser !== undefined}
        user={showRatingsUser}
        serviceId={projects?.userServiceId}
        pages={pageOptions}
        initialPageId={pageFilter}
        ratingSurveyIds={surveyOptions.filter((s) => /rating/i.test(s.label)).map((s) => s.value)}
        onClose={() => setShowRatingsUser(undefined)}
      />

      <RatingModal
        open={ratingUser !== undefined}
        user={ratingUser}
        onClose={() => setRatingUser(undefined)}
      />
    </React.Fragment>
  );
};

export default StudentsModal;
