import React, { useEffect } from "react";
import { Row, Col, Checkbox } from "antd";
import RenderFields from "../RenderFields";

const getConditionalSection = (allSections, section, index) => {
  if (section?.[index]) {
    const conditionalSection = allSections?.find((x) => {
      return x.sectionName === section?.[index];
    });
    return conditionalSection;
  }
};

/**
 * The option an entry of a multi-select value stands for. Entries come in
 * three shapes: a plain string (a saved value loaded back into the form),
 * `{ option: "A" }`, and `{ option: ["A"] }` (what a fresh tick stores).
 */
const entryOption = (entry: any) => {
  if (typeof entry === "string") return entry;
  return Array.isArray(entry?.option) ? entry.option[0] : entry?.option;
};

const entryMatches = (entry: any, option: any) =>
  entry === option ||
  entry?.option === option ||
  (Array.isArray(entry?.option) && entry.option.includes(option));

/** Keep the first entry per option — older saves repeated options. */
const dedupeEntries = (entries: any[]) => {
  const seen = new Set();
  return entries.filter((entry) => {
    const key = entryOption(entry);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const MultipleChoiceInput: React.FC<any> = ({
  value = undefined,
  placeholder,
  isMulti,
  options,
  onChange,
  conditionalSections,
  fieldSections,
  projects,
  addOtherLocation,
  onProjectChange,
  onCustomerSearch,
  adminRoles,
  customerDisabled,
  dispatchDisabled,
  socket
  // conditionalParentName,
}) => {
  const renderConditionalSection = (option) => {
    const tindex = Array.isArray(value) ? value.findIndex((x) => {
      return x?.option === option;
    }) : -1;

    if (value?.[tindex]?.conditional) {
      return (
        <React.Fragment>
          <br />
          {value?.[tindex]?.conditional?.Rows.map((row, j) => (
            <Row className={j > 0 ? "mt-3 w-100" : "w-100"} key={j}>
              <React.Fragment>
                {!row.isMulti &&
                  row?.Cols.map((col, k) => (
                    <Col
                      span={col.ColSize}
                      className=""
                      xs={24}
                      sm={col.ColSize}
                      key={k}
                    >
                      <RenderFields
                        data={col}
                        projects={projects}
                        addOtherLocation={addOtherLocation}
                        onProjectChange={onProjectChange}
                        onCustomerSearch={onCustomerSearch}
                        adminRoles={adminRoles}
                        customerDisabled={customerDisabled}
                        dispatchDisabled={dispatchDisabled}
                        conditionalSections={conditionalSections}
                        conditionalParentName={value?.[tindex]?.timestamp}
                        socket={socket}
                      />
                    </Col>
                  ))}
              </React.Fragment>
            </Row>
          ))}
          <br />
        </React.Fragment>
      );
    } else {
      return <React.Fragment />;
    }
  };


  return (
    <React.Fragment>
      <span className="col-label">{placeholder}</span>
      <div className="tiles padding-12">
        <Row className="w-100">
          <Col span={24}>
            {isMulti ? (
              <div className="d-flex flex-column align-items-start">
                {options.map((option, index) => (
                  <React.Fragment>
                    <Checkbox
                      className="mb-2 ml-0"
                      checked={
                        Array.isArray(value) &&
                        value.some((x) => entryMatches(x, option))
                      }
                      name={option}
                      key={option}
                      onChange={() => {
                        const current = Array.isArray(value) ? value : [];
                        // Matched the same way `checked` is. Matching only
                        // `x.option === option` never found the entry (it is
                        // stored as `["A"]`, or as "A" once loaded), so
                        // unticking appended a duplicate instead.
                        const isChecked = current.some((x) =>
                          entryMatches(x, option)
                        );
                        const next = isChecked
                          ? current.filter((x) => !entryMatches(x, option))
                          : [
                            ...current,
                            {
                              option: Array.isArray(option) ? option : [option],
                              conditional: getConditionalSection(
                                conditionalSections,
                                fieldSections,
                                index
                              ),
                              timestamp: new Date().getTime().toString(),
                            },
                          ];
                        onChange(dedupeEntries(next));
                      }}
                    >
                      {option}
                    </Checkbox>
                    {renderConditionalSection(option)}
                  </React.Fragment>
                ))}
              </div>
            ) : (
              <React.Fragment>
                {options.map((option, index) => (
                  <Checkbox
                    className="mb-2 ml-0"
                    checked={option === value?.option || option === value}
                    name={option}
                    key={option}
                    onChange={(e) => {
                      // Clicking the selected option again unselects it.
                      if (!e.target.checked) {
                        onChange(undefined);
                        return;
                      }
                      let conditional;
                      if (fieldSections?.[index]) {
                        const conditionalSection = conditionalSections?.find(
                          (x) => {
                            return x.sectionName === fieldSections?.[index];
                          }
                        );
                        conditional = conditionalSection;
                      } else {
                        conditional = undefined;
                      }
                      onChange({
                        option,
                        conditional,
                        timestamp: new Date().getTime().toString(),
                      });
                    }}
                  >
                    {option}
                  </Checkbox>
                ))}
                {value?.conditional && (
                  <React.Fragment>
                    <br />
                    {value?.conditional?.Rows.map((row, j) => (
                      <Row className={j > 0 ? "mt-3" : ""} key={j}>
                        <React.Fragment>
                          {!row.isMulti &&
                            row?.Cols.map((col, k) => (
                              <Col
                                span={col.ColSize}
                                className=""
                                xs={24}
                                sm={col.ColSize}
                                key={k}
                              >
                                <RenderFields
                                  data={col}
                                  projects={projects}
                                  addOtherLocation={addOtherLocation}
                                  onProjectChange={onProjectChange}
                                  onCustomerSearch={onCustomerSearch}
                                  adminRoles={adminRoles}
                                  customerDisabled={customerDisabled}
                                  dispatchDisabled={dispatchDisabled}
                                  conditionalSections={conditionalSections}
                                  conditionalParentName={value?.timestamp}
                                  socket={socket}
                                />
                              </Col>
                            ))}
                        </React.Fragment>
                      </Row>
                    ))}
                  </React.Fragment>
                )}
              </React.Fragment>
            )}
          </Col>
        </Row>
      </div>
    </React.Fragment>
  );
};

export default MultipleChoiceInput;
