import { useMemo } from "react";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";

import { StripeIdentity } from "./stripeTypes";

/** What the Payment modals hardcode when the token names no cudb. */
const DEFAULT_CUDB_SERVICE_ID = "cudb-live";

/**
 * Who the Stripe workflow runs as: the user behind the link's encrypted
 * `?token=`, which `CFODashboardWrapper` decrypts into redux
 * `encrypted_token`. Null until that lands (or when the link carries no
 * token), and the Stripe screens then make no request. Raw identity
 * parameters on the URL are ignored.
 */
export const useStripeIdentity = (): StripeIdentity | null => {
  const { encrypted_token } = useSelector((state: RootState) => state.auth) as any;

  return useMemo(() => {
    const userId = encrypted_token?.userId;
    if (!userId) return null;
    const cudbServiceId = encrypted_token?.cudbServiceId || encrypted_token?.serviceId || DEFAULT_CUDB_SERVICE_ID;
    return { userId: String(userId), cudbServiceId: String(cudbServiceId) };
  }, [encrypted_token]);
};
