/**
 * Directory — the organisation's roles, projects, users, groups and
 * events, read the way api-admin-core reads them.
 *
 * Each function reproduces one admin service read against the same BDS
 * API and the same JSON paths:
 *
 * - roles and projects: what `role.service` (`$..persistent.static.admin.role`)
 *   and `project.service` (`/persistent/static/admin/project/items`) read
 *   from the organisation's config user;
 * - users by role: `live-user.service.getUsersByPermissionsV2`'s aggregate
 *   on the `user:role` index, by role id, plus `stripeCustomerId`;
 * - groups: `group.service.getAll`'s aggregate on `query:bulk` and
 *   `getkeys` for each group's members;
 * - events: the organisation's event pages (the School3 calendar read;
 *   no admin service lists them with dates).
 */
import { formatForRedis } from "utils/appUtil";
import { FamilyRow, fetchFamilyRowsWith } from "../../../School3/Dashboard/Student/familyRows";

import { ECOSYSTEM, aggregateRows, bdsPost, escapeRedis, userIdsFromGroupKeys } from "./bds";

export interface OrgContext {
  /** The organisation's cudb service id, from the token. */
  serviceId: string;
  connectionId: string;
}

export type DirectoryResult<T> = { ok: true; data: T } | { ok: false; error: string };

const fail = (e: any, fallback: string): DirectoryResult<never> => ({
  ok: false,
  error: typeof e === "string" ? e : e?.message || fallback,
});

/* ------------------------------------------------------------------ */
/* Roles and projects (the config user's admin branch)                 */
/* ------------------------------------------------------------------ */

export interface RawRole {
  _id: string;
  name: string;
  permissions?: string[];
  /** Dashboards the role may open (admin console > Roles > Dashboards). */
  dashboards?: any;
  /** The role's older single sidebar list. */
  sidebarModules?: number[];
}

/** One project as stored under `admin.project.items`. */
export interface RawProject {
  _id: string;
  name?: string;
  customId?: string;
  type?: string | null;
  status?: string;
  startDate?: string | number | null;
  endDate?: string | number | null;
  liveUserIds?: (string | number)[];
  managerLiveUserIds?: (string | number)[];
  memberGroupId?: string | null;
  paymentConfigId?: string | null;
  payment?: { type?: string; info?: { name?: string; amount?: number; recurringDetails?: unknown } } | null;
}

export interface OrgAdminData {
  /** The users carrying a role list - the org's config user(s). */
  adminUserIds: string[];
  roles: RawRole[];
  projects: RawProject[];
}

/**
 * The organisation's roles and projects. The admin services read them
 * from the org's config user (`cudbConfig.userId`), which the browser
 * does not know; one aggregate over the cudb keeping the records that
 * carry `persistent.static.admin.role` finds it. A root cudb holds one
 * such record per org admin, so the lists are merged.
 */
export const fetchOrgAdmin = async (context: OrgContext): Promise<DirectoryResult<OrgAdminData>> => {
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:userNameIndex`,
        searchQuery: `@serviceId:{'${formatForRedis(context.serviceId)}'}`,
        searchOptions: "TIMEOUT 5000",
      },
      list: { objectIds: undefined },
      load: {
        id: "$.objectId",
        roles: "$.persistent.static.admin.role",
        projectItems: "$.persistent.static.admin.project.items",
      },
    },
    apply: { expression: "", name: "" },
    result: {},
    filter: { expression: "exists(@roles)" },
    anyStatus: true,
  };
  try {
    const reply = await bdsPost("aggregateBds", request, context.connectionId);
    const rows = aggregateRows(reply);
    if (!rows) return fail(reply?.message || reply, "The organisation search returned no list");
    const holders = rows.filter((row: any) => Array.isArray(row?.roles) && row.roles.length > 0);
    const roles = new Map<string, RawRole>();
    const projects = new Map<string, RawProject>();
    holders.forEach((holder: any) => {
      holder.roles.forEach((role: any) => {
        if (!role || role._id === undefined) return;
        roles.set(String(role._id), {
          _id: String(role._id),
          name: String(role.name || ""),
          permissions: Array.isArray(role.permissions) ? role.permissions : [],
          dashboards: role.dashboards,
          sidebarModules: Array.isArray(role.sidebarModules) ? role.sidebarModules : [],
        });
      });
      Object.values(holder.projectItems || {}).forEach((item: any) => {
        if (item && item._id) projects.set(String(item._id), { ...item, _id: String(item._id) });
      });
    });
    return {
      ok: true,
      data: {
        adminUserIds: holders.map((holder: any) => String(holder.id)),
        roles: Array.from(roles.values()),
        projects: Array.from(projects.values()),
      },
    };
  } catch (e: any) {
    return fail(e, "The organisation search failed");
  }
};

/**
 * The organisation's parents and their kids, one row per parent and kid. Only
 * parents are users; each lists its kids (non-beamer records) in `family`.
 * Read over the same transport as the other Directory calls.
 */
export const fetchFamilies = async (context: OrgContext): Promise<DirectoryResult<FamilyRow[]>> => {
  try {
    const run = async (request: any): Promise<any[]> => {
      const reply = await bdsPost("aggregateBds", request, context.connectionId);
      const rows = aggregateRows(reply);
      if (!rows) throw new Error(reply?.message || "The family search returned no list");
      return rows;
    };
    return { ok: true, data: await fetchFamilyRowsWith(run, context.serviceId) };
  } catch (e: any) {
    return fail(e, "The family search failed");
  }
};

/**
 * The role id of one user (the signed-in one), read the same way the role
 * list is: an aggregate on the org's user index, listed by object id.
 */
export const fetchUserRoleId = async (
  context: OrgContext,
  userId: string
): Promise<DirectoryResult<string | null>> => {
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:userNameIndex`,
        searchQuery: `@serviceId:{'${formatForRedis(context.serviceId)}'}`,
        searchOptions: "TIMEOUT 5000",
      },
      list: { objectIds: [userId] },
      load: { id: "$.objectId", roleId: "$..admin.profile.roleId" },
    },
    apply: { expression: "", name: "" },
    result: {},
    filter: { expression: "exists(@roleId)" },
    anyStatus: true,
  };
  try {
    const reply = await bdsPost("aggregateBds", request, context.connectionId);
    const rows = aggregateRows(reply);
    if (!rows) return fail(reply?.message || reply, "The user role search returned no list");
    const row = rows.find((r: any) => String(r?.id) === String(userId)) || rows[0];
    const roleId = row && row.roleId !== undefined && row.roleId !== null ? String(row.roleId) : null;
    return { ok: true, data: roleId };
  } catch (e: any) {
    return fail(e, "The user role search failed");
  }
};

/* ------------------------------------------------------------------ */
/* Users by role                                                       */
/* ------------------------------------------------------------------ */

/** The admin listing shape (`_transformPopulatedLiveUsersForListing`) plus the Stripe customer id. */
export interface RawUser {
  _id: string | number;
  status?: string | null;
  isBlocked?: boolean;
  email?: string;
  phoneNumber?: string;
  customId?: string;
  roleId?: string | number | null;
  beamId?: string;
  firstName?: string;
  middleName?: string;
  lastName?: string;
  department?: string;
  stripeCustomerId?: string | null;
}

/** Port of the listing transform, reading `static` = `persistent.static`. */
const toListing = (liveUser: any): RawUser => {
  const liveUserObj = liveUser?.static;
  const firstName = liveUserObj?.live?.profile?.firstName || "";
  const lastName = liveUserObj?.live?.profile?.lastName || "";
  const beamIds = liveUserObj?.live?.beamIds;
  return {
    _id: liveUser?.objectId,
    status: liveUser?.status || null,
    isBlocked: liveUser?.isBlocked || false,
    email: liveUserObj?.live?.alternativeIds?.email,
    phoneNumber: liveUserObj?.live?.alternativeIds?.phone,
    customId: liveUserObj?.live?.alternativeIds?.customId,
    roleId: liveUserObj?.admin?.profile?.roleId,
    beamId: Array.isArray(beamIds) ? (beamIds.length ? beamIds[0] : `${firstName}.${lastName}`) : beamIds || `${firstName}.${lastName}`,
    firstName,
    middleName: liveUserObj?.live?.profile?.middleName,
    lastName,
    department: liveUserObj?.live?.profile?.department,
    stripeCustomerId:
      liveUserObj?.live?.alternativeIds?.stripeCustomerId || liveUserObj?.stripe?.customerId || null,
  };
};

/** `getUsersByPermissionsV2`'s aggregate, by role id: every user whose role is one of `roleIds`. */
export const fetchUsersByRoleIds = async (
  context: OrgContext,
  roleIds: string[]
): Promise<DirectoryResult<RawUser[]>> => {
  const ids = roleIds.filter((id) => id && id.trim() !== "").map((id) => escapeRedis(id.trim()));
  if (ids.length === 0) return { ok: true, data: [] };
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:user:role`,
        searchQuery: `@userType:{user}@profileRole:{${ids.join("|")}}@serviceId:{${escapeRedis(context.serviceId)}}`,
      },
      load: {
        objectId: "$.objectId",
        roleId: "$..persistent.static.admin.profile.roleId",
        status: "$.nonpersistent.static.live.status.name",
        isBlocked: "$.nonpersistent.static.live.isBlocked",
        static: "$.persistent.static",
      },
    },
    result: { pagination: { offset: 0, limit: 1000 } },
  };
  try {
    const reply = await bdsPost("aggregateBds", request, context.connectionId);
    const rows = aggregateRows(reply);
    if (!rows) return fail(reply?.message || reply, "The user search returned no list");
    return { ok: true, data: rows.map(toListing) };
  } catch (e: any) {
    return fail(e, "The user search failed");
  }
};

/* ------------------------------------------------------------------ */
/* Groups                                                              */
/* ------------------------------------------------------------------ */

/** One group as `group.service.getAll` shapes it; members carry ids only. */
export interface RawGroup {
  _id: string;
  name: string;
  /** static | dynamic | nonbeamer | organization */
  type?: string;
  pageId?: string | null;
  members?: { _id: string }[];
  reportingToGroupId?: string | null;
  collaboratingWithGroupIds?: string[];
}

/** Resolves `limit` promises at a time, in order. */
const inBatches = async <T, R>(items: T[], limit: number, run: (item: T) => Promise<R>): Promise<R[]> => {
  const results: R[] = [];
  for (let i = 0; i < items.length; i += limit) {
    const batch = await Promise.all(items.slice(i, i + limit).map(run));
    results.push(...batch);
  }
  return results;
};

/** `group.service.getAll`: the organisation's groups, then `getkeys` for each one's member ids. */
export const fetchGroups = async (context: OrgContext): Promise<DirectoryResult<RawGroup[]>> => {
  const cudbServiceId = escapeRedis(context.serviceId);
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:query:bulk`,
        searchQuery: `@type:{user\\:nonbeamer|user\\:organization|user\\:static|user\\:dynamic}@partitions:{org\\:${cudbServiceId}}`,
      },
      load: {
        objectId: "$.objectId",
        info: "$.info",
        objectType: "$.info.bulk.objectType",
        createdAt: "$.info.createdAt",
      },
    },
    sortBy: { properties: [{ field: "@createdAt", order: "ASC" }], max: 100000 },
    result: { pagination: { offset: 0, limit: 1000 } },
  };
  try {
    const reply = await bdsPost("aggregateBds", request, context.connectionId);
    const rows = aggregateRows(reply);
    if (!rows) return fail(reply?.message || reply, "The group search returned no list");

    const groups = rows
      .filter((group: any) => group?.objectId !== undefined && group?.objectId !== null)
      .map((group: any): RawGroup => {
        const info = group.info || {};
        return {
          _id: String(group.objectId),
          name: info.name || info.data?.group?.name || "",
          type: typeof info.type === "string" ? info.type.split(":")[1] : undefined,
          pageId: info.data?.group?.pageId || null,
          members: [],
          reportingToGroupId: info.data?.group?.reportingToGroupId || null,
          collaboratingWithGroupIds: info.data?.group?.collaboratingWithGroupIds || [],
        };
      });

    /* Members: the backend's `getGroupKeys`, one `getkeys` per group. A failed one leaves the group without members. */
    let keyFailures = 0;
    const withMembers = await inBatches(groups, 6, async (group) => {
      try {
        const keysReply = await bdsPost("getkeys", { queryId: group._id }, context.connectionId);
        const keys = keysReply?.data?.keys;
        if (!Array.isArray(keys)) {
          keyFailures += 1;
          return group;
        }
        return { ...group, members: userIdsFromGroupKeys(keys).map((id) => ({ _id: id })) };
      } catch (e) {
        keyFailures += 1;
        return group;
      }
    });
    if (keyFailures > 0 && keyFailures === groups.length && groups.length > 0) {
      return fail("getkeys refused every group; members are unknown", "The group member lookup failed");
    }
    return { ok: true, data: withMembers };
  } catch (e: any) {
    return fail(e, "The group search failed");
  }
};

/* ------------------------------------------------------------------ */
/* Events                                                              */
/* ------------------------------------------------------------------ */

/** One event page as the aggregate returns it. */
export interface RawEventPage {
  pageId: string;
  status?: string | null;
  createdAt?: number | string | null;
  profile?: {
    title?: string;
    event?: { title?: string; scheduleDate?: string | number; scheduleTime?: string; [key: string]: unknown };
    [key: string]: unknown;
  } | null;
}

/** Every event page of the organisation, newest first (the School3 calendar read). */
export const fetchEventPages = async (context: OrgContext): Promise<DirectoryResult<RawEventPage[]>> => {
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:page:ride`,
        searchQuery: `@pageType:{event}@partitions:{'org\\:${formatForRedis(context.serviceId)}'}`,
        searchOptions: "VERBATIM TIMEOUT 10000",
      },
      load: {
        profile: "$..profile",
        pageId: "$.objectId",
        status: "$.nonpersistent.static.live.status.name",
        createdAt: "$.createdAt",
      },
    },
    sortBy: { properties: [{ field: "@createdAt", order: "DESC" }], max: 1000 },
  };
  try {
    const reply = await bdsPost("aggregateBds", request, context.connectionId);
    const rows = aggregateRows(reply);
    if (!rows) return fail(reply?.message || reply, "The event search returned no list");
    return { ok: true, data: rows as RawEventPage[] };
  } catch (e: any) {
    return fail(e, "The event search failed");
  }
};
