/**
 * Payment requests — the friend page between the CFO and a recipient:
 * found through BDS when it exists, created over the socket otherwise.
 *
 * `createPage` replies on one topic per connection. Unsubscribing a
 * topic drops every handler registered on it, so sends that run side by
 * side share a single subscription (`CreatePageReplies`) and are told
 * apart by the request id echoed in each reply.
 */
import { SocketTopics } from "constants/enums";
import { generateUUID } from "utils/appUtil";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";

import { ECOSYSTEM, aggregateRows, bdsPost } from "../directory/bds";
import { OrgContext } from "../directory/directoryApi";
import { createPageTopics, friendPageChanges } from "./pageMessages";

export const CREATE_PAGE_TIMEOUT_MS = 10_000;

/** The id of the newest friend page shared by the two users, or null. Any failure counts as "none". */
export const findFriendPage = async (context: OrgContext, meId: string, friendId: string): Promise<string | null> => {
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:pageUpdatedAtIndex`,
        searchQuery: `@pageType:{friend}@pageMembers:{${meId}}@pageMembers:{${friendId}}`,
        searchOptions: "VERBATIM TIMEOUT 10000",
      },
      load: { pageId: "$.objectId", updatedAt: "$.updatedAt" },
    },
    sortBy: { properties: [{ field: "@updatedAt", order: "DESC" }], max: 1 },
  };
  try {
    const reply = await bdsPost("aggregateBds", request, context.connectionId);
    const rows = aggregateRows(reply);
    const first = rows && rows.find((row: any) => row?.pageId !== undefined && row?.pageId !== null);
    return first ? String(first.pageId) : null;
  } catch (e) {
    return null;
  }
};

/** The new page's id, whichever of the reply shapes the live services use. */
const pageIdOf = (response: any): string | null => {
  const data = response?.data;
  const id = data?.id ?? data?.pageId ?? data?.page?.objectId ?? data?.page?._id ?? data?.objectId;
  return id === undefined || id === null ? null : String(id);
};

/**
 * One subscription to `createPage/reply` for a whole send, with the
 * pending requests keyed by id. Open it before the first create and
 * close it after the last.
 */
export class CreatePageReplies {
  private pending = new Map<string, { resolve: (pageId: string) => void; reject: (e: Error) => void }>();
  private topics: { publish: string; reply: string };
  private opened = false;

  constructor(private socket: ISocket, private connectionId: string) {
    this.topics = createPageTopics(connectionId);
  }

  open() {
    if (this.opened) return;
    this.opened = true;
    this.socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      this.topics.reply,
      (envelope: any) => {
        const id = envelope?.id;
        let key = id ? String(id) : null;
        /* A reply without the echoed id can only be matched when a single create is pending. */
        if ((!key || !this.pending.has(key)) && this.pending.size === 1) key = Array.from(this.pending.keys())[0];
        const waiter = key ? this.pending.get(key) : undefined;
        if (!waiter || !key) return;
        this.pending.delete(key);
        const response = envelope?.response;
        const pageId = pageIdOf(response);
        if (response && response.status !== false && pageId) waiter.resolve(pageId);
        else waiter.reject(new Error(response?.message || response?.data?.details || "createPage failed"));
      },
      /* A unique id: the socket replaces handlers that share one. */
      `cfo-payment-requests-${generateUUID()}`
    );
  }

  close() {
    if (!this.opened) return;
    this.opened = false;
    this.pending.forEach((waiter) => waiter.reject(new Error("createPage cancelled")));
    this.pending.clear();
    this.socket.unSubscribeToEvent(SocketTopics.UnSubscribePageTopics, this.topics.reply);
  }

  /** Publishes one createPage and resolves with the new page id, or rejects on error or after the timeout. */
  create(changes: unknown[], timeoutMs = CREATE_PAGE_TIMEOUT_MS): Promise<string> {
    this.open();
    const requestId = generateUUID();
    return new Promise<string>((resolve, reject) => {
      const timer = setTimeout(() => {
        if (this.pending.delete(requestId)) reject(new Error("createPage timed out"));
      }, timeoutMs);
      this.pending.set(requestId, {
        resolve: (pageId) => {
          clearTimeout(timer);
          resolve(pageId);
        },
        reject: (e) => {
          clearTimeout(timer);
          reject(e);
        },
      });
      this.socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        this.topics.publish,
        wrapRequestPayload({ changes }, requestId),
        (ack: { status: boolean }) => {
          if (!ack || ack.status === false) {
            if (this.pending.delete(requestId)) {
              clearTimeout(timer);
              reject(new Error("createPage could not be published"));
            }
          }
        }
      );
    });
  }
}

export interface EnsuredPage {
  pageId: string;
  created: boolean;
}

/** The friend page for a recipient: the existing one, or a new one. */
export const ensureFriendPage = async (input: {
  replies: CreatePageReplies;
  context: OrgContext;
  me: { id: string; beamId?: string | null };
  friend: { id: string; beamId?: string | null };
}): Promise<EnsuredPage> => {
  const existing = await findFriendPage(input.context, input.me.id, input.friend.id);
  if (existing) return { pageId: existing, created: false };
  const pageId = await input.replies.create(
    friendPageChanges({
      meId: input.me.id,
      meBeamId: input.me.beamId,
      friendId: input.friend.id,
      friendBeamId: input.friend.beamId,
      serviceId: input.context.serviceId,
    })
  );
  return { pageId, created: true };
};
