/**
 * Directory — the BDS transport and helpers api-admin-core uses, ported.
 *
 * `role.service`, `live-user.service`, `group.service` and
 * `project.service` read the organisation through the BDS API with a
 * JSON POST and a `topic` header (`core/common/util/request.util.ts`).
 * The shared `Api` class drops custom headers, so this uses `fetch`
 * directly, like `services/apis/aiSchedulerClient.ts` does.
 */

const ecosystem = process.env.REACT_APP_ECO_SYSTEM || "";
const bdsBase = process.env.REACT_APP_BDS_API || "";

/**
 * Reads (`aggregateBds`, `getkeys`) and the writes api-admin-core makes
 * the same way (`createQuery`, `updateQuery`, `setkeys`): JSON-patch
 * changes on a query object in the organisation's partition.
 */
export type BdsOp = "aggregateBds" | "getkeys" | "createQuery" | "updateQuery" | "setkeys";

/** Verbatim port of api-admin-core `StringUtil.escapeRedis`. */
export const escapeRedis = (str: string): string => {
  const replacements: { [key: string]: string } = {
    ",": "\\,", ".": "\\.", "<": "\\<", ">": "\\>", "{": "\\{", "}": "\\}",
    "[": "\\[", "]": "\\]", '"': '\\"', "'": "\\'", ":": "\\:", ";": "\;",
    "!": "\\!", "@": "\\@", "#": "\\#", $: "\\$", "%": "\\%", "^": "\\^",
    "&": "\\&", "*": "\\*", "(": "\\(", ")": "\\)", "-": "\\-", "+": "\\+",
    "=": "\\=", "~": "\\~",
  };
  return String(str || "").replace(/,|\.|<|>|\{|\}|\[|\]|"|'|:|;|!|@|#|\$|%|\^|&|\*|\(|\)|-|\+|=|~/g, (x) => replacements[x]);
};

/** The topic header the backend sends with each BDS call. */
export const bdsTopic = (connectionId: string, op: BdsOp): string =>
  `${ecosystem}/connection/${connectionId}/service/bds/${op}`;

/** A BDS POST exactly as `sendRequest` makes it; resolves to the parsed body. */
export const bdsPost = async (op: BdsOp, body: unknown, connectionId: string): Promise<any> => {
  const response = await fetch(`${bdsBase}/${op}`, {
    method: "POST",
    headers: { accept: "*/*", "Content-Type": "application/json", topic: bdsTopic(connectionId, op) },
    body: JSON.stringify(body),
  });
  const text = await response.text();
  try {
    return text ? JSON.parse(text) : {};
  } catch (e) {
    return { status: false, message: text.slice(0, 200) };
  }
};

/** The id of the object a `createQuery` reply created, or null when the call failed. */
export const createdId = (reply: any): string | null => {
  const id = reply?.data?.id;
  return id === undefined || id === null || id === "" ? null : String(id);
};

/** The row list of an aggregate reply, or null when the call failed. */
export const aggregateRows = (reply: any): any[] | null => (Array.isArray(reply?.data) ? reply.data : null);

/** Port of `group.util.ts` `userIdsFromGroupKeys`: user ids out of `<eco>:user:<id>:<serviceId>` keys. */
export const userIdsFromGroupKeys = (keys: string[] = []): string[] =>
  keys
    .filter((key) => typeof key === "string" && key.includes("user"))
    .map((key) => key.split(":", 3)[2])
    .filter((id) => !!id);

export const ECOSYSTEM = ecosystem;
