import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Button, Empty, Modal, Steps, Tag, Tooltip } from "antd";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";

import ConfirmationModal from "../../../../common/Confirmation";
import { pushNotification } from "utils/notifications";

import { Domain, PaymentRequestDraft, PaymentRequestTarget, ProjectMember } from "./types";
import { getPaymentConfig } from "./mockData";
import { money, validatePaymentConfig } from "./paymentConfig";
import {
  LiveDraftInput,
  amountFor,
  createDraft,
  membersFor,
  requestTotal,
  wizardModeOf,
} from "./SendPaymentRequest/draft";
import StepConfiguration from "./SendPaymentRequest/StepConfiguration";
import StepRecipients from "./SendPaymentRequest/StepRecipients";
import StepReview from "./SendPaymentRequest/StepReview";
import StepSending from "./SendPaymentRequest/StepSending";
import MemberCustomiseModal from "./SendPaymentRequest/MemberCustomiseModal";
import { OrgContext } from "./directory/directoryApi";
import { SendOutcome, sendPaymentRequests } from "./payments/sendPaymentRequest";
import { usePaymentRequests } from "./payments/usePaymentRequests";

export interface SentResult {
  recipients: number;
  total: number;
  sent: number;
  failed: number;
}

interface Props {
  open: boolean;
  target: PaymentRequestTarget | null;
  domain: Domain;
  onClose: () => void;
  onSent?: (result: SentResult) => void;
  /** Live roster and seed configuration; without it the mock lookups are used (vendors). */
  live?: LiveDraftInput & { subject: string };
  /** The dashboard socket and organisation; without both, sending is disabled. */
  socket?: ISocket | null;
  context?: OrgContext | null;
}

/**
 * Send a payment request, in four steps: the configuration it is built
 * on (editable in full), who receives it (with per-member copies when
 * the CFO wants some members on different terms), a review, and the
 * send itself - one friend page and one `pay` message per recipient,
 * reported row by row with a retry for the ones that failed.
 *
 * Every request is recorded (`payments/paymentRequestRecord.ts`) before
 * its message goes out; the Transactions screen lists the records, so
 * they are refreshed once a run settles.
 *
 * The draft is a snapshot of the configuration; the stored
 * configuration is never changed from here.
 */
const SendPaymentRequestModal: FC<Props> = ({ open, target, domain, onClose, onSent, live, socket, context }) => {
  const { encrypted_token, userInfo } = useSelector((state: RootState) => state.auth) as any;
  const paymentRequests = usePaymentRequests();
  const [step, setStep] = useState(0);
  const [draft, setDraftState] = useState<PaymentRequestDraft | null>(null);
  const [customising, setCustomising] = useState<ProjectMember | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [outcomes, setOutcomes] = useState<SendOutcome[]>([]);
  const [running, setRunning] = useState(false);
  const runId = useRef(0);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const wizardMode = wizardModeOf(target);
  const members = useMemo(() => membersFor(target, live), [target, live]);
  const focusIds = (target && target.focusMemberIds) || [];
  const source = live
    ? live.config
    : target
    ? getPaymentConfig(target.payee ? target.payee.paymentConfigId : target.project ? target.project.paymentConfigId : null)
    : null;
  const subjectName = live
    ? live.subject
    : target
    ? target.payee
      ? target.payee.name
      : target.project
      ? target.project.name
      : ""
    : "";

  useEffect(() => {
    setDraftState(createDraft(target, live));
    setStep(0);
    setCustomising(null);
    setConfirming(false);
    setOutcomes([]);
    setRunning(false);
    runId.current += 1;
  }, [target, open]); // eslint-disable-line react-hooks/exhaustive-deps

  const setDraft = (update: (current: PaymentRequestDraft) => PaymentRequestDraft) =>
    setDraftState((current) => (current ? update(current) : current));

  const errors = useMemo(() => (draft ? validatePaymentConfig(draft.config) : []), [draft]);
  const recipients = draft ? draft.recipientIds.length : 0;
  const total = draft ? requestTotal(draft) : 0;
  const currency = draft ? draft.config.currency : "USD";
  const recipientWord = recipients === 1 ? "recipient" : "recipients";

  const senderId: string | null = encrypted_token?.userId ? String(encrypted_token.userId) : null;
  const canSend = !!socket && !!context && !!senderId && !!live;
  const sendBlockedReason = !live
    ? "Placeholder data cannot be sent"
    : !socket
    ? "The dashboard socket is not connected"
    : !context || !senderId
    ? "Waiting for the organisation and user from the link's token"
    : null;

  /** Runs the send for the given members; the step shows every outcome as it lands. */
  const run = async (toMembers: ProjectMember[], previous: SendOutcome[]) => {
    if (!draft || !socket || !context || !senderId) return;
    const mine = ++runId.current;
    setRunning(true);
    const pendingIds = new Set(toMembers.map((m) => m.id));
    const initial: SendOutcome[] = previous
      .filter((o) => !pendingIds.has(o.memberId))
      .concat(toMembers.map((m) => ({ memberId: m.id, name: m.name, status: "pending" as const })));
    setOutcomes(initial);

    const results = await sendPaymentRequests({
      socket,
      context,
      me: { id: senderId, beamId: userInfo?.beamId || null },
      draft,
      members: toMembers,
      subject: subjectName || "Payment request",
      project: target ? target.project : null,
      domain,
      previous,
      onProgress: (outcome) => {
        if (!mounted.current || mine !== runId.current) return;
        setOutcomes((current) => current.map((o) => (o.memberId === outcome.memberId ? outcome : o)));
      },
    });
    if (!mounted.current || mine !== runId.current) return;
    setRunning(false);

    const all = initial.map((o) => results.find((r) => r.memberId === o.memberId) || o);
    const sent = all.filter((o) => o.status === "sent").length;
    const failed = all.filter((o) => o.status === "failed" || o.status === "unconfirmed").length;
    pushNotification(
      failed === 0
        ? `Payment request sent to ${sent} ${sent === 1 ? "recipient" : "recipients"}`
        : `Sent to ${sent}, not confirmed for ${failed} - see the list to retry`,
      failed === 0 ? "success" : "warning",
      "TOP_CENTER",
      2500
    );
    if (onSent) onSent({ recipients: all.length, total, sent, failed });
    /* The records are the Transactions screen's rows now. */
    paymentRequests.refresh();
  };

  const send = () => {
    if (!draft) return;
    setConfirming(false);
    setStep(3);
    const selected = members.filter((m) => draft.recipientIds.indexOf(m.id) !== -1);
    run(selected, []);
  };

  const needsRetry = (o: SendOutcome) => o.status === "failed" || o.status === "unconfirmed";

  const retryFailed = () => {
    const failedIds = new Set(outcomes.filter(needsRetry).map((o) => o.memberId));
    const failedMembers = members.filter((m) => failedIds.has(m.id));
    if (failedMembers.length > 0) run(failedMembers, outcomes);
  };

  const failedCount = outcomes.filter(needsRetry).length;
  const nextDisabled = (step === 0 && errors.length > 0) || (step === 1 && recipients === 0);

  const footer = [];
  if (step < 3) {
    footer.push(
      <Button key="cancel" className="beam-btn orange-btn bordered" onClick={onClose}>
        Cancel
      </Button>
    );
  }
  if (draft && step > 0 && step < 3) {
    footer.push(
      <Button key="back" className="beam-btn gray-btn bordered" onClick={() => setStep(step - 1)}>
        Back
      </Button>
    );
  }
  if (draft && step < 2) {
    footer.push(
      <Button key="next" className="beam-btn blue-btn cover" disabled={nextDisabled} onClick={() => setStep(step + 1)}>
        Next
      </Button>
    );
  }
  if (draft && step === 2) {
    footer.push(
      <Tooltip key="send" title={sendBlockedReason || undefined}>
        <span>
          <Button
            className="beam-btn green-btn cover"
            disabled={recipients === 0 || !canSend}
            onClick={() => setConfirming(true)}
          >
            Send to {recipients} {recipientWord}
          </Button>
        </span>
      </Tooltip>
    );
  }
  if (step === 3) {
    if (!running && failedCount > 0) {
      footer.push(
        <Button key="retry" className="beam-btn blue-btn cover" onClick={retryFailed}>
          Retry failed ({failedCount})
        </Button>
      );
    }
    footer.push(
      <Button key="close" className="beam-btn gray-btn bordered" disabled={running} onClick={onClose}>
        {running ? "Sending…" : "Close"}
      </Button>
    );
  }

  return (
    <>
      <Modal
        open={open}
        width={1040}
        onCancel={running ? undefined : onClose}
        closable={!running}
        maskClosable={!running}
        className="beam-modal cfo-action-modal cfo-wizard"
        bodyStyle={{ maxHeight: "72vh", overflow: "auto" }}
        title={
          <div className="cfo-wizard__title">
            <div className="cfo-action-modal__title">
              <span>Send Payment Request</span>
              {subjectName && <Tag color="geekblue">{subjectName}</Tag>}
              {draft && (
                <span className="cfo-action-modal__scope">
                  {recipients} {recipientWord} · {money(total, currency)}
                </span>
              )}
            </div>
            {draft && (
              <Steps
                size="small"
                current={step}
                className="cfo-wizard__steps"
                onChange={(next) => next < step && step < 3 && setStep(next)}
                items={[
                  { title: "Configuration", description: errors.length ? `${errors.length} to fix` : "Review and adjust" },
                  { title: "Recipients", description: draft.mode === "custom" ? "Customise members" : "Same for everyone" },
                  { title: "Review" },
                  { title: "Send", description: running ? "In progress" : outcomes.length ? "Done" : undefined },
                ]}
              />
            )}
          </div>
        }
        footer={footer}
      >
        {!draft && (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description={
              subjectName
                ? `${subjectName} has no payment configuration attached. Attach one from the admin portal's Payment Configuration screen before sending a request.`
                : "Select a project or payee first."
            }
          />
        )}

        {draft && source && step === 0 && (
          <StepConfiguration
            draft={draft}
            setDraft={setDraft}
            errors={errors}
            wizardMode={wizardMode}
            source={source}
            subjectName={subjectName}
          />
        )}
        {draft && step === 1 && (
          <StepRecipients
            draft={draft}
            setDraft={setDraft}
            members={members}
            wizardMode={wizardMode}
            focusIds={focusIds}
            onCustomise={setCustomising}
          />
        )}
        {draft && step === 2 && (
          <StepReview draft={draft} members={members} wizardMode={wizardMode} subjectName={subjectName} />
        )}
        {draft && step === 3 && (
          <StepSending
            outcomes={outcomes}
            members={members}
            amountFor={(id) => amountFor(draft, id)}
            currency={currency}
            running={running}
          />
        )}
      </Modal>

      {draft && customising && (
        <MemberCustomiseModal
          key={customising.id}
          member={customising}
          draft={draft}
          onClose={() => setCustomising(null)}
          onApply={(request) => {
            const id = customising.id;
            setDraft((current) => ({
              ...current,
              overrides: { ...current.overrides, [id]: request },
              recipientIds:
                current.recipientIds.indexOf(id) === -1 ? current.recipientIds.concat(id) : current.recipientIds,
            }));
            setCustomising(null);
          }}
        />
      )}

      {confirming && draft && (
        <ConfirmationModal
          message={`Send a payment request to ${recipients} ${recipientWord} for ${money(total, currency)}? Each recipient gets a pay message on their page with you.`}
          onClose={() => setConfirming(false)}
          handleConfirm={send}
        />
      )}
    </>
  );
};

export default SendPaymentRequestModal;
