/**
 * Stripe payments tab — workflow client.
 *
 * Same request shape the Payment modals use (see
 * `Modals/Payment/EditPaymentModal.tsx`), but called directly rather than
 * through the `INVOKE_WORKFLOW` saga: that saga only toasts on failure and
 * never invokes its callback, which would leave an awaiting caller hanging.
 *
 * The shared `Api` class takes no AbortSignal, so requests cannot be
 * cancelled; callers guard against stale replies instead (see
 * `useStripeCharges`).
 */
import { invokeWorkflow } from "services/apis/collections/oAuthApis";

import {
  StripeCharge,
  StripeIdentity,
  StripeOp,
  StripeRefund,
  StripeSearchResult,
  StripeWorkflowResult,
} from "./stripeTypes";
import { ChargeSearchRequest } from "./chargeQuery";

/** The engine-side `timeout` in the payload does not bound the HTTP call; this does. */
const CLIENT_TIMEOUT_MS = 20_000;

/** The engine-side budget for the workflow run, as the Payment modals send it. */
const WORKFLOW_TIMEOUT_MS = 10_000;

const timeout = (ms: number) =>
  new Promise<never>((_, reject) => {
    setTimeout(() => reject(new Error("The payment workflow timed out")), ms);
  });

/**
 * Runs one op of the Stripe workflow and normalises every way it can
 * come back: a Stripe object, a Stripe error, the workflow's own error
 * path, an HTTP error body, or no reply at all.
 */
export async function invokeStripeOp<T>(
  identity: StripeIdentity,
  op: StripeOp,
  params: Record<string, unknown> = {}
): Promise<StripeWorkflowResult<T>> {
  const payload = {
    changes: [],
    configId: process.env.REACT_APP_STRIPE_CONFIG_ID,
    request: {
      op,
      userId: identity.userId,
      cudbServiceId: identity.cudbServiceId,
      ...params,
    },
    timeout: WORKFLOW_TIMEOUT_MS,
  };

  let resp: any;
  try {
    resp = await Promise.race([invokeWorkflow(payload as any), timeout(CLIENT_TIMEOUT_MS)]);
  } catch (e: any) {
    /* Includes the TypeError `invokeWorkflow` itself throws from its catch
       when a network failure leaves `error.response` undefined. */
    return { ok: false, error: { kind: "network", message: e?.message || "Network error" } };
  }

  /* `invokeWorkflow` resolves to the error message string on an HTTP error. */
  if (typeof resp === "string") {
    return { ok: false, error: { kind: "http", message: resp } };
  }

  const data = resp?.data;

  if (data?.error) {
    return {
      ok: false,
      error: {
        kind: "stripe",
        code: data.error.code || data.error.type,
        message: data.error.message || "Stripe rejected the request",
      },
    };
  }

  if (data === undefined || data === null || data.response === undefined) {
    /* 79-error replies with `dataset.output.response`, e.g. {message: "fetching user failed"};
       an HTTP error body looks like {status: false, message}. */
    const message =
      data?.message || resp?.message || resp?.error || "The payment workflow returned no response";
    return { ok: false, error: { kind: "workflow", message: String(message) } };
  }

  return { ok: true, data: data.response as T, customerId: data.customerId };
}

export const searchCharges = (identity: StripeIdentity, request: ChargeSearchRequest) =>
  invokeStripeOp<StripeSearchResult<StripeCharge>>(identity, "searchCharges", { ...request });

export const retrieveCharge = (identity: StripeIdentity, chargeId: string) =>
  invokeStripeOp<StripeCharge>(identity, "retrieveCharge", { chargeId });

/**
 * Refunds a charge. `amountMinor` is in Stripe minor units; leaving it
 * out omits the key from the request, which makes Stripe refund the
 * whole remaining balance.
 */
export const refundCharge = (identity: StripeIdentity, chargeId: string, amountMinor?: number) =>
  invokeStripeOp<StripeRefund>(
    identity,
    "refundPaymentCharge",
    amountMinor === undefined ? { chargeId } : { chargeId, amount: amountMinor }
  );
