import { useCallback, useMemo } from "react";

import { Domain, DunningAlert, LedgerRow } from "../types";
import { CfoSession, useCfoSession } from "./useCfoSession";
import { usePaymentRequests } from "./usePaymentRequests";
import { alertsFromRows, currencyOf, ledgerRowsFor } from "./ledgerFromRequests";

export interface LedgerSource {
  rows: LedgerRow[];
  alerts: DunningAlert[];
  /** The moment the rows were computed against; schedule stages and offsets read from it. */
  now: number;
  /** What the screens format figures in: the currency most rows carry. */
  currency: string;
  session: CfoSession;
  /** The link carries a token: render the screen (empty until the records land). */
  signedIn: boolean;
  /** The token is being read or the records are loading; the figures are not final. */
  loading: boolean;
  error: string | null;
  loadedAt: number | null;
  /** Requests whose message was never delivered; they are off the ledger. */
  failedCount: number;
  refresh: () => void;
}

/**
 * What Dashboard, Transactions and Reports read: the organisation's
 * recorded payment requests as ledger rows, with the alerts and the
 * currency derived from them. There is no sample-data fallback: until
 * the records have loaded the rows are empty, so every figure reads 0.
 */
export const useLedgerSource = (domain: Domain): LedgerSource => {
  const session = useCfoSession();
  const requests = usePaymentRequests();

  /* One `now` per load, so sorting and stages stay put between renders. */
  const now = useMemo(() => Date.now(), [requests.loadedAt]); // eslint-disable-line react-hooks/exhaustive-deps

  const rows = useMemo<LedgerRow[]>(() => ledgerRowsFor(requests.records, domain, now), [requests.records, domain, now]);
  const alerts = useMemo<DunningAlert[]>(() => alertsFromRows(rows, now), [rows, now]);
  const currency = useMemo(() => currencyOf(rows), [rows]);

  const failedCount = useMemo(
    () => requests.records.filter((r) => r.domain === domain && r.delivery === "failed").length,
    [requests.records, domain]
  );

  const refresh = useCallback(() => {
    if (session === "ready") requests.refresh();
  }, [session, requests]);

  return {
    rows,
    alerts,
    now,
    currency,
    session,
    signedIn: session !== "no-token",
    loading: session === "pending" || requests.loading || (session === "ready" && requests.loadedAt === null && !requests.error),
    error: requests.error,
    loadedAt: requests.loadedAt,
    failedCount,
    refresh,
  };
};
