/**
 * Payment requests — the record of every request sent.
 *
 * One BDS query object per recipient per send, type `payment:request`,
 * stored the way api-admin-core's `payment-config.service` stores
 * `config:payment`: `createQuery` with the body under `/info/data`, the
 * organisation partition, no expiry; `updateQuery` with JSON-patch
 * changes; listed with `aggregateBds` on `query:bulk` by type tag.
 *
 * The record is written before the pay message is published, so a
 * failed send still leaves a row. The message carries the record's id
 * (`attributes.paymentRequestId`) and so does the friend page
 * (`pageApi.ts`); `getkeys` on the record returns the recipient's user
 * key and the page key, as it does for a group's members and page.
 *
 * Pure builders take ids and `now` as inputs so they can be tested;
 * the I/O functions are thin wrappers over `bdsPost`.
 */
import {
  AmountLine,
  AppliedAdjustments,
  CollectionMethod,
  Currency,
  Domain,
  PaymentConfig,
  PlanType,
  ProjectSummary,
  Reminders,
  ScheduleLine,
} from "../types";
import { ECOSYSTEM, aggregateRows, bdsPost, createdId, escapeRedis } from "../directory/bds";
import { OrgContext } from "../directory/directoryApi";

/* ------------------------------------------------------------------ */
/* Shape                                                               */
/* ------------------------------------------------------------------ */

/** BDS query object type stored at `/info/type`. */
export const PAYMENT_REQUEST_TYPE = "payment:request";
/** Redis-escaped form of the type for `aggregateBds` tag queries. */
export const PAYMENT_REQUEST_TYPE_QUERY = "payment\\:request";
/** Key under `/info/data` that holds the record. */
export const PAYMENT_REQUEST_DATA_KEY = "paymentRequest";
export const PAYMENT_REQUEST_SCHEMA_VERSION = 1;
export const PAYMENT_REQUEST_KIND = "cfo-payment-request";

/** Delivery of the pay message: sending → sent, or unconfirmed (the ack never came), or failed. */
export type DeliveryStatus = "sending" | "sent" | "unconfirmed" | "failed";

/**
 * Money state. The dashboard writes `requested`; the payment side moves
 * it on (see PAYMENT_REQUESTS.md): `partial` / `paid` as money settles,
 * `failed` when an attempt is declined, `refunded` after a refund,
 * `void` when the request is withdrawn.
 */
export type PaymentStatus = "requested" | "partial" | "paid" | "failed" | "refunded" | "void";

export const PAYMENT_STATUSES: PaymentStatus[] = ["requested", "partial", "paid", "failed", "refunded", "void"];

export type PaymentEntryStatus = "succeeded" | "pending" | "failed" | "refunded";
export type PaymentEntryMethod = "card" | "ach" | "cash" | "check" | "wire" | "other";

/** One payment attempt, written by the payment side. Amounts in major units of the record's currency. */
export interface PaymentEntry {
  /** Unique per attempt; the Stripe payment intent id when there is one (makes writes idempotent). */
  id: string;
  amount: number;
  currency: string;
  status: PaymentEntryStatus;
  method: PaymentEntryMethod;
  /** Epoch ms of the attempt. */
  at: number;
  stripePaymentIntentId?: string | null;
  stripeChargeId?: string | null;
  receiptUrl?: string | null;
  failureReason?: string | null;
  /** Part of `amount` given back; set when status is `refunded` (partial refunds keep `succeeded`). */
  refundedAmount?: number | null;
  note?: string | null;
}

export interface PaymentRequestRecord {
  schemaVersion: typeof PAYMENT_REQUEST_SCHEMA_VERSION;
  kind: typeof PAYMENT_REQUEST_KIND;
  delivery: DeliveryStatus;
  /** Publish attempts; a retry reuses the record and counts up. */
  attempts: number;
  paymentStatus: PaymentStatus;
  /** One wizard run; every recipient of that run shares it. */
  batchId: string;
  /** Echoed as `attributes.requestId` on the pay message. */
  requestId: string;
  /** Echoed as `connectionInfo.connectionMessageId` on the envelope; reused on retry. */
  connectionMessageId: string;
  page: { id: string; created: boolean; linkError?: string | null };
  org: { serviceId: string };
  domain: Domain;
  sender: { userId: string; beamId: string | null };
  recipient: {
    userId: string;
    beamId: string | null;
    name: string;
    role: string;
    household: string;
    email: string | null;
    phone: string | null;
    stripeCustomerId: string | null;
  };
  project: { id: string; name: string; kind: string; paymentConfigId: string | null } | null;
  subject: string;
  config: {
    /** The stored configuration's id; null when the request was built on a blank draft. */
    id: string | null;
    name: string;
    planType: PlanType;
    collectionMethod: CollectionMethod;
    /** The full configuration as sent, so the request can be re-read without the store. */
    snapshot: PaymentConfig;
  };
  applied: AppliedAdjustments;
  note: string;
  amount: { total: number; currency: Currency; lines: AmountLine[] };
  schedule: ScheduleLine[];
  reminders: Reminders;
  createdAt: number;
  updatedAt: number;
  sentAt: number | null;
  error?: string | null;
  source: { app: "cfo-dashboard"; version: 1 };

  /* ---- written by the payment side (PAYMENT_REQUESTS.md) ---- */
  /** Settled so far, net of refunds, in major units of `amount.currency`. */
  amountPaid?: number | null;
  payments?: PaymentEntry[];
  /** Epoch ms when `paymentStatus` became `paid`. */
  paidAt?: number | null;
  /** Epoch ms of the latest payment entry. */
  lastPaymentAt?: number | null;
  updatedBy?: { app: string; userId?: string | null } | null;
}

export interface StoredPaymentRequest extends PaymentRequestRecord {
  _id: string;
}

/* ------------------------------------------------------------------ */
/* Builders (pure)                                                     */
/* ------------------------------------------------------------------ */

/** What the message builder computed for one recipient; the record and the message share it. */
export interface ComputedRequest {
  config: PaymentConfig;
  applied: AppliedAdjustments;
  note: string;
  due: { total: number; lines: AmountLine[] };
  schedule: ScheduleLine[];
}

export interface RecordInput {
  context: OrgContext;
  domain: Domain;
  batchId: string;
  requestId: string;
  connectionMessageId: string;
  me: { id: string; beamId?: string | null };
  member: {
    id: string;
    name: string;
    role: string;
    household: string;
    beamId?: string | null;
    email?: string | null;
    phone?: string | null;
    stripeCustomerId?: string | null;
  };
  project: ProjectSummary | null;
  subject: string;
  request: ComputedRequest;
  page: { id: string; created: boolean };
  now: number;
}

/** Blank drafts carry a `draft-<time>` id that names no stored configuration. */
const storedConfigId = (id: string | null | undefined): string | null =>
  id && !/^draft-/.test(id) ? String(id) : null;

/** The record as it is first written: delivery `sending`, one attempt. */
export const buildPaymentRequestRecord = (input: RecordInput): PaymentRequestRecord => ({
  schemaVersion: PAYMENT_REQUEST_SCHEMA_VERSION,
  kind: PAYMENT_REQUEST_KIND,
  delivery: "sending",
  attempts: 1,
  paymentStatus: "requested",
  batchId: input.batchId,
  requestId: input.requestId,
  connectionMessageId: input.connectionMessageId,
  page: { id: input.page.id, created: input.page.created, linkError: null },
  org: { serviceId: input.context.serviceId },
  domain: input.domain,
  sender: { userId: String(input.me.id), beamId: input.me.beamId || null },
  recipient: {
    userId: String(input.member.id),
    beamId: input.member.beamId || null,
    name: input.member.name,
    role: input.member.role,
    household: input.member.household || "",
    email: input.member.email || null,
    phone: input.member.phone || null,
    stripeCustomerId: input.member.stripeCustomerId || null,
  },
  project: input.project
    ? {
        id: input.project.id,
        name: input.project.name,
        kind: input.project.kind,
        paymentConfigId: input.project.paymentConfigId,
      }
    : null,
  subject: input.subject,
  config: {
    id: storedConfigId(input.request.config._id),
    name: input.request.config.name,
    planType: input.request.config.planType,
    collectionMethod: input.request.config.collectionMethod,
    snapshot: input.request.config,
  },
  applied: input.request.applied,
  note: input.request.note,
  amount: { total: input.request.due.total, currency: input.request.config.currency, lines: input.request.due.lines },
  schedule: input.request.schedule,
  reminders: input.request.config.reminders,
  createdAt: input.now,
  updatedAt: input.now,
  sentAt: null,
  error: null,
  source: { app: "cfo-dashboard", version: 1 },
});

/** `/info/name`: what a listing of raw objects shows. */
export const recordName = (record: PaymentRequestRecord): string => `${record.subject} · ${record.recipient.name}`;

export interface BdsChange {
  op: "add" | "replace";
  path: string;
  value: unknown;
}

/** The `createQuery` body: the object as api-admin-core writes one, body under `/info/data/paymentRequest`. */
export const createQueryBody = (serviceId: string, record: PaymentRequestRecord): { changes: BdsChange[] } => ({
  changes: [
    {
      op: "add",
      path: "/info",
      value: {
        type: PAYMENT_REQUEST_TYPE,
        name: recordName(record),
        createdAt: record.createdAt,
        data: { [PAYMENT_REQUEST_DATA_KEY]: record },
      },
    },
    { op: "add", path: "/partitions", value: [`org:${serviceId}`] },
    { op: "add", path: "$.objectExpiry", value: "0" },
  ],
});

export type RecordPatch = Partial<Omit<PaymentRequestRecord, "schemaVersion" | "kind" | "createdAt">>;

/**
 * The `updateQuery` changes for a patch: one `add` per top-level key
 * (JSON-patch `add` on an existing member replaces it, and unlike
 * `replace` it also creates a key that was never written) plus
 * `updatedAt`.
 */
export const updateChanges = (patch: RecordPatch, now: number): BdsChange[] => {
  const changes: BdsChange[] = [];
  (Object.keys(patch) as (keyof RecordPatch)[]).forEach((key) => {
    const value = patch[key];
    if (value === undefined) return;
    changes.push({ op: "add", path: `/info/data/${PAYMENT_REQUEST_DATA_KEY}/${key}`, value });
  });
  changes.push({ op: "add", path: `/info/data/${PAYMENT_REQUEST_DATA_KEY}/updatedAt`, value: now });
  return changes;
};

/** The keys that make the record reachable with `getkeys`: the recipient's user key and the page key. */
export const recordKeys = (record: Pick<PaymentRequestRecord, "recipient" | "page" | "org">): string[] => [
  `${ECOSYSTEM}:user:${record.recipient.userId}:${record.org.serviceId}`,
  `${ECOSYSTEM}:page:${record.page.id}:live`,
];

/** One aggregate row as a stored record, or null when it is not one. */
export const toStoredRecord = (row: any): StoredPaymentRequest | null => {
  if (!row || row.objectId === undefined || row.objectId === null) return null;
  const body = row.info?.data?.[PAYMENT_REQUEST_DATA_KEY];
  if (!body || typeof body !== "object" || !body.recipient || !body.amount) return null;
  return {
    ...body,
    _id: String(row.objectId),
    delivery: body.delivery || "sent",
    attempts: typeof body.attempts === "number" ? body.attempts : 1,
    page: body.page || { id: "", created: false },
    project: body.project || null,
    schedule: Array.isArray(body.schedule) ? body.schedule : [],
    amount: {
      total: Number(body.amount.total) || 0,
      currency: body.amount.currency || "USD",
      lines: Array.isArray(body.amount.lines) ? body.amount.lines : [],
    },
    createdAt: Number(body.createdAt) || Number(row.info?.createdAt) || 0,
    updatedAt: Number(body.updatedAt) || Number(body.createdAt) || 0,
    sentAt: body.sentAt === undefined || body.sentAt === null ? null : Number(body.sentAt),
    paymentStatus: PAYMENT_STATUSES.indexOf(body.paymentStatus) !== -1 ? body.paymentStatus : "requested",
    amountPaid: optionalNumber(body.amountPaid),
    payments: Array.isArray(body.payments) ? body.payments.map(toPaymentEntry).filter(Boolean) : [],
    paidAt: optionalNumber(body.paidAt),
    lastPaymentAt: optionalNumber(body.lastPaymentAt),
  };
};

const optionalNumber = (value: unknown): number | null => {
  if (value === undefined || value === null || value === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const toPaymentEntry = (raw: any): PaymentEntry =>
  raw && typeof raw === "object"
    ? {
        ...raw,
        id: String(raw.id ?? ""),
        amount: Number(raw.amount) || 0,
        currency: raw.currency || "",
        status: raw.status || "pending",
        method: raw.method || "other",
        at: Number(raw.at) || 0,
        refundedAmount: optionalNumber(raw.refundedAmount),
      }
    : (null as any);

/** Refunded money across the entries. */
export const refundedAmountOf = (record: Pick<PaymentRequestRecord, "payments">): number =>
  (record.payments || []).reduce(
    (acc, entry) =>
      acc + (entry.refundedAmount ? entry.refundedAmount : entry.status === "refunded" ? entry.amount : 0),
    0
  );

/**
 * What has been collected on a request, net of refunds, clamped to the
 * total: `amountPaid` when the payment side wrote one, else the sum of
 * succeeded entries less refunds, else the whole total when the status
 * says `paid`, else nothing.
 */
export const paidAmountOf = (
  record: Pick<PaymentRequestRecord, "amountPaid" | "payments" | "paymentStatus" | "amount">
): number => {
  const total = record.amount.total;
  let paid: number;
  if (typeof record.amountPaid === "number" && Number.isFinite(record.amountPaid)) {
    paid = record.amountPaid;
  } else if (record.payments && record.payments.length > 0) {
    const succeeded = record.payments
      .filter((entry) => entry.status === "succeeded" || entry.status === "refunded")
      .reduce((acc, entry) => acc + entry.amount, 0);
    paid = succeeded - refundedAmountOf(record);
  } else {
    paid = record.paymentStatus === "paid" ? total : 0;
  }
  return Math.max(0, Math.min(total, paid));
};

/* ------------------------------------------------------------------ */
/* I/O                                                                 */
/* ------------------------------------------------------------------ */

/** Writes the record; resolves with the new object's id. */
export const createPaymentRequestRecord = async (context: OrgContext, record: PaymentRequestRecord): Promise<string> => {
  const reply = await bdsPost("createQuery", createQueryBody(context.serviceId, record), context.connectionId);
  const id = createdId(reply);
  if (!id) throw new Error(reply?.message || "The payment request could not be recorded");
  return id;
};

/** Applies a patch to a stored record. */
export const updatePaymentRequestRecord = async (context: OrgContext, id: string, patch: RecordPatch): Promise<void> => {
  const reply = await bdsPost("updateQuery", { objectId: id, changes: updateChanges(patch, Date.now()) }, context.connectionId);
  if (reply && reply.status === false) throw new Error(reply.message || "The payment request record could not be updated");
};

/** Best effort: sets the record's keys so `getkeys` leads to the recipient and the page. Never throws. */
export const linkPaymentRequestKeys = async (
  context: OrgContext,
  id: string,
  record: Pick<PaymentRequestRecord, "recipient" | "page" | "org">
): Promise<boolean> => {
  try {
    const reply = await bdsPost("setkeys", { queryId: id, keys: recordKeys(record) }, context.connectionId);
    return !(reply && reply.status === false);
  } catch (e) {
    return false;
  }
};

/** Every payment request of the organisation, newest first. */
export const fetchPaymentRequests = async (context: OrgContext): Promise<StoredPaymentRequest[]> => {
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:query:bulk`,
        searchQuery: `@type:{${PAYMENT_REQUEST_TYPE_QUERY}}@partitions:{org\\:${escapeRedis(context.serviceId)}}`,
      },
      load: { objectId: "$.objectId", info: "$.info", createdAt: "$.info.createdAt" },
    },
    sortBy: { properties: [{ field: "@createdAt", order: "DESC" }], max: 100000 },
    result: { pagination: { offset: 0, limit: 1000 } },
  };
  const reply = await bdsPost("aggregateBds", request, context.connectionId);
  const rows = aggregateRows(reply);
  if (!rows) throw new Error(reply?.message || "The payment request list returned no list");
  return rows
    .map(toStoredRecord)
    .filter((record): record is StoredPaymentRequest => record !== null)
    .sort((a, b) => b.createdAt - a.createdAt);
};
