/**
 * Payment requests — the organisation's stored payment configurations,
 * read the way api-admin-core's `payment-config.service` reads them:
 * BDS records of type `config:payment` in the org partition, the
 * configuration under `info.data.paymentConfig`.
 */
import { useEffect, useRef, useState } from "react";

import { PaymentConfig } from "../types";
import { makeConfig } from "../paymentConfig";
import { ECOSYSTEM, aggregateRows, bdsPost, escapeRedis } from "../directory/bds";
import { OrgContext } from "../directory/directoryApi";

export const fetchPaymentConfigs = async (context: OrgContext): Promise<PaymentConfig[]> => {
  const request = {
    select: {
      index: {
        searchIndex: `${ECOSYSTEM}:query:bulk`,
        searchQuery: `@type:{config\\:payment}@partitions:{org\\:${escapeRedis(context.serviceId)}}`,
      },
      load: { objectId: "$.objectId", info: "$.info", createdAt: "$.info.createdAt" },
    },
    sortBy: { properties: [{ field: "@createdAt", order: "ASC" }], max: 100000 },
    result: { pagination: { offset: 0, limit: 1000 } },
  };
  const reply = await bdsPost("aggregateBds", request, context.connectionId);
  const rows = aggregateRows(reply);
  if (!rows) throw new Error(reply?.message || "The payment configuration list returned no list");
  return rows
    .filter((row: any) => row?.objectId !== undefined && row?.objectId !== null)
    .map((row: any) => {
      const info = row.info || {};
      const body = info.data?.paymentConfig || {};
      return makeConfig({ ...body, _id: String(row.objectId), name: info.name ?? body.name ?? "" });
    });
};

export interface PaymentConfigsState {
  configs: PaymentConfig[];
  loading: boolean;
  error: string | null;
  byId: (id: string | null | undefined) => PaymentConfig | null;
}

/** The organisation's configurations, loaded once per organisation. */
export const usePaymentConfigs = (context: OrgContext | null): PaymentConfigsState => {
  const [configs, setConfigs] = useState<PaymentConfig[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const loadedFor = useRef<string | null>(null);

  useEffect(() => {
    if (!context || loadedFor.current === context.serviceId) return;
    loadedFor.current = context.serviceId;
    let active = true;
    setLoading(true);
    fetchPaymentConfigs(context)
      .then((list) => {
        if (!active) return;
        setConfigs(list);
        setError(null);
      })
      .catch((e: any) => {
        if (!active) return;
        setError(e?.message || "The payment configuration list failed");
      })
      .then(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [context]);

  return {
    configs,
    loading,
    error,
    byId: (id) => (id ? configs.find((config) => String(config._id) === String(id)) || null : null),
  };
};
