import { PERMISSION_TYPES, SCHOOL_BUS_MENU_ITEMS } from "utils/PageTypes";

/**
 * Who a user is and which modules they get, decided from the permissions on
 * their role (the ones set in the admin console), not from the role's name.
 */
export type DashboardRole = "admin" | "coach" | "manager" | "staff" | "member";

const M = SCHOOL_BUS_MENU_ITEMS;

/**
 * The sidebar modules each permission unlocks. A user sees the union over their
 * role's permissions; `admin` sees everything. Edit this table to change what a
 * role can open.
 *
 *   live       everyone: events, documents, pages, assist, exams, parents
 *   dashboard  the overview dashboard and the player and coach lists
 *   cad        teams and the scheduler (the permission to create and dispatch events)
 *   onMove     no extra module here (driver tools live in other products)
 *   admin      everything, including staff and apps
 */
export const MODULES_BY_PERMISSION: Record<string, number[]> = {
  [PERMISSION_TYPES.Live]: [M.Events, M.Documents, M.Chat, M.Assist, M.Exams, M.Parents],
  [PERMISSION_TYPES.Dashboard]: [M.Overview, M.Players, M.Coaches],
  [PERMISSION_TYPES.Cad]: [M.Classes, M.Scheduler],
  [PERMISSION_TYPES.OnMove]: [],
  [PERMISSION_TYPES.Admin]: [M.Staff, M.BeamApps],
};

const has = (permissions: string[] | undefined, permission: string) =>
  !!permissions && permissions.includes(permission);

/** Which kind of user this is, from the role's permissions. */
export const resolveDashboardRole = (
  permissions: string[] | undefined
): DashboardRole => {
  if (has(permissions, PERMISSION_TYPES.Admin)) return "admin";
  if (
    has(permissions, PERMISSION_TYPES.Dashboard) &&
    has(permissions, PERMISSION_TYPES.Cad)
  )
    return "coach";
  if (has(permissions, PERMISSION_TYPES.Dashboard)) return "manager";
  if (has(permissions, PERMISSION_TYPES.OnMove)) return "staff";
  return "member";
};

/**
 * The sidebar options a role's own list can switch on or off (menu item ids).
 * Keep in sync with SIDEBAR_MODULES in api-admin-core `role.enums.ts` and the
 * options on the admin console's role form.
 */
export const TOGGLEABLE_MODULES: number[] = [
  M.Overview,
  M.Players,
  M.Parents,
  M.Coaches,
  M.Staff,
  M.Classes,
  M.Scheduler,
  M.Events,
  M.Exams,
  M.Documents,
  M.BeamApps,
  M.Assist,
  M.Chat,
];

/** The screens the Players and Coaches menu items open use their own ids. */
export const screenModuleId = (screen: number): number =>
  screen === M.Students ? M.Players : screen === M.Teachers ? M.Coaches : screen;

export const moduleScreenId = (moduleId: number): number =>
  moduleId === M.Players ? M.Students : moduleId === M.Coaches ? M.Teachers : moduleId;

/** Modules that open a screen of their own, in the order a landing prefers. */
const LANDING_ORDER: number[] = [
  M.Overview, M.Players, M.Coaches, M.Parents, M.Classes, M.Scheduler,
  M.Events, M.Documents, M.Exams, M.Staff, M.BeamApps,
];

/** The first module the role may open, as a screen id; undefined when none. */
export const firstOpenScreen = (
  permissions: string[] | undefined,
  allowedModules?: number[]
): number | undefined => {
  const id = LANDING_ORDER.find((m) => canSeeModule(permissions, m, allowedModules));
  return id === undefined ? undefined : moduleScreenId(id);
};

export type DashboardKey = "sports" | "cfo";

/**
 * What a role may do on one dashboard: whether it can open it at all, and the
 * sidebar options it shows (undefined = the role's permissions decide).
 */
export interface DashboardAccess {
  enabled: boolean;
  modules?: (number | string)[];
}

/**
 * The role's setting for a dashboard, as saved by the admin console's
 * Dashboards dialog (`role.dashboards.<key>`). A role with no setting for a
 * dashboard is unrestricted there. Roles saved before that dialog existed
 * keep their old single `sidebarModules` list, which counts for the sports
 * dashboard until the role is saved again.
 */
export const dashboardAccess = (role: any, key: DashboardKey): DashboardAccess => {
  const entry = role?.dashboards?.[key];
  if (entry && typeof entry === "object") {
    const modules = Array.isArray(entry.modules)
      ? entry.modules.filter((m: unknown) => typeof m === "number" || typeof m === "string")
      : [];
    return {
      enabled: entry.enabled !== false,
      modules: modules.length ? modules : undefined,
    };
  }
  if (key === "sports") {
    const legacy = roleModuleList(role?.sidebarModules);
    if (legacy) return { enabled: true, modules: legacy };
  }
  return { enabled: true };
};

/**
 * The role's own list of sidebar modules (`role.sidebarModules`, set in the
 * admin console), as menu item ids. Empty or missing means "no list": the
 * permissions alone decide, as before.
 */
export const roleModuleList = (value: unknown): number[] | undefined => {
  if (!Array.isArray(value)) return undefined;
  const ids = value.map((v) => Number(v)).filter((n) => Number.isFinite(n));
  return ids.length ? ids : undefined;
};

/**
 * True when the role's list leaves this module out. Admins are never
 * restricted, so nobody can lock themselves out of the settings.
 */
export const isModuleBlocked = (
  permissions: string[] | undefined,
  moduleId: number,
  allowedModules?: number[]
): boolean =>
  !!allowedModules &&
  !has(permissions, PERMISSION_TYPES.Admin) &&
  TOGGLEABLE_MODULES.includes(moduleId) &&
  !allowedModules.includes(moduleId);

/**
 * Whether the module (a sidebar item id) is open to these permissions, and
 * to the role's own module list when it has one.
 */
export const canSeeModule = (
  permissions: string[] | undefined,
  moduleId: number,
  allowedModules?: number[]
): boolean => {
  if (!permissions) return false;
  if (has(permissions, PERMISSION_TYPES.Admin)) return true;
  if (isModuleBlocked(permissions, moduleId, allowedModules)) return false;
  return permissions.some((p) => (MODULES_BY_PERMISSION[p] || []).includes(moduleId));
};
