/**
 * Payment requests — stored records as ledger rows, so the Transactions
 * screen (its grid, filters, KPI tiles and the payment schedule derived
 * by `selectors.buildSchedule`) reads live requests through the same
 * `LedgerRow` shape as the mock ledger.
 *
 * Money follows the record's amount lines: the fee is what was charged
 * before deductions (the base plus any surcharge), the adjustments are
 * the deductions, and the invoiced amount is the total, so the KPI
 * identity `invoiced = fee − Σ adjustments` holds. What the payment
 * side wrote back (`paidAmountOf`, see PAYMENT_REQUESTS.md) is collected
 * and settles the schedule oldest line first; the rest splits into what
 * is past its due date and what is still to come.
 */
import { Adjustment, AmountLine, Domain, DunningAlert, LedgerRow } from "../types";
import { DUNNING_META, dunningBucketOf, nextDueOf } from "../selectors";
import { StoredPaymentRequest, paidAmountOf, refundedAmountOf } from "./paymentRequestRecord";

const HOUR = 60 * 60 * 1000;

/**
 * No accounts-payable source exists in the platform yet, so the screens
 * show costs and payables as "coming soon" with no figures. Flip when
 * payouts are recorded and mapped to `side: "ap"` rows.
 */
export const PAYABLES_COMING_SOON = true;

const ADJUSTMENT_TYPE: Partial<Record<AmountLine["key"], Adjustment["type"]>> = {
  earlyBird: "earlybird",
  sibling: "sibling",
  promo: "promo",
  waiver: "waiver",
  scholarship: "scholarship",
};

/** The deductions among the amount lines, as the ledger's positive adjustments. */
export const adjustmentsOf = (lines: AmountLine[]): Adjustment[] =>
  lines
    .filter((line) => line.amount < 0)
    .map((line) => {
      const type = ADJUSTMENT_TYPE[line.key];
      return type ? { type, label: line.label, amount: -line.amount } : null;
    })
    .filter((adjustment): adjustment is Adjustment => adjustment !== null);

/** Records never delivered, or withdrawn (`void`), have invoiced nothing and stay off the ledger. */
export const isLedgerVisible = (record: StoredPaymentRequest): boolean =>
  record.delivery !== "failed" && record.paymentStatus !== "void";

/** One record as a ledger row, or null when it does not belong on the ledger. */
export const toLedgerRow = (record: StoredPaymentRequest, now: number): LedgerRow | null => {
  if (!isLedgerVisible(record)) return null;

  const lines = record.amount.lines || [];
  const total = record.amount.total;
  const serviceFee = lines.filter((line) => line.amount >= 0).reduce((acc, line) => acc + line.amount, 0);
  const adjustments = adjustmentsOf(lines);
  const config = record.config.snapshot;

  /*
   * What was paid settles the schedule oldest line first; whatever is
   * left of a line is past due when its date has gone, still to come
   * otherwise. Lines without a date are due at once.
   */
  const collected = paidAmountOf(record);
  const dueAtOf = (line: { dueAt: number | null }) => (line.dueAt === null ? now : line.dueAt);
  const ordered = record.schedule.slice().sort((a, b) => dueAtOf(a) - dueAtOf(b));
  let credit = collected;
  let pastDue = 0;
  let earliestOverdue: number | null = null;
  let nextDueAt: number | null = null;
  ordered.forEach((line) => {
    const settled = Math.min(credit, line.amount);
    credit -= settled;
    const unpaid = line.amount - settled;
    if (unpaid <= 0) return;
    if (line.dueAt !== null && line.dueAt < now) {
      pastDue += unpaid;
      if (earliestOverdue === null || line.dueAt < earliestOverdue) earliestOverdue = line.dueAt;
    } else if (nextDueAt === null || dueAtOf(line) < nextDueAt) {
      nextDueAt = dueAtOf(line);
    }
  });
  pastDue = Math.min(pastDue, Math.max(0, total - collected));
  const outstanding = Math.max(0, total - collected - pastDue);

  const refunded = refundedAmountOf(record);
  const lastFailure = (record.payments || []).filter((entry) => entry.status === "failed").pop();
  const flags: LedgerRow["flags"] =
    record.paymentStatus === "failed"
      ? [{ kind: "card-decline", note: (lastFailure && lastFailure.failureReason) || "The last payment attempt failed" }]
      : [];

  const method: LedgerRow["method"] =
    config.planType === "recurring"
      ? "scheduled"
      : config.upfront.installments.enabled || config.upfront.deposit.enabled
      ? "installment"
      : "upfront";

  return {
    key: `pr-${record._id}`,
    side: "ar",
    projectId: record.project ? record.project.id : `user:${record.recipient.userId}`,
    project: record.project ? record.project.name : record.subject,
    projectKind: record.project ? record.project.kind : "Direct request",
    entityId: record.recipient.userId,
    entity: record.recipient.name,
    entityRole: record.recipient.role,
    currency: record.amount.currency,
    serviceFee,
    cadence: config.planType === "recurring" ? "recurring" : "one-time",
    adjustments,
    invoicedServiceFee: total,
    form: record.config.collectionMethod,
    method,
    invoiceId: `PR-${record.requestId.slice(0, 8).toUpperCase()}`,
    collected,
    outstanding,
    pastDue,
    pastDueHours: earliestOverdue === null ? 0 : Math.max(0, Math.round((now - earliestOverdue) / HOUR)),
    refund:
      refunded > 0
        ? { amount: refunded, reason: "cancellation", retainedFee: 0, at: record.lastPaymentAt || record.updatedAt }
        : null,
    flags,
    lastActivityAt: record.lastPaymentAt || record.sentAt || record.createdAt,
    nextDueAt: outstanding > 0 ? nextDueAt : null,
  };
};

/**
 * The alert feed the Reports screen and the Transactions "notify" path
 * read, derived from the rows: an overdue row raises an alert in its
 * dunning bucket, a row due within 72 hours raises an upcoming one.
 * `buildSchedule` skips alerts a row already covers, so these never add
 * schedule items; they exist for the alert centre.
 */
export const alertsFromRows = (rows: LedgerRow[], now: number): DunningAlert[] => {
  const alerts: DunningAlert[] = [];
  rows
    .filter((row) => row.side === "ar")
    .forEach((row) => {
      if (row.pastDue > 0) {
        const bucket = dunningBucketOf(row.pastDueHours);
        alerts.push({
          id: `${row.key}-${bucket}`,
          bucket,
          title: DUNNING_META[bucket].label,
          entity: row.entity,
          project: row.project,
          projectId: row.projectId,
          amount: row.pastDue,
          currency: row.currency,
          dueAt: now - row.pastDueHours * HOUR,
        });
      }
      const next = nextDueOf(row);
      if (next !== null && next >= now && next - now <= 72 * HOUR && row.outstanding > 0) {
        alerts.push({
          id: `${row.key}-T-72h`,
          bucket: "T-72h",
          title: DUNNING_META["T-72h"].label,
          entity: row.entity,
          project: row.project,
          projectId: row.projectId,
          amount: row.outstanding,
          currency: row.currency,
          dueAt: next,
        });
      }
    });
  return alerts.sort((a, b) => a.dueAt - b.dueAt);
};

/** The currency most rows carry; the screens format every figure in it. */
export const currencyOf = (rows: LedgerRow[], fallback = "USD"): string => {
  const counts = new Map<string, number>();
  rows.forEach((row) => counts.set(row.currency, (counts.get(row.currency) || 0) + 1));
  let best = fallback;
  let bestCount = 0;
  counts.forEach((count, currency) => {
    if (count > bestCount) {
      best = currency;
      bestCount = count;
    }
  });
  return best;
};

/** The ledger rows of a domain's records. */
export const ledgerRowsFor = (records: StoredPaymentRequest[], domain: Domain, now: number): LedgerRow[] =>
  records
    .filter((record) => record.domain === domain)
    .map((record) => toLedgerRow(record, now))
    .filter((row): row is LedgerRow => row !== null);
