import React, { FC } from "react";
import { Card } from "antd";
import { TanfStat, TanfStatsResult } from "./tanfStats";

interface TanfOutcomeStatsProps {
    stats: TanfStatsResult;
    /** The date range the dated groups are showing, for example "Oct 4, 2026 - Nov 4, 2026". */
    rangeLabel: string;
}

const formatValue = (stat: TanfStat, value: number): string =>
    stat.format === "currency" ? `$${value.toFixed(2)}` : value.toLocaleString();

const StatTile: FC<{ stat: TanfStat; totalClients: number }> = ({ stat, totalClients }) => {
    const { value } = stat;
    const showShare = value !== null && stat.countsClients && totalClients > 0;

    return (
        <div className="tanf-stat-tile">
            {value === null ? (
                <div className="tanf-stat-untracked">Not tracked yet</div>
            ) : (
                <div className="tanf-stat-value">{formatValue(stat, value)}</div>
            )}
            <div className="tanf-stat-label">{stat.label}</div>
            {showShare && (
                <div className="tanf-stat-share">
                    {Math.round(((value as number) / totalClients) * 100)}% of TANF clients
                </div>
            )}
        </div>
    );
};

const TanfOutcomeStats: FC<TanfOutcomeStatsProps> = ({ stats, rangeLabel }) => (
    <Card className="summary-card tanf-outcomes-card">
        <div className="tanf-outcomes-header">
            <h3>TANF Outcomes</h3>
            <p>{stats.totalClients.toLocaleString()} TANF clients</p>
            <p className="tanf-outcomes-hint">
                Groups showing a date follow the date filter. "All time" groups are current totals.
            </p>
        </div>

        {stats.groups.map(group => (
            <section key={group.key} className="tanf-stat-group">
                <div className="tanf-stat-group-header">
                    <h4>{group.title}</h4>
                    <span className={`tanf-stat-scope tanf-stat-scope-${group.scope}`}>
                        {group.scope === "selectedRange" ? rangeLabel : "All time"}
                    </span>
                </div>
                <div className="tanf-stat-grid">
                    {group.stats.map(stat => (
                        <StatTile key={stat.key} stat={stat} totalClients={stats.totalClients} />
                    ))}
                </div>
                {group.note && <p className="tanf-stat-note">{group.note}</p>}
            </section>
        ))}
    </Card>
);

export default TanfOutcomeStats;
